aiohttp/__init__.py:
"""A small stand-in for aiohttp, so Energy Pilot's core runs unchanged inside the app.

In the app (Pyodide) requests go through the browser's fetch - and in the native app through native HTTP, so
the manufacturers' APIs can be reached without CORS limits. On a normal Python (tests) urllib is used.
Only what Energy Pilot uses is here: ClientSession.get/post with params, headers, json and timeout.
"""

from __future__ import annotations

import asyncio
import enum
import json as _json
import sys
from typing import Any
from urllib.parse import urlencode

from . import web  # noqa: F401  (aiohttp.web)

IN_BROWSER = sys.platform == "emscripten"


class ClientError(Exception):
    pass


class ClientConnectionError(ClientError):
    pass


class ClientResponseError(ClientError):
    def __init__(self, status: int, message: str = "") -> None:
        super().__init__(f"{status} {message}".strip())
        self.status = status
        self.message = message


class ClientTimeout:
    def __init__(self, total: float | None = None, **_: Any) -> None:
        self.total = total


class WSMsgType(enum.IntEnum):
    TEXT = 1
    BINARY = 2
    CLOSED = 8


class ClientWebSocketResponse:  # only used as a type hint
    pass


class ClientResponse:
    def __init__(self, status: int, body: bytes, headers: dict[str, str] | None = None) -> None:
        self.status = status
        self._body = body
        self.headers = headers or {}

    async def read(self) -> bytes:
        return self._body

    async def text(self, encoding: str = "utf-8") -> str:
        return self._body.decode(encoding, errors="replace")

    async def json(self, content_type: Any = None, **_: Any) -> Any:
        return _json.loads(self._body.decode("utf-8") or "null")

    def raise_for_status(self) -> None:
        if self.status >= 400:
            raise ClientResponseError(self.status)

    def release(self) -> None:
        pass


class _RequestContext:
    def __init__(self, coro: Any) -> None:
        self._coro = coro
        self._resp: ClientResponse | None = None

    def __await__(self):
        return self._coro.__await__()

    async def __aenter__(self) -> ClientResponse:
        self._resp = await self._coro
        return self._resp

    async def __aexit__(self, *exc: Any) -> None:
        return None


def _timeout_s(timeout: Any) -> float:
    if isinstance(timeout, ClientTimeout):
        return float(timeout.total or 60)
    if isinstance(timeout, (int, float)):
        return float(timeout)
    return 60.0


async def _browser_fetch(method: str, url: str, headers: dict[str, str], body: bytes | None, timeout: float) -> ClientResponse:
    from pyodide.http import pyfetch  # type: ignore

    kwargs: dict[str, Any] = {"method": method, "headers": headers}
    if body is not None:
        kwargs["body"] = body.decode("utf-8")
    try:
        r = await asyncio.wait_for(pyfetch(url, **kwargs), timeout)
        data = await r.bytes()
    except asyncio.TimeoutError as err:
        raise ClientConnectionError("timeout") from err
    except Exception as err:  # noqa: BLE001 - network refused, CORS, offline
        raise ClientConnectionError(str(err)) from err
    return ClientResponse(r.status, data)


async def _urllib_fetch(method: str, url: str, headers: dict[str, str], body: bytes | None, timeout: float) -> ClientResponse:
    import urllib.error
    import urllib.request

    def go() -> ClientResponse:
        req = urllib.request.Request(url, data=body, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:  # noqa: S310
                return ClientResponse(r.status, r.read(), dict(r.headers))
        except urllib.error.HTTPError as err:
            return ClientResponse(err.code, err.read() or b"")
        except Exception as err:  # noqa: BLE001
            raise ClientConnectionError(str(err)) from err

    return await asyncio.to_thread(go)


class ClientSession:
    def __init__(self, *_: Any, headers: dict[str, str] | None = None, **__: Any) -> None:
        self._headers = dict(headers or {})
        self.closed = False

    async def __aenter__(self) -> "ClientSession":
        return self

    async def __aexit__(self, *exc: Any) -> None:
        await self.close()

    async def close(self) -> None:
        self.closed = True

    def request(self, method: str, url: str, *, params: dict[str, Any] | None = None, headers: dict[str, str] | None = None,
                json: Any = None, data: Any = None, timeout: Any = None, **_: Any) -> _RequestContext:
        if params:
            url = url + ("&" if "?" in url else "?") + urlencode({k: v for k, v in params.items() if v is not None})
        h = {**self._headers, **(headers or {})}
        body = None
        if json is not None:
            body = _json.dumps(json).encode()
            h.setdefault("Content-Type", "application/json")
        elif data is not None:
            body = data if isinstance(data, bytes) else str(data).encode()
        fetch = _browser_fetch if IN_BROWSER else _urllib_fetch
        return _RequestContext(fetch(method.upper(), url, h, body, _timeout_s(timeout)))

    def get(self, url: str, **kw: Any) -> _RequestContext:
        return self.request("GET", url, **kw)

    def post(self, url: str, **kw: Any) -> _RequestContext:
        return self.request("POST", url, **kw)

    def put(self, url: str, **kw: Any) -> _RequestContext:
        return self.request("PUT", url, **kw)

    def ws_connect(self, *_: Any, **__: Any) -> Any:
        raise ClientConnectionError("websockets are not used in the app")

aiohttp/web.py:
"""A stand-in for aiohttp.web: the panel's API handlers in web.py are called directly by the app."""

from __future__ import annotations

import json as _json
from pathlib import Path
from typing import Any, Awaitable, Callable

Handler = Callable[["Request"], Awaitable["Response"]]


class Request:
    def __init__(self, method: str, path: str, query: dict[str, str] | None = None, body: bytes | None = None,
                 headers: dict[str, str] | None = None) -> None:
        self.method = method.upper()
        self.path = path
        self.query = dict(query or {})
        self.headers = dict(headers or {})
        self._body = body or b""

    @property
    def can_read_body(self) -> bool:
        return bool(self._body)

    @property
    def body_exists(self) -> bool:
        return bool(self._body)

    async def json(self) -> Any:
        return _json.loads(self._body.decode("utf-8") or "null")

    async def text(self) -> str:
        return self._body.decode("utf-8")

    async def read(self) -> bytes:
        return self._body


class Response:
    def __init__(self, *, body: bytes | str | None = None, text: str | None = None, status: int = 200,
                 content_type: str | None = None, headers: dict[str, str] | None = None) -> None:
        if text is not None:
            body = text
        self.body = body.encode() if isinstance(body, str) else (body or b"")
        self.status = status
        self.content_type = content_type or "text/plain"
        self.headers = dict(headers or {})
        if content_type:
            self.headers.setdefault("Content-Type", content_type)

    @property
    def text(self) -> str:
        return self.body.decode("utf-8", errors="replace")


def json_response(data: Any = None, *, status: int = 200, dumps: Callable[[Any], str] = _json.dumps, **kw: Any) -> Response:
    return Response(text=dumps(data), status=status, content_type="application/json", headers=kw.get("headers"))


class FileResponse(Response):
    def __init__(self, path: str | Path, **kw: Any) -> None:
        p = Path(path)
        try:
            data = p.read_bytes()
            status = 200
        except OSError:
            data, status = b"", 404
        ct = "text/html" if p.suffix == ".html" else "application/javascript" if p.suffix == ".js" else "application/octet-stream"
        super().__init__(body=data, status=status, content_type=ct, headers=kw.get("headers"))


class HTTPException(Exception):
    status = 500


class HTTPNotFound(HTTPException):
    status = 404


class HTTPBadRequest(HTTPException):
    status = 400


class _Router:
    def __init__(self) -> None:
        self.routes: dict[tuple[str, str], Handler] = {}

    def add_get(self, path: str, handler: Handler, **_: Any) -> None:
        self.routes[("GET", path)] = handler

    def add_post(self, path: str, handler: Handler, **_: Any) -> None:
        self.routes[("POST", path)] = handler

    def add_static(self, *_: Any, **__: Any) -> None:
        pass  # the app serves its own files


class Application(dict):
    def __init__(self, **_: Any) -> None:
        super().__init__()
        self.router = _Router()

    async def handle(self, req: Request) -> Response:
        handler = self.router.routes.get((req.method, req.path))
        if handler is None:
            return json_response({"error": "not found", "path": req.path}, status=404)
        try:
            return await handler(req)
        except HTTPException as err:
            return json_response({"error": type(err).__name__}, status=err.status)


class AppRunner:  # main.py's server is not used in the app
    def __init__(self, *_: Any, **__: Any) -> None:
        pass

    async def setup(self) -> None:
        pass


class TCPSite:
    def __init__(self, *_: Any, **__: Any) -> None:
        pass

    async def start(self) -> None:
        pass

energy_pilot/autofix.py:
"""Mistakes Energy Pilot mends by itself - only ones that can't cost money or harm anything: they change how a value
is read, or make Energy Pilot more careful. Each is shown as one line with an undo.

- The main fuse written in amps (75) where kW was asked: set to what that fuse carries (a bit under, to be safe).
- A battery level given as 0-1 instead of 0-100.
- A power sensor in kW without saying so (3.2 where 3200 W was meant).
- A price in øre/cents instead of kroner/euros.
- A chosen sensor that disappeared (an integration renamed it): the one found in its place is used.
- A chosen grid or house power sensor stuck for hours, or unavailable: another that works is used.

Anything that steers the inverter or the charger is never changed here.
"""

from __future__ import annotations

from collections import deque
import statistics
import time
from typing import Any

POWER_ROLES = ("pv_power", "battery_power", "grid_power", "house_power", "ev_power")
STUCK_ROLES = ("grid_power", "house_power")  # these never sit still for hours in a lived-in house
ONE_PHASE = {"GB", "IE", "US", "CA", "AU", "NZ", "JP", "MX", "PH"}  # houses mostly on one phase
STUCK_S = 6 * 3600
GONE_S = 30 * 60


def _f(v: Any) -> float | None:
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


class AutoFix:
    def __init__(self, overview: Any) -> None:
        self.ov = overview
        self.samples: dict[str, deque] = {}
        self.gone_since: dict[str, float] = {}

    @property
    def log(self) -> list[dict[str, Any]]:
        return list(self.ov.settings.get("autofix_log") or [])

    def _ignored(self, key: str) -> bool:
        return key in (self.ov.settings.get("autofix_ignore") or [])

    def _done(self, key: str, what: str, old: Any, new: Any, change: dict[str, Any]) -> None:
        entry = {"key": key, "what": what, "from": old, "to": new, "t": time.time()}
        self.ov.save({**change, "autofix_log": ([e for e in self.log if e["key"] != key] + [entry])[-20:]})
        tel = getattr(self.ov, "telemetry", None)
        if tel:
            tel.mended(key, what)

    def undo(self, key: str) -> None:
        e = next((x for x in self.log if x["key"] == key), None)
        if not e:
            return
        s = self.ov.settings
        change: dict[str, Any] = {}
        if e["what"] == "fuse":
            change["import_limit_kw"] = e["from"]
        elif e["what"] in ("soc_scale", "kw_scale"):
            role = key.split(":", 1)[1]
            change["role_scale"] = {k: v for k, v in (s.get("role_scale") or {}).items() if k != role}
        elif e["what"] == "price_scale":
            change["price_scale"] = None
        elif e["what"] in ("renamed", "stuck"):
            role = key.split(":", 1)[1]
            change["roles"] = {**(s.get("roles") or {}), role: e["from"]}
        self.ov.save({**change, "autofix_log": [x for x in self.log if x["key"] != key],
                      "autofix_ignore": list(dict.fromkeys((s.get("autofix_ignore") or []) + [key]))})

    # ---------- every minute ----------
    def run(self) -> None:
        st = self.ov.ha.states
        now = time.time()
        roles = self.ov.roles()
        for r in POWER_ROLES + ("battery_soc",):
            v = _f((st.get(roles.get(r) or "") or {}).get("state"))
            if v is not None:
                self.samples.setdefault(r, deque(maxlen=90)).append(v)
        self.fuse()
        self.soc_scale(roles)
        self.kw_scale(roles)
        self.price_scale()
        self.renamed(st, now)
        self.stuck(st, roles, now)

    def fuse(self) -> None:
        v = _f(self.ov.settings.get("import_limit_kw"))
        if v is None or v <= 50 or self._ignored("fuse"):
            return
        country = str(self.ov.ha.config.get("country") or "").upper()
        phases = 1 if country in ONE_PHASE else 3
        kw = max(3, round(v * 0.23 * phases * 0.92))  # amps × 230 V × phases, a little under the fuse
        self._done("fuse", "fuse", v, kw, {"import_limit_kw": kw})

    def soc_scale(self, roles: dict[str, Any]) -> None:
        key = "soc:battery_soc"
        s = self.samples.get("battery_soc") or []
        if len(s) < 30 or self._ignored(key) or (self.ov.settings.get("role_scale") or {}).get("battery_soc"):
            return
        if max(s) <= 1.0 and any(0.02 < x < 0.98 for x in s):
            self._done(key, "soc_scale", 1, 100, {"role_scale": {**(self.ov.settings.get("role_scale") or {}), "battery_soc": 100}})

    def kw_scale(self, roles: dict[str, Any]) -> None:
        """A power sensor whose numbers are kW-sized while the others are in watts, and that doesn't say kW."""
        scale = self.ov.settings.get("role_scale") or {}
        big = [r for r in POWER_ROLES if (s := self.samples.get(r)) and len(s) >= 30 and max(abs(x) for x in s) > 300]
        if not big:
            return
        for r in POWER_ROLES:
            key = f"kw:{r}"
            s = self.samples.get(r) or []
            e = roles.get(r)
            unit = str(((self.ov.ha.states.get(e or "") or {}).get("attributes") or {}).get("unit_of_measurement") or "").lower()
            if len(s) < 60 or r in big or scale.get(r) or self._ignored(key) or unit == "kw":
                continue
            moving = [x for x in s if abs(x) >= 0.2]
            if len(moving) >= 20 and max(abs(x) for x in s) <= 30 and any(abs(x - round(x)) > 0.01 for x in moving):
                self._done(key, "kw_scale", 1, 1000, {"role_scale": {**scale, r: 1000}})

    def price_scale(self) -> None:
        key = "price"
        if self._ignored(key) or self.ov.settings.get("price_scale"):
            return
        prices = list((getattr(self.ov, "fine_prices", None) or {}).values())
        if len(prices) < 12:
            return
        cur = str(self.ov.ha.config.get("currency") or "").upper()
        limit = 20 if cur in ("DKK", "SEK", "NOK") else 5  # never seen in a whole day of real prices
        if statistics.median(prices) > limit:
            self._done(key, "price_scale", 1, 0.01, {"price_scale": 0.01})

    def renamed(self, st: dict[str, Any], now: float) -> None:
        chosen = self.ov.settings.get("roles") or {}
        for role, e in chosen.items():
            if not isinstance(e, str) or not e or e in st:
                self.gone_since.pop(f"renamed:{role}", None)
                continue
            key = f"renamed:{role}"
            since = self.gone_since.setdefault(key, now)
            found = self.ov.role(role)  # the one found in its place
            if now - since >= GONE_S and found and found != e and not self._ignored(key):
                self._done(key, "renamed", e, found, {"roles": {**chosen, role: found}})

    def stuck(self, st: dict[str, Any], roles: dict[str, Any], now: float) -> None:
        from datetime import datetime

        chosen = self.ov.settings.get("roles") or {}
        for role in STUCK_ROLES:
            e = roles.get(role)
            key = f"stuck:{role}"
            if not e or self._ignored(key) or chosen.get(role) != e:
                continue  # only the user's own choice is swapped - a found one changes by itself
            s = st.get(e) or {}
            try:
                age = now - datetime.fromisoformat(str(s.get("last_changed"))).timestamp()
            except ValueError:
                continue
            bad = s.get("state") in ("unavailable", "unknown") and age > GONE_S or age > STUCK_S
            if not bad:
                continue
            alt = self._alternative(role, e, st, now)
            if alt:
                self._done(key, "stuck", e, alt, {"roles": {**chosen, role: alt}})

    def _alternative(self, role: str, bad: str, st: dict[str, Any], now: float) -> str | None:
        from datetime import datetime

        for c in (self.ov.candidates().get(role) or []):
            e = c.get("entity_id")
            if not e or e == bad or not c.get("guess"):
                continue
            s = st.get(e) or {}
            try:
                fresh = now - datetime.fromisoformat(str(s.get("last_changed"))).timestamp() < 3600
            except ValueError:
                continue
            if fresh and _f(s.get("state")) is not None:
                return e
        return None

    def lines(self) -> list[dict[str, Any]]:
        """For the page: what was mended, newest first."""
        return sorted(self.log, key=lambda e: -e["t"])

energy_pilot/batteries.py:
"""More than one home battery (a SolarEdge/BYD and a Victron, say).

The plan sees them as one battery - the capacities and powers added up, the level weighted by size. That keeps the
plan fast and is close to right; how the work is shared between them is the controller's job (shadow only for now).
Battery 1 is the one set up as before (its sensors under "What you have"); the others live in settings["batteries"].
"""

from __future__ import annotations

import re
from typing import Any

SOC_WORDS = ("state_of_charge", "state_of_energy", "battery_soc", "_soc", "battery_level")
NOT_A_HOME_BATTERY = ("phone", "iphone", "pixel", "ipad", "tablet", "watch", "laptop", "macbook", "car_", "_car", "tesla_model",
                      "vehicle", "ev_", "remote", "button", "sensor_battery", "mower", "vacuum", "roborock", "12v", "12_v",
                      # settings, not a level: "Home Minimum State of Charge", reserve, target, limits
                      "minimum", "maximum", "_min_", "_max_", "min_soc", "max_soc", "reserve", "target", "limit", "setpoint",
                      "cutoff", "cut_off", "backup", "discharge_depth", "end_of_discharge")


def extras(settings: dict[str, Any]) -> list[dict[str, Any]]:
    """The extra batteries that are set up (with at least a level sensor)."""
    return [b for b in (settings.get("batteries") or []) if isinstance(b, dict) and b.get("soc")]


def _num(s: dict[str, Any] | None) -> float | None:
    try:
        return float((s or {}).get("state"))
    except (TypeError, ValueError):
        return None


def _watts(s: dict[str, Any] | None) -> float | None:
    v = _num(s)
    if v is None:
        return None
    unit = str(((s or {}).get("attributes") or {}).get("unit_of_measurement") or "").lower()
    return v * 1000 if unit == "kw" else v


def read(states: dict[str, Any], b: dict[str, Any]) -> dict[str, Any]:
    """One extra battery now: level (%), power (W, + = charging) and size."""
    w = _watts(states.get(b["power"])) if b.get("power") else None
    if w is not None and b.get("sign") == -1:
        w = -w
    return {"name": b.get("name") or "", "soc": _num(states.get(b["soc"])), "power": w, "kwh": float(b.get("kwh") or 10)}


def combine(main: dict[str, Any], others: list[dict[str, Any]]) -> tuple[float | None, float | None]:
    """The level weighted by size, the powers added up. A battery that can't be read leaves the level unknown."""
    all_ = [main] + others
    if any(x["soc"] is None for x in all_):
        soc = None
    else:
        total = sum(x["kwh"] for x in all_)
        soc = round(sum(x["soc"] * x["kwh"] for x in all_) / total, 1) if total else None
    ws = [x["power"] for x in all_ if x["power"] is not None]
    return soc, (sum(ws) if ws else None)


def _prefix(entity: str) -> str:
    obj = entity.split(".", 1)[1]
    for w in SOC_WORDS:
        if w in obj:
            return obj.split(w)[0].rstrip("_")
    return obj


def _device(entity: str) -> str:
    """The first word of the name - what usually tells one inverter or battery from another."""
    return re.split(r"[_.]", entity.split(".", 1)[1])[0]


def find(states: dict[str, Any], main_soc: str | None, taken: list[str], dismissed: list[str],
         phones: set[str] | frozenset[str] = frozenset()) -> list[dict[str, Any]]:
    """Batteries in Home Assistant that aren't set up: a level sensor on another device than battery 1,
    with the battery power sensor beside it when there is one."""
    seen_devices = {_device(main_soc)} if main_soc else set()
    seen_devices |= {_device(e) for e in taken if e}
    out = []
    for e, s in sorted(states.items()):
        if not e.startswith("sensor.") or e in taken or e in dismissed or e == main_soc or e in phones:
            continue  # the companion app's phone battery is never a home battery
        a = s.get("attributes") or {}
        obj = e.split(".", 1)[1]
        if not any(w in obj for w in SOC_WORDS) or any(w in obj for w in NOT_A_HOME_BATTERY):
            continue
        if str(a.get("unit_of_measurement") or "") != "%" or a.get("device_class") not in ("battery", None):
            continue
        if _num(s) is None or _device(e) in seen_devices:
            continue
        pre = _prefix(e)
        power = None
        best = 0
        for p, ps in states.items():
            pa = ps.get("attributes") or {}
            if not p.startswith("sensor.") or "batter" not in p or _device(p) != _device(e):
                continue
            if str(pa.get("unit_of_measurement") or "").lower() not in ("w", "kw"):
                continue
            pobj = p.split(".", 1)[1]
            common = len(pre) if pobj.startswith(pre) else len(_device(e))
            if "power" in pobj and common > best:
                power, best = p, common
        if power is None and not any(w in obj for w in ("state_of_charge", "state_of_energy", "_soc")):
            continue  # "battery_level" without a battery power beside it: a phone or a tablet, not a home battery
        out.append({"soc": e, "power": power, "name": a.get("friendly_name") or e})
        seen_devices.add(_device(e))  # one battery per device
    return out

energy_pilot/batterytype.py:
"""What kind of battery it is - and so what a kWh through it wears it, how low it may go and how efficient it is.

Found by itself, from what Home Assistant already knows: the inverter's own "battery type" setting (Deye, Growatt,
Victron, Solis …), the battery's model (BYD, Pylontech … are LFP; Powerwall 2 and LG RESU are NMC), a cycle rating the
integration shows, and - last - a learned efficiency under 85 % (lead). Otherwise LFP, the common one.
The user can pick the type, say what the battery cost, or set the wear outright (Advanced).
"""

from __future__ import annotations

import re
from typing import Any

# cycles to end of life, the lowest level it likes, round-trip efficiency, a typical price per kWh (DKK)
TYPES: dict[str, dict[str, float]] = {
    "lfp": {"cycles": 6000, "min_soc": 10, "eff": 0.95, "price_dkk": 1600},
    "nmc": {"cycles": 3500, "min_soc": 10, "eff": 0.93, "price_dkk": 2500},
    "sodium": {"cycles": 4000, "min_soc": 10, "eff": 0.92, "price_dkk": 1200},
    "lead": {"cycles": 1000, "min_soc": 50, "eff": 0.80, "price_dkk": 1000},
}
# DKK per unit of each currency (rounded - only for the typical battery price)
DKK_PER = {"DKK": 1, "EUR": 7.46, "GBP": 8.7, "NOK": 0.65, "SEK": 0.66, "USD": 6.9, "AUD": 4.5, "NZD": 4.1, "CAD": 5.0,
           "PLN": 1.73, "CHF": 7.9, "CZK": 0.3, "HUF": 0.019}

_LEAD = r"lead|agm|gel|flooded|bly|blei|plomb|opzv|opzs|\bpb\b"
_LFP = r"lithium|lifepo|lfp|li-?ion|\bli\b"
MODELS = [  # the battery's or inverter's model name -> type (first match wins)
    (r"powerwall ?3", "lfp"),
    (r"powerwall|resu|lg ?chem|tesla", "nmc"),
    (r"byd|pylontech|growatt ?ark|apx|luna|sigen|alpha ?ess|seplos|jk ?bms|eve|lifepo|dyness|weco|sofar ?amass|"
     r"solax ?triple|huawei|givenergy|fox ?ess|mira|ecoflow|anker|zendure|marstek", "lfp"),
    (r"sodium|natrium|na-?ion", "sodium"),
]


def detect(states: dict[str, Any], model: str | None, soc_entity: str | None, learned_eff: float | None,
           eff_seen: int = 0) -> dict[str, Any]:
    """{"type": "lfp" …, "why": "inverter"/"model"/"efficiency"/"default", "cycles": n or None}."""
    cycles = None
    if soc_entity:
        a = (states.get(soc_entity) or {}).get("attributes") or {}
        for k, v in a.items():
            if "cycle" in str(k).lower() and "rating" in str(k).lower():
                try:
                    cycles = int(float(v))
                except (TypeError, ValueError):
                    pass
    for e, s in states.items():
        if e.split(".")[0] in ("select", "sensor") and re.search(r"battery_?type|batterietyp|type_de_batterie", e):
            st = str((s or {}).get("state") or "").lower()
            if re.search(_LEAD, st):
                return {"type": "lead", "why": "inverter", "cycles": cycles}
            if re.search(_LFP, st):
                return {"type": "lfp", "why": "inverter", "cycles": cycles}
    text = (model or "").lower()
    for pat, t in MODELS:
        if text and re.search(pat, text):
            return {"type": t, "why": "model", "cycles": cycles}
    if learned_eff is not None and eff_seen >= 3 and learned_eff < 0.85:
        return {"type": "lead", "why": "efficiency", "cycles": cycles}
    return {"type": "lfp", "why": "default" if cycles is None else "model", "cycles": cycles}


def wear(kind: str, currency: str, capacity_kwh: float | None = None, price: float | None = None,
         cycles: int | None = None) -> float:
    """Money per kWh into or out of the battery: its price over every kWh it will move in its life (both ways)."""
    t = TYPES.get(kind) or TYPES["lfp"]
    n = cycles or t["cycles"]
    if price and capacity_kwh:
        per_kwh = price / capacity_kwh  # what the user paid
    else:
        per_kwh = t["price_dkk"] / DKK_PER.get(currency.upper(), 7.46)
    return round(per_kwh / (n * 2), 3)

energy_pilot/battstats.py:
"""The battery's own story, measured every half minute: the level hour by hour for the week that went, the longest
time the house went without buying from the grid, and how many evenings in a row the battery lasted.

Only what was really seen counts - a gap (a restart) ends a run rather than bridging it.
"""

from __future__ import annotations

import json
from datetime import datetime, timedelta
from pathlib import Path
from typing import Any

BUY_W = 80  # buying less than this counts as "without the grid" (meters drift a little)
BLIP_S = 120  # the kettle may pull from the grid this long without ending a run
GAP_S = 300  # a longer gap between readings (a restart) ends a run
EVENING = range(17, 22)  # the evening the battery should last through


class BattStats:
    def __init__(self, data_dir: Path) -> None:
        self.file = data_dir / "energy_pilot_battstats.json"
        self.state: dict[str, Any] = {"hours": {}, "best": None, "evenings": {}}
        try:
            self.state.update(json.loads(self.file.read_text()))
        except (OSError, ValueError):
            pass
        self._at: datetime | None = None
        self._run_from: datetime | None = None
        self._buy_since: datetime | None = None
        self._saved = 0.0

    def save(self) -> None:
        try:
            self.file.write_text(json.dumps(self.state))
        except OSError:
            pass

    def tick(self, now: datetime, flow: dict[str, Any], min_soc: float) -> None:
        prev, self._at = self._at, now
        s, soc, grid = self.state, flow.get("soc"), flow.get("grid")
        if soc is not None:
            k = now.strftime("%Y-%m-%dT%H")
            a = s["hours"].setdefault(k, [0.0, 0])
            a[0] += float(soc)
            a[1] += 1
            day = now.date().isoformat()
            if now.hour in EVENING and float(soc) <= min_soc + 1:
                s["evenings"][day] = False  # ran out this evening
            elif now.hour >= EVENING.stop and day not in s["evenings"]:
                s["evenings"][day] = True
        if prev is None or (now - prev).total_seconds() > GAP_S:
            self._run_from = self._buy_since = None
        if grid is not None:
            if float(grid) <= BUY_W:
                self._buy_since = None
                self._run_from = self._run_from or now
            else:
                self._buy_since = self._buy_since or now
                if (now - self._buy_since).total_seconds() > BLIP_S:
                    self._run_from = None
            if self._run_from:
                h = (now - self._run_from).total_seconds() / 3600
                best = s.get("best") or {}
                if h >= 0.5 and h > (best.get("h") or 0):
                    s["best"] = {"h": round(h, 2), "day": self._run_from.date().isoformat()}
        if now.timestamp() - self._saved > 300:
            cut = (now - timedelta(days=8)).strftime("%Y-%m-%dT%H")
            s["hours"] = {k: v for k, v in s["hours"].items() if k >= cut}
            dcut = (now - timedelta(days=60)).date().isoformat()
            s["evenings"] = {k: v for k, v in s["evenings"].items() if k >= dcut}
            self.save()
            self._saved = now.timestamp()

    def streak(self, now: datetime) -> int:
        ev, n = self.state["evenings"], 0
        day = now.date() if now.date().isoformat() in ev else now.date() - timedelta(days=1)
        while ev.get(day.isoformat()) is True:
            n += 1
            day -= timedelta(days=1)
        return n

    def summary(self, now: datetime, min_soc: float) -> dict[str, Any]:
        hours = self.state["hours"]
        week, days = [], []
        for back in range(6, -1, -1):
            d = (now - timedelta(days=back)).date()
            row = []
            for h in range(24):
                v = hours.get(f"{d.isoformat()}T{h:02d}")
                row.append(round(v[0] / v[1]) if v and v[1] else None)
            week.append(row)
            days.append(d.isoformat())
        # a tip from the week: empty most evenings - or never close to it
        full_days = [r for r in week[:-1] if sum(v is not None for v in r) >= 20]
        empties = [next((h for h in range(15, 24) if r[h] is not None and r[h] <= min_soc + 2), None) for r in full_days]
        hit = sorted(h for h in empties if h is not None)
        tip = None
        if len(full_days) >= 4 and len(hit) >= max(3, len(full_days) * 0.6):
            tip = {"kind": "empty_evenings", "from": hit[len(hit) // 2]}
        elif len(full_days) >= 5 and all(min(v for v in r if v is not None) > min_soc + 15 for r in full_days):
            tip = {"kind": "never_low"}
        best = self.state.get("best")
        return {"week": week, "days": days, "best": best, "streak": self.streak(now), "tip": tip,
                "has_week": len(full_days) >= 2}

energy_pilot/blend.py:
"""Two ways of forecasting, blended by how well each one has really hit - simple first, ML as it earns it.

For each thing forecast (house use, sun, tomorrow's prices before they're out) there is a simple way that works from
day one, and an ML model trained every night on the home's own data. Every night both are checked against what
really happened, and the ML model's share moves towards what it has earned:

- it gets nothing until it has enough data (house and sun: three weeks)
- the share follows the two errors (equal errors: half each), and moves a third of the way per night
- if it starts to miss (a new heat pump, a new car), its share goes down again by itself

Learned values (the car's habits, the battery's real efficiency) are blended with the setting or the datasheet in
the same spirit: the more they have seen, the more they count. What the user sets themselves always wins.
"""

from __future__ import annotations

import time

from datetime import datetime, timedelta
import json
import logging
import math
from pathlib import Path
from statistics import median
from typing import Any

from .sources import is_day_off

_LOGGER = logging.getLogger(__name__)
MIN_DAYS = {"house": 21, "sun": 21, "price": 14}
STEP = 1 / 3


class Mixer:
    """The ML share per kind, from the errors measured night by night."""

    def __init__(self, state: dict[str, Any]) -> None:
        self.state = state.setdefault("blend", {})

    def share(self, kind: str) -> float:
        return float((self.state.get(kind) or {}).get("w", 0.0))

    def info(self, kind: str) -> dict[str, Any]:
        return dict(self.state.get(kind) or {"w": 0.0})

    def update(self, kind: str, err_simple: float | None, err_ml: float | None, ml_days: int) -> None:
        s = self.state.setdefault(kind, {"w": 0.0, "simple": None, "ml": None, "days": 0})
        smooth = lambda old, new: new if old is None else round(0.8 * old + 0.2 * new, 4)  # noqa: E731
        if err_simple is not None:
            s["simple"] = smooth(s.get("simple"), err_simple)
        if err_ml is not None:
            s["ml"] = smooth(s.get("ml"), err_ml)
            s["days"] = int(s.get("days", 0)) + 1
        s["ml_days"] = ml_days
        if ml_days < MIN_DAYS[kind] or s.get("ml") is None or s.get("simple") is None:
            target = 0.0
        else:
            a, b = max(1e-6, s["simple"]) ** 2, max(1e-6, s["ml"]) ** 2
            target = a / (a + b)  # equal errors: half each; the better one gets more
        s["w"] = round(s["w"] + STEP * (target - s["w"]), 3)

    @staticmethod
    def mix(simple: float | None, ml: float | None, w: float) -> float | None:
        if ml is None or w <= 0:
            return simple
        if simple is None:
            return ml
        return round((1 - w) * simple + w * ml, 3)


def mae(pairs: list[tuple[float, float]]) -> float | None:
    return round(sum(abs(a - b) for a, b in pairs) / len(pairs), 4) if pairs else None


# ---------- the sun ----------

class SolarModel:
    """kWh per hour from sunlight, cloud, temperature, hour and time of year - this home's panels, shade and all."""

    def __init__(self) -> None:
        self.model: Any = None
        self.days = 0
        self.top = 0.0

    @staticmethod
    def features(when: datetime, w: dict[str, float]) -> list[float]:
        doy = when.timetuple().tm_yday / 365.25 * 2 * math.pi
        return [when.hour, math.sin(doy), math.cos(doy), float(w.get("sun") or 0), float(w.get("cloud") or 0), float(w.get("temp") or 10)]

    def train(self, pv: dict[datetime, float], weather: Any) -> bool:
        X, y, days = [], [], set()
        for when, kw in pv.items():
            w = weather.at(when)
            if not w or w.get("sun") is None or kw is None or kw < 0:
                continue
            if (w.get("sun") or 0) < 5 and kw < 0.05:
                continue  # night
            X.append(self.features(when, w))
            y.append(kw)
            days.add(when.date())
        if len(days) < 7:
            return False
        from . import mlcheck

        if not mlcheck.ok():
            return False
        from sklearn.ensemble import HistGradientBoostingRegressor

        model = HistGradientBoostingRegressor(max_iter=200, learning_rate=0.06, max_depth=4, min_samples_leaf=8)
        model.fit(X, y)
        self.model, self.days, self.top = model, len(days), max(y)
        return True

    def predict(self, hours: list[datetime], weather: Any) -> dict[datetime, float]:
        if self.model is None:
            return {}
        rows = [(h, weather.at(h)) for h in hours]
        rows = [(h, w) for h, w in rows if w and w.get("sun") is not None]
        if not rows:
            return {}
        out = self.model.predict([self.features(h, w) for h, w in rows])
        return {h: (0.0 if (w.get("sun") or 0) < 3 else round(min(self.top * 1.1, max(0.0, float(v))), 3)) for (h, w), v in zip(rows, out)}


# ---------- tomorrow's prices, before they're out ----------

class PriceModel:
    """Tomorrow's prices before they're published (around 13:00): estimated, and replaced when the real ones come.

    Simple: the shape of the last two weeks (per hour, weekday or day off) at the level of the last day.
    ML: hour, weekday, day off, wind, sun and temperature, yesterday's price for the hour and the last day's level.
    """

    def __init__(self, data_dir: Path) -> None:
        self.file = data_dir / "energy_pilot_prices.json"
        self.hist: dict[str, float] = {}
        self.made: dict[str, dict[str, float]] = {}  # forecasts made before the real prices: {hour: {simple, ml}}
        try:
            d = json.loads(self.file.read_text())
            self.hist, self.made = d.get("hist", {}), d.get("made", {})
        except (OSError, ValueError):
            pass
        self.model: Any = None

    def save(self) -> None:
        try:
            self.file.write_text(json.dumps({"hist": self.hist, "made": self.made}))
        except OSError:
            pass

    @staticmethod
    def key(when: datetime) -> str:
        return when.strftime("%Y-%m-%dT%H")

    def remember(self, prices: dict[datetime, float], now: datetime) -> None:
        """Real prices, kept 120 days."""
        changed = False
        for when, p in prices.items():
            if when.minute == 0 or self.key(when) not in self.hist:
                k = self.key(when)
                if self.hist.get(k) != round(p, 4):
                    self.hist[k], changed = round(p, 4), True
        if changed:
            cut = self.key(now - timedelta(days=120))
            self.hist = {k: v for k, v in self.hist.items() if k >= cut}
            self.save()

    def _level(self, before: datetime) -> float | None:
        day = [v for k, v in self.hist.items() if self.key(before - timedelta(hours=24)) <= k < self.key(before)]
        return sum(day) / len(day) if len(day) >= 12 else None

    def simple(self, when: datetime) -> float | None:
        level = self._level(when.replace(hour=0))
        if level is None:
            return None
        off = is_day_off(when.date())
        same, all_ = [], []
        for k, v in self.hist.items():
            t = datetime.fromisoformat(k + ":00")
            if (when.replace(tzinfo=None) - t).days > 14:
                continue
            all_.append(v)
            if t.hour == when.hour and is_day_off(t.date()) == off:
                same.append(v)
        if not same or not all_:
            return None
        return round(level * (sum(same) / len(same)) / max(1e-6, sum(all_) / len(all_)), 4)

    def _features(self, when: datetime, w: dict[str, float] | None) -> list[float] | None:
        y = self.hist.get(self.key(when - timedelta(days=1)))
        level = self._level(when.replace(hour=0))
        if y is None or level is None:
            return None
        w = w or {}
        return [when.hour, when.weekday(), float(is_day_off(when.date())), float(w.get("wind") or 0), float(w.get("sun") or 0),
                float(w.get("temp") or 10), y, level]

    def train(self, weather: Any, tz: Any) -> int:
        X, y, days = [], [], set()
        for k, v in self.hist.items():
            when = datetime.fromisoformat(k + ":00").replace(tzinfo=tz)
            f = self._features(when, weather.at(when) if weather else None)
            if f is not None:
                X.append(f)
                y.append(v)
                days.add(when.date())
        if len(days) < 7:
            return len(days)
        from . import mlcheck

        if not mlcheck.ok():
            return len(days)
        from sklearn.ensemble import HistGradientBoostingRegressor

        self.model = HistGradientBoostingRegressor(max_iter=200, learning_rate=0.06, max_depth=4, min_samples_leaf=6).fit(X, y)
        return len(days)

    def ml(self, when: datetime, weather: Any) -> float | None:
        if self.model is None:
            return None
        f = self._features(when, weather.at(when) if weather else None)
        # Tomorrow: "yesterday" for tomorrow's hours is today - known.
        return round(float(self.model.predict([f])[0]), 4) if f else None

    def estimate(self, hours: list[datetime], weather: Any, share: float) -> dict[datetime, float]:
        out = {}
        for h in hours:
            s, m = self.simple(h), self.ml(h, weather)
            v = Mixer.mix(s, m, share)
            if v is not None:
                out[h] = v
                k = self.key(h)
                if k not in self.hist and k not in self.made:
                    self.made[k] = {"simple": s, "ml": m}
        return out

    def score(self, now: datetime) -> tuple[float | None, float | None]:
        """The forecasts made earlier, against the real prices that came since."""
        ps, pm = [], []
        for k in [k for k in self.made if k in self.hist]:
            f, real = self.made.pop(k), self.hist[k]
            if f.get("simple") is not None:
                ps.append((f["simple"], real))
            if f.get("ml") is not None:
                pm.append((f["ml"], real))
        cut = self.key(now - timedelta(days=3))
        self.made = {k: v for k, v in self.made.items() if k >= cut}
        self.save()
        return mae(ps), mae(pm)


# ---------- the car's habits ----------

class Habits:
    """When the car leaves (per weekday) and how much it takes - learned from plugging in and out."""

    def __init__(self, state: dict[str, Any]) -> None:
        self.s = state.setdefault("habits", {"leave": {}, "need": [], "plug": None, "session": 0.0})

    def see(self, now: datetime, plugged: bool | None, session_kwh: float | None) -> None:
        if plugged is None:
            return
        was = self.s.get("plug")
        if session_kwh is not None:
            self.s["session"] = max(float(self.s.get("session") or 0), session_kwh)
        if was and not plugged:  # left
            lv = self.s["leave"].setdefault(str(now.weekday()), [])
            lv.append(now.hour * 60 + now.minute)
            self.s["leave"][str(now.weekday())] = lv[-8:]
            if self.s.get("session"):
                self.s["need"] = (self.s.get("need") or [])[-19:] + [round(self.s["session"], 1)]
            self.s["session"] = 0.0
        self.s["plug"] = bool(plugged)

    def leave(self, weekday: int) -> tuple[int, int] | None:
        """Usual leaving time (h, m) for the weekday, once it has seen it 4 times."""
        lv = self.s["leave"].get(str(weekday)) or []
        if len(lv) < 4:
            return None
        m = int(median(lv))
        return m // 60, m % 60

    def need(self, setting: float) -> float:
        n = self.s.get("need") or []
        if not n:
            return setting
        w = min(1.0, len(n) / 10)
        return round((1 - w) * setting + w * median(n), 1)

    def info(self) -> dict[str, Any]:
        return {"leave": {d: self.leave(int(d)) for d in self.s["leave"]}, "need_seen": len(self.s.get("need") or [])}


# ---------- the battery's real efficiency ----------

TAPER_BANDS = (98, 95, 90, 85)  # levels where charging is watched on its own (highest first)


class BatteryLearner:
    """The battery's real usable capacity and efficiency - from what goes in and out against what the level shows.

    Each run of charging (or discharging) of at least 10 points is written down as kWh per percent point:
    charging takes capacity/100 / charge-efficiency per point, discharging gives capacity/100 x discharge-efficiency.
    So their ratio is the round trip, and their geometric mean the capacity - neither needs the other to be known.
    Many write the label's kWh (13), while the level only spans what is usable (~11.5); and batteries wear.
    """

    def __init__(self, state: dict[str, Any]) -> None:
        self.s = state.setdefault("battery_learned", {})
        self.s.setdefault("in_pp", [])
        self.s.setdefault("out_pp", [])
        self.s.setdefault("seg", None)

    def see(self, batt_w: float | None, soc: float | None, hours: float, capacity: float | None = None) -> None:
        if batt_w is None or soc is None:
            return
        seg = self.s.get("seg")
        way = "in" if batt_w > 50 else "out" if batt_w < -50 else None
        if seg and way != seg["way"]:
            moved = abs(soc - seg["soc"])
            if moved >= 10 and seg["kwh"] > 0.5:
                per = seg["kwh"] / moved  # kWh per percent point
                if 0.02 <= per <= 1.0:  # 2 - 100 kWh batteries
                    key = seg["way"] + "_pp"
                    self.s[key] = (self.s.get(key) or [])[-19:] + [round(per, 4)]
            seg = None
        if way and seg is None:
            seg = {"way": way, "soc": soc, "kwh": 0.0}
        if seg:
            seg["kwh"] += abs(batt_w) / 1000 * hours
        self.s["seg"] = seg
        if soc >= 99:
            self.s["last_full"] = time.time()  # full: the cells have been balanced
        if batt_w > 300:  # charging: how hard it charges at which level (most batteries slow down when nearly full)
            band = next((b for b in TAPER_BANDS if soc >= b), 0)
            key = str(band)
            self.s.setdefault("charge_w", {})
            self.s["charge_w"][key] = (self.s["charge_w"].get(key) or [])[-59:] + [round(batt_w)]

    def days_since_full(self) -> float:
        """Days since the battery was last full - 0 until it has been watched for a while (no full charge at once)."""
        if "last_full" not in self.s:
            self.s["last_full"] = time.time()
        return (time.time() - float(self.s["last_full"])) / 86400

    def taper(self) -> tuple[tuple[float, float], ...]:
        """How much of its charge power the battery really takes near full, as (from level, share) - learned by
        comparing the hardest charging seen high up with the hardest seen below 85 %. Nothing until it has seen enough."""
        cw = self.s.get("charge_w") or {}
        low = sorted(cw.get("0") or [])
        if len(low) < 20:
            return ()
        ref = low[int(len(low) * 0.9)]
        seen = {}
        for band in sorted(TAPER_BANDS):
            vals = sorted(cw.get(str(band)) or [])
            if len(vals) >= 10:
                seen[band] = max(0.2, min(1.0, vals[int(len(vals) * 0.9)] / ref))
        # A battery never charges faster higher up: what was seen at 90 % it can do at 85 % too. Slow charging that
        # was asked for (the plan's last half hour, a little sun) would otherwise look like a battery that can't.
        out, best = [], 0.0
        for band in sorted(seen, reverse=True):
            best = max(best, seen[band])
            seen[band] = best
        for band in sorted(seen):
            if seen[band] < 0.95:
                out.append((float(band), round(seen[band], 2)))
        return tuple(out)

    def _medians(self) -> tuple[float, float, int] | None:
        a, b = self.s.get("in_pp") or [], self.s.get("out_pp") or []
        if len(a) < 3 or len(b) < 3:
            return None
        return median(a), median(b), min(len(a), len(b))

    def capacity(self) -> float | None:
        """Usable kWh, once it has seen at least three runs each way."""
        m = self._medians()
        if not m:
            return None
        cap = (m[0] * m[1]) ** 0.5 * 100
        return round(cap, 1) if 2 <= cap <= 100 else None

    def efficiency(self, datasheet: float) -> float:
        m = self._medians()
        if not m:
            return datasheet
        learned = min(1.0, max(0.7, m[1] / m[0]))
        w = min(1.0, m[2] / 10)
        return round((1 - w) * datasheet + w * learned, 3)

    def info(self, datasheet: float) -> dict[str, Any]:
        m = self._medians()
        return {"efficiency": self.efficiency(datasheet), "capacity": self.capacity(), "seen": m[2] if m else 0}

energy_pilot/chargers.py:
"""More than one charger (two KEBA boxes, say) - each car planned on its own, all within the main fuse.

Charger 1 is the one set up as before (its sensors under "What you have", its buttons on the car card); the others
live in settings["chargers"]: sensors, charger power, and the car's own "charge now", "ready at" and "at most".
Each extra charger is a part of its own (car2, car3 …): it starts in shadow and is put in control by itself.
Charger 1 comes first: the sun's surplus and the room under the main fuse go to it, the others are turned down first.
"""

from __future__ import annotations

from datetime import datetime, timedelta
import re
from typing import Any

POWER_WORDS = ("charging_power", "charge_power", "charger_power", "wallbox_power", "ladeeffekt")
PLUG_WORDS = ("plugged", "plug", "cable", "stik")
SESSION_WORDS = ("session_energy", "energy_session", "session")


# What a charger's plug sensor says when a car is in it - a binary sensor ("on") or an enum, like VEVOR's
# "plugged_in", OCPP's "Preparing"/"SuspendedEV" or go-e's "waiting".
_UNPLUGGED = ("off", "false", "available", "disconnected", "unplugged", "fault_unplugged", "not_connected", "no_car",
              "idle", "unavailable", "unknown", "none", "")


def is_plugged(state: Any) -> bool:
    s = str(state or "").strip().lower().replace(" ", "_")
    if s in _UNPLUGGED or "unplug" in s or "disconnect" in s or "not_connected" in s:
        return False
    return s in ("on", "true", "1") or any(w in s for w in (
        "plug", "connect", "charg", "wait", "paus", "suspend", "prepar", "finish", "complete", "occupied", "ready", "car"))


def extras(settings: dict[str, Any]) -> list[dict[str, Any]]:
    """The extra chargers that are set up (with a power or a plug sensor)."""
    return [c for c in (settings.get("chargers") or []) if isinstance(c, dict) and (c.get("power") or c.get("plug"))]


def _num(s: dict[str, Any] | None) -> float | None:
    try:
        return float((s or {}).get("state"))
    except (TypeError, ValueError):
        return None


def session(states: dict[str, Any], session_e: str | None, plug_e: str | None, mark: float | None = None) -> float | None:
    """What was charged since the car was plugged in. Many chargers (KEBA, …) keep the last session's number until
    the next one starts charging - a number older than the plug-in belongs to the previous car visit: 0.

    mark: what the meter showed when the car was plugged in (remembered by Energy Pilot, also over a restart - a
    restart gives every sensor a new "last changed", so that alone can't tell). The meter then counts from it: the
    same number is 0, a lower one is a new session that started from 0, a higher one counts on from the mark."""
    if not session_e:
        return None
    s = states.get(session_e) or {}
    v = _num(s)
    if v is None or not plug_e:
        return v
    p = states.get(plug_e) or {}
    if not is_plugged(p.get("state")):
        return v
    if mark is not None:
        return round(v - mark, 2) if v >= mark - 0.01 else v
    try:
        if datetime.fromisoformat(s["last_changed"]) < datetime.fromisoformat(p["last_changed"]):
            return 0.0
    except (KeyError, ValueError, TypeError):
        pass
    return v


def read(states: dict[str, Any], c: dict[str, Any], marks: dict[str, float] | None = None) -> dict[str, Any]:
    """One extra charger now: power (W), plugged in, charged this session (kWh)."""
    w = _num(states.get(c["power"])) if c.get("power") else None
    if w is not None and str(((states.get(c["power"]) or {}).get("attributes") or {}).get("unit_of_measurement") or "").lower() == "kw":
        w *= 1000
    # No plug sensor: power tells - but a plain switch (a smart plug) draws nothing while off, so it is taken as plugged in.
    plug = is_plugged((states.get(c["plug"]) or {}).get("state")) if c.get("plug") else bool(c.get("switch")) or (w or 0) > 100
    return {"name": c.get("name") or "", "power": w, "plug": plug,
            "session_kwh": session(states, c.get("session"), c.get("plug"), (marks or {}).get(c.get("plug") or ""))}


def ready_at(c: dict[str, Any], now: datetime) -> datetime | None:
    if not c.get("ready"):
        return None
    hh, mm = (int(x) for x in str(c["ready"]).split(":")[:2])
    t = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
    return t if t > now else t + timedelta(days=1)


def _template(obj: str, words: tuple[str, ...]) -> str | None:
    """The name with the role word cut out: keba_p30_charging_power_2 -> keba_p30_|_2 (tells two boxes apart)."""
    for w in words:
        if w in obj:
            return obj.replace(w, "|", 1)
    return None


def find(states: dict[str, Any], main_power: str | None, main_plug: str | None, taken: list[str],
         dismissed: list[str]) -> list[dict[str, Any]]:
    """Chargers in Home Assistant that aren't set up: a charging power sensor with a plug sensor of the same name."""
    plugs = {}
    sessions = {}
    for e, s in states.items():
        obj = e.split(".", 1)[1]
        if e.startswith("binary_sensor.") and (t := _template(obj, PLUG_WORDS)):
            plugs.setdefault(t, e)
        if e.startswith("sensor.") and (t := _template(obj, SESSION_WORDS)):
            sessions.setdefault(t, e)
    out = []
    for e, s in sorted(states.items()):
        if not e.startswith("sensor.") or e in (main_power,) or e in taken or e in dismissed:
            continue
        obj = e.split(".", 1)[1]
        t = _template(obj, POWER_WORDS)
        a = s.get("attributes") or {}
        if t is None or str(a.get("unit_of_measurement") or "").lower() not in ("w", "kw"):
            continue
        plug = plugs.get(t)
        if plug is None or plug == main_plug or plug in taken:
            continue  # a power sensor alone could be anything - a charger has a plug
        out.append({"power": e, "plug": plug, "session": sessions.get(t), "name": a.get("friendly_name") or e})
    return out


# The switch that starts and stops a charger - only what has to do with charging is offered.
CHARGE_WORDS = re.compile(r"charg|evse|wallbox|(^|_)ev(_|$)|lader|ladebox|ladestation|laadpaal|laad|recharge|zappi|easee|"
                          r"keba|wallbox|go_?e|ohme|pod_?point|myenergi|commando")
_T = r"(?:^|_)"  # a whole word in entity_id style
NOT_CHARGER = re.compile(r"batter|inverter|discharg|grid_charg|ac_charg|force_charg|export|solar|backup|child|display|"
                         r"bornesikring|bornelas|barnlas|barnesikring|kinderslot|kindersicherung|securite_enfant|"
                         r"buzzer|firmware|restart|reboot|identify|sentry|climate|heater|defrost|steering|precondition|"
                         r"charge_port|cable_lock|" + _T + r"(sell|eco|lock|led|leds|light|lights|lys|screen|sound|beep|"
                         r"update|ota|sleep|seat|seats|valet|window|windows|door|doors|trunk|frunk)(?:_|$)")
CHARGER_MODEL = re.compile(r"charg|evse|wallbox|lader|laad|borne de|zappi|easee|keba|go-e|ohme|pod point", re.I)


def switch_options(registry: list[dict[str, Any]], devices: dict[str, dict[str, Any]], states: dict[str, Any],
                   anchors: list[str], skip_devices: set[str]) -> list[dict[str, Any]]:
    """Switches that can start and stop a charger: on a charger's own device, on the device that measures a
    charger's power (a Shelly, a smart plug), or named for charging - never the inverter's or the battery's."""
    by_id = {e["entity_id"]: e for e in registry}
    anchor_devs = {by_id[a]["device_id"] for a in anchors if a and (by_id.get(a) or {}).get("device_id")}
    current_devs = {e.get("device_id") for e in registry if e.get("device_id")
                    and re.match(r"(number|select)\..*(current|ampere|amp|courant|strom)", e["entity_id"])}
    out = []
    for e in registry:
        eid = e["entity_id"]
        if not eid.startswith("switch.") or e.get("disabled_by") or eid not in states:
            continue
        dev = e.get("device_id") or ""
        if dev and dev in skip_devices:
            continue
        name = str((states[eid].get("attributes") or {}).get("friendly_name") or eid)
        text = (eid.split(".", 1)[1] + " " + name.lower().replace(" ", "_"))
        if NOT_CHARGER.search(text):
            continue
        d = devices.get(dev) or {}
        model = " ".join(str(d.get(k) or "") for k in ("manufacturer", "model", "name", "name_by_user"))
        if dev in anchor_devs:
            why = "measures"
        elif CHARGE_WORDS.search(text):
            why = "name"
        elif dev and CHARGER_MODEL.search(model) and dev in current_devs:
            why = "charger"
        else:
            continue
        out.append({"entity_id": eid, "name": name, "device": dev, "why": why})
    order = {"measures": 0, "charger": 1, "name": 2}
    return sorted(out, key=lambda r: (order[r["why"]], r["name"].lower()))

energy_pilot/checks.py:
"""Self-check: settings that make the plan worse, each with a plain explanation and (when it can) a one-tap fix.

A wrong number - an import limit set too low, a battery size off by a few kWh - quietly spoils the plan, and
nothing told the user. These checks look at what Energy Pilot has measured and planned, and say so.
"""

from __future__ import annotations

import re
from datetime import datetime
from typing import Any


class GridPeak:
    """The most the house has really bought from the grid (kW, two-minute average) - kept for 30 days."""

    def __init__(self, state: dict[str, Any]) -> None:
        self.state = state
        self._recent: list[float] = []

    def see(self, now: datetime, grid_w: float | None) -> None:
        if grid_w is None:
            return
        self._recent = (self._recent + [max(0.0, grid_w) / 1000])[-4:]  # 4 x 30 s
        if len(self._recent) < 4:
            return
        kw = sum(self._recent) / 4
        p = self.state.get("grid_peak") or {}
        old = p.get("at")
        stale = old is None or (now - datetime.fromisoformat(old)).days >= 30
        if stale or kw > p.get("kw", 0):
            self.state["grid_peak"] = {"kw": round(kw, 2), "at": now.isoformat()}

    def kw(self) -> float | None:
        return (self.state.get("grid_peak") or {}).get("kw")


# The most common main fuse for a house, by country: (kW, as people know it). Only where one size is common.
USUAL_FUSE = {"DK": (17, "3 × 25 A"), "SE": (17, "3 × 25 A"), "FI": (17, "3 × 25 A"), "DE": (24, "3 × 35 A"),
              "AT": (24, "3 × 35 A"), "NL": (17, "3 × 25 A"), "GB": (23, "100 A"), "IE": (14, "63 A")}


def run(engine: Any, hours: list, b: Any, plan: Any, end_value: float) -> list[dict[str, Any]]:
    """The checks for the plan just made. Each: key, level (warn/info), values for the text, fix (settings) or goto."""
    from .engine import plan_battery

    out: list[dict[str, Any]] = []
    st = engine.ov.settings
    f = engine.ov.flow() or {}

    # 1. The import limit stops the battery charging in the cheap hours.
    if b.import_limit_kw is not None and plan is not None and hours:
        from dataclasses import replace

        free = plan_battery(hours, f["soc"], replace(b, import_limit_kw=None), end_value=end_value)
        lost = round(plan.cost - free.cost, 2)
        if lost > max(0.5, 0.02 * abs(plan.cost_without or 0)):
            out.append({"key": "fuse_blocks", "level": "warn", "vals": {"limit": b.import_limit_kw, "x": lost},
                        "fix": {"import_limit_kw": None}, "goto": "grid"})
    peak = engine.grid_peak.kw() if getattr(engine, "grid_peak", None) else None
    if b.import_limit_kw is not None and peak and peak > b.import_limit_kw * 1.05 and not any(c["key"] == "fuse_blocks" for c in out):
        out.append({"key": "fuse_low", "level": "warn", "vals": {"limit": b.import_limit_kw, "peak": round(peak, 1)},
                    "fix": {"import_limit_kw": None}, "goto": "grid"})
    # The limit is still the 10 kW new installs start with: the usual main fuse in the country is a better guess.
    st0 = engine.ov.settings
    country = str(((getattr(engine, "ha", None) and engine.ha.config) or {}).get("country") or "").upper()
    usual = USUAL_FUSE.get(country)
    if (usual and st0.get("import_limit_kw") == 10 and not st0.get("fuse_ok") and (peak or 0) <= usual[0]
            and not any(c["key"] in ("fuse_blocks", "fuse_low") for c in out)):
        out.append({"key": "fuse_default", "level": "info", "vals": {"kw": usual[0], "fuse": usual[1]},
                    "fix": {"import_limit_kw": usual[0]}, "dismiss": {"fuse_ok": True}, "goto": "grid"})

    # 2. Battery size: the usable kWh it has measured differs from what's set.
    from . import batteries

    learned = engine.batt_learn.capacity()
    if learned and not batteries.extras(st) and st.get("battery_kwh") and abs(float(st["battery_kwh"]) - learned) / learned > 0.05:
        out.append({"key": "capacity", "level": "info", "vals": {"set": float(st["battery_kwh"]), "learned": round(learned, 1)},
                    "fix": {"battery_kwh": None}, "goto": "battery"})

    # 3. Is the car part of the house use? The user's choice says otherwise than what it has seen.
    chosen, seen = st.get("ev_in_house"), engine.ev_detected
    if chosen is not None and seen is not None and bool(chosen) != bool(seen):
        out.append({"key": "ev_house", "level": "info", "vals": {"seen": bool(seen)}, "fix": {"ev_in_house": None}, "goto": "car"})

    # 3b. Sell the sun instead of storing it - offered to those who had Energy Pilot before it came (new installs
    #     have it on). Only when the plan does sell surplus sun while the battery would take it anyway.
    st_keys = engine.ov.settings
    ctl = getattr(engine.ov, "controller", None)
    sell_sun = getattr(engine.ov, "sell_sun", None)
    if callable(sell_sun) and "sell_sun" not in st_keys and not sell_sun() and plan is not None and ctl and ctl.can_block_sun():
        kwh = sum(-s.grid_kwh for s in plan.steps if s.action == "hold" and s.grid_kwh < -0.01 and s.soc_end < b.max_soc - 1)
        if kwh >= 1:
            out.append({"key": "sell_sun", "level": "info", "vals": {"kwh": round(kwh, 1)}, "fix": {"sell_sun": True}, "goto": "battery"})

    # 4. Selling from the battery.
    if st.get("battery_export"):
        if not b.export:
            out.append({"key": "export_blocked", "level": "info", "vals": {}, "goto": "battery"})
        elif not st.get("sell") and not engine.ov.role("sell_price"):
            out.append({"key": "export_no_price", "level": "warn", "vals": {}, "fix": {"sell": True}, "goto": "prio"})
        elif plan is not None and hours and not any(s.action == "export" for s in plan.steps):
            best = max(h.sell for h in hours)
            # What the power in the battery saves: the cheapest hour the plan lets the battery cover the house in.
            price = {h.start: h.price for h in hours}
            used = [price[x.start] for x in plan.steps if x.action == "discharge" and x.start in price]
            buys = sorted(h.price for h in hours)
            worth = min(used) if used else buys[len(buys) // 2]  # kept for later: about a usual hour's price
            if best < worth:  # otherwise something else holds it back - nothing plain to say
                out.append({"key": "export_no_gain", "level": "info", "vals": {"sell": round(best, 2), "worth": round(worth, 2)}})

    # 5. Another battery in Home Assistant that isn't set up.
    main = engine.ov.role("battery_soc")
    if main and not st.get("offgrid"):
        more = batteries.extras(st)
        taken = [b.get("soc") for b in more] + [b.get("power") for b in more]
        for cand in batteries.find(engine.ha.states, main, taken, list(st.get("battery_dismissed") or []),
                                    getattr(getattr(engine.ov, "controller", None), "phones", None) or frozenset())[:1]:
            new = {"name": cand["name"], "soc": cand["soc"], "power": cand["power"]}
            out.append({"key": "battery_found", "level": "info", "vals": {"name": cand["name"]},
                        "fix": {"batteries": list(st.get("batteries") or []) + [new]},
                        "dismiss": {"battery_dismissed": list(st.get("battery_dismissed") or []) + [cand["soc"]]}, "goto": "battery"})

    # 6. The learning models can't run on this CPU (see mlcheck.py) - the simple forecasts are used.
    from . import mlcheck

    if mlcheck.why() == "cpu":
        out.append({"key": "ml_cpu", "level": "info", "vals": {}})

    # 7. Another charger in Home Assistant that isn't set up.
    from . import chargers

    if engine.ov.role("ev_power") or engine.ov.role("ev_plug"):
        more = chargers.extras(st)
        taken = [x for c in more for x in (c.get("power"), c.get("plug"))]
        for cand in chargers.find(engine.ha.states, engine.ov.role("ev_power"), engine.ov.role("ev_plug"), taken,
                                  list(st.get("charger_dismissed") or []))[:1]:
            new = {k: cand[k] for k in ("name", "power", "plug", "session")}
            out.append({"key": "charger_found", "level": "info", "vals": {"name": cand["name"]},
                        "fix": {"chargers": list(st.get("chargers") or []) + [new]},
                        "dismiss": {"charger_dismissed": list(st.get("charger_dismissed") or []) + [cand["power"]]}, "goto": "car"})

    # 6b. A machine or a small battery that could run cheaply (Settings → Things that run cheaply) - one at a time.
    ctl = getattr(engine.ov, "controller", None)
    for cand in (getattr(ctl, "thing_candidates", None) or [])[:1]:
        import uuid

        new = {"id": uuid.uuid4().hex[:8], "mode": "sun_cheap"} | {k: v for k, v in cand.items() if k not in ("device", "remote") and v}
        out.append({"key": "thing_found", "level": "info", "vals": {"name": cand["name"]},
                    "fix": {"things": list(st.get("things") or []) + [new]},
                    "dismiss": {"things_dismissed": list(st.get("things_dismissed") or []) + [cand["device"]]}, "goto": "things"})

    # 7. Things it can't see.
    if f.get("soc") is None and not st.get("offgrid"):
        out.append({"key": "no_soc", "level": "warn", "vals": {}, "goto": "roles"})

    out += house_history(engine, st)
    out += read_only(engine, st)
    out += alpha_period(engine)
    out += inverter_floor(engine, b)
    return out


# Integrations that can only read the battery - and the one that can control it instead (with a link that opens it).
READ_ONLY = {
    "powerwall": ("Powerwall", "Teslemetry", "https://my.home-assistant.io/redirect/config_flow_start/?domain=teslemetry"),
    "solaredge": ("SolarEdge", "SolarEdge Modbus Multi",
                  "https://my.home-assistant.io/redirect/hacs_repository/?owner=WillCodeForCats&repository=solaredge-modbus-multi&category=integration"),
    "fusion_solar": ("Huawei", "Huawei Solar", "https://my.home-assistant.io/redirect/hacs_repository/?owner=wlcrs&repository=huawei_solar&category=integration"),
}


def read_only(engine: Any, st: dict[str, Any]) -> list[dict[str, Any]]:
    """The battery comes from an integration that can only read it, and nothing else to control it with: one quiet line
    that says which integration can - with a button that opens it, and "Not now" that hides it for good."""
    ctl = getattr(engine.ov, "controller", None)
    reg = getattr(ctl, "_ent_reg", None) or {}
    soc = engine.ov.role("battery_soc")
    plat = (reg.get(soc or "") or {}).get("platform")
    if plat not in READ_ONLY or plat in (st.get("readonly_dismissed") or []):
        return []
    if ctl and (ctl.profile_key("battery") or st.get("custom_profile")):
        return []  # something to control it with was found (or set up by hand): nothing to say
    name, use, link = READ_ONLY[plat]
    return [{"key": "read_only", "level": "info", "vals": {"name": name, "use": use}, "link": link,
             "dismiss": {"readonly_dismissed": list(st.get("readonly_dismissed") or []) + [plat]}}]


# AlphaESS' integration only changes a period that exists, on the weekdays it already runs: one made in its app fixes it.
ALPHA_PERIOD = re.compile(r"no existing period|create it in the alpha|does not run today|in the alphaess app", re.I)


def alpha_period(engine: Any) -> list[dict[str, Any]]:
    """The last battery command was refused by AlphaESS for want of a period in its app: say how to make one."""
    ctl = getattr(engine.ov, "controller", None)
    log = list((getattr(ctl, "log", None) or {}).get("battery") or [])
    last = next((e for e in log if e.get("mode") == "control"), None)
    if not last or last.get("result") == "ok" or not ALPHA_PERIOD.search(str(last.get("error") or "")):
        return []
    return [{"key": "alpha_period", "level": "warn", "vals": {}}]


def house_history(engine: Any, st: dict[str, Any]) -> list[dict[str, Any]]:
    """The house sensor keeps no statistics in Home Assistant (no state_class): no history to learn the house from.
    Energy Pilot can keep the history itself - offered with one tap; once on, how many days it has so far."""
    stats_h = getattr(engine, "house_stats_hours", None)
    house_e = engine.ov.role("house_power") or engine.ov.role("grid_power")
    if stats_h is not None and stats_h < 24 * 7 and house_e:
        attrs = ((engine.ha.states.get(house_e) or {}).get("attributes") or {})
        if not st.get("own_history") and not attrs.get("state_class"):
            return [{"key": "house_no_stats", "level": "warn", "vals": {"sensor": attrs.get("friendly_name") or house_e},
                        "fix": {"own_history": True}, "goto": "roles"}]
        elif st.get("own_history") and engine.house_hist.days() < 7:
            return [{"key": "house_own_history", "level": "info", "vals": {"d": str(engine.house_hist.days())}}]
    return []


# The inverter's own lowest battery level: below it the inverter won't discharge, whatever is asked (Deye's
# "Battery Low SOC" and "Shutdown SOC", Solis' over-discharge SOC, SolaX' "Selfuse Discharge Min SOC" ...).
FLOOR = re.compile(r"(low|shut_?down|cut_?off|over_?discharge|discharge_?min|min_?discharge|end_?of_?discharge)[a-z_]*soc|soc[a-z_]*(low|min|cut_?off|shut_?down)$", re.I)
RESTART = re.compile(r"restart[a-z_]*soc|soc[a-z_]*restart", re.I)
NOT_FLOOR = re.compile(r"program_|time_point|energ(i|y)_?pilot|charg(e|ing)_(soc|start)|max", re.I)


def inverter_floors(states: dict[str, Any], entities: list[str], restart: bool = False) -> list[tuple[str, float]]:
    """(name, %) of the inverter's settings that keep the battery from going lower; restart: also the level it waits
    for after it has been empty (Deye's "Restart SOC")."""
    out = []
    for e in entities:
        if not e.startswith("number."):
            continue
        name = e.split(".", 1)[1]
        if NOT_FLOOR.search(name) or not (FLOOR.search(name) or restart and RESTART.search(name)):
            continue
        st = states.get(e) or {}
        unit = (st.get("attributes") or {}).get("unit_of_measurement")
        try:
            v = float(st.get("state"))
        except (TypeError, ValueError):
            continue
        if unit in (None, "%") and 0 < v <= 100:
            out.append((name, v))
    return out


def inverter_floor(engine: Any, b: Any) -> list[dict[str, Any]]:
    """The inverter stops discharging above the minimum Energy Pilot plans with: offer to use the inverter's level."""
    ctl = getattr(engine.ov, "controller", None)
    if ctl is None or b is None or ctl.mode("battery") != "control":
        return []
    floors = inverter_floors(engine.ov.ha.states, (getattr(ctl, "entities", None) or {}).get("battery") or [])
    if not floors:
        return []
    name, v = max(floors, key=lambda x: x[1])
    if v <= (b.min_soc or 0) + 0.5:
        return []
    return [{"key": "inv_floor", "level": "warn", "vals": {"inv": int(v) if float(v).is_integer() else v, "ep": int(b.min_soc or 0), "name": name},
             "fix": {"battery_min_soc": int(round(v))}, "goto": "battery"}]


class FollowWatch:
    """Does the battery do what it's told? If the plan wants it to cover the house (or charge) and it stays at 0 W for
    10 minutes, something on the inverter holds it back - often a rate or limit left at 0 by another system. It says
    so, with the inverter's settings that stand at 0, so it's found for every inverter, known or not."""

    WAIT = 600  # seconds the battery must stay still before it's told
    WORDS = {"discharge": r"discharg|dischg|output|export", "charge": r"(?<!dis)charg|(?<!dis)chg|input"}
    LIMIT = r"rate|power|limit|current|level|max"

    def __init__(self) -> None:
        self.since: datetime | None = None
        self.kind: str | None = None
        self.found: dict[str, Any] | None = None

    def see(self, now: datetime, mode: str | None, want: dict[str, Any] | None, f: dict[str, Any],
            states: dict[str, Any], entities: list[str]) -> None:
        kind = self._expect(mode, want, f)
        batt, grid = f.get("battery"), f.get("grid") or 0.0
        stuck = kind == "discharge" and batt is not None and batt > -100 and grid > 300 \
            or kind == "charge" and batt is not None and batt < 100
        if not stuck:
            self.since, self.kind, self.found = None, None, None
            return
        if self.kind != kind:
            self.since, self.kind, self.found = now, kind, None
        if (now - self.since).total_seconds() >= self.WAIT and self.found is None:
            self.found = {"kind": kind, "at": now.isoformat(), "suspects": self.suspects(kind, states, entities, f.get("soc"))}
            import logging

            logging.getLogger("energy_pilot.control").warning("The battery doesn't follow the plan (%s): %s", kind, self.found["suspects"])

    @staticmethod
    def _expect(mode: str | None, want: dict[str, Any] | None, f: dict[str, Any]) -> str | None:
        if mode != "control" or not want or f.get("soc") is None:
            return None
        ctx, soc = want.get("ctx") or {}, f["soc"]
        need = (f.get("house") or 0.0) - (f.get("pv") or 0.0)
        if want.get("intent") == "normal" and need > 400 and soc > (ctx.get("min_soc") or 0) + 3:
            return "discharge"
        if want.get("intent") == "charge" and soc < (ctx.get("target") or 0) - 3:
            return "charge"
        return None

    @classmethod
    def suspects(cls, kind: str, states: dict[str, Any], entities: list[str], soc: float | None = None) -> list[str]:
        """The inverter's numbers that sound like they limit this way and stand at 0 or at their lowest (Sungrow's
        "no battery discharge" is 10 W, the least it takes): "free_mode_discharge_rate = 0"."""
        import re

        out = []
        # The inverter's own lowest level (or the level it waits for after empty) at or above the battery now.
        if kind == "discharge" and soc is not None:
            out += [f"{n} = {int(v) if v.is_integer() else v} %" for n, v in inverter_floors(states, entities, restart=True) if v >= soc - 1]
        for e in entities:
            if not e.startswith("number."):
                continue
            name = e.split(".", 1)[1]
            if not (re.search(cls.WORDS[kind], name) and re.search(cls.LIMIT, name)):
                continue
            st = states.get(e) or {}
            try:
                v = float(st.get("state"))
            except (TypeError, ValueError):
                continue
            attrs = st.get("attributes") or {}
            lo, hi = attrs.get("min"), attrs.get("max")
            lowest = isinstance(lo, (int, float)) and isinstance(hi, (int, float)) and 0 < lo and hi >= 20 * lo and v <= lo
            if v == 0 or lowest:
                out.append(f"{name} = {int(v) if v.is_integer() else v}")
        # Modes and switches that stop it outright: Victron's "Keep batteries charged", GivEnergy's pause, "disable charge".
        block = {"discharge": r"keep batteries charged|pause discharg|pause both", "charge": r"pause charg|pause both"}[kind]
        for e in entities:
            st = str((states.get(e) or {}).get("state") or "")
            name = e.split(".", 1)[1]
            if e.startswith("select.") and re.search(block, st, re.I):
                out.append(f"{name} = {st}")
            elif e.startswith("switch.") and st == "on" and re.search(r"disable_charg" if kind == "charge" else r"disable_discharg", name):
                out.append(f"{name} = on")
        return out[:4]

    def check(self) -> list[dict[str, Any]]:
        if not self.found:
            return []
        names = ", ".join(self.found["suspects"])
        key = f"follow_{self.found['kind']}" + ("_why" if names else "")
        return [{"key": key, "level": "warn", "vals": {"list": names}, "goto": "battery"}]

energy_pilot/control.py:
"""The engine's hands: turning the plan into what the inverter and the charger are told - in shadow first.

Every few minutes: what the plan wants now (battery: normal / hold / charge; car: charge / stop) is turned into
service calls through the adapter. In shadow they are only written down ("would do"); in control they are sent -
only when the intent changes, and again every half hour in case something else changed it. After sending, the
controls are read back to see that they took.

Safety:
- Starts in shadow, one part at a time.
- Won't take the battery while another system plans it (your AppDaemon), unless you say so.
- "Everything back to shadow" puts the battery back to normal before letting go.
- Won't control if a control the profile needs is missing (another model, renamed, disabled) - never half a command.
"""

from __future__ import annotations

import asyncio
from collections import deque
from datetime import datetime, timedelta
import logging
import re
import time
from typing import Any
from zoneinfo import ZoneInfo

from . import adapters

# Platforms that hold anything (helpers, sums, MQTT): their entities never belong to one inverter or charger.
GENERIC_PLATFORMS = ("mqtt", "template", "group", "min_max", "integration", "utility_meter", "statistics", "filter",
                     "derivative", "threshold", "trend", "compensation", "powercalc", "sql", "rest", "command_line")

_LOGGER = logging.getLogger(__name__)
REASSERT_S = 1800


class Controller:
    def __init__(self, ha: Any, overview: Any, engine: Any) -> None:
        self.ha, self.ov, self.engine = ha, overview, engine
        self.entities: dict[str, list[str]] = {"battery": [], "car": []}
        self.platforms: dict[str, str | None] = {"battery": None, "car": None}
        self.model: str | None = None
        self.services: set[str] | None = None
        self.last: dict[str, dict[str, Any]] = {}
        self.log: dict[str, deque] = {"battery": deque(maxlen=60), "car": deque(maxlen=60), "generator": deque(maxlen=60)}
        self.car_devices: dict[str, str | None] = {}  # the extra chargers' devices (car2, car3 …)
        self.bat_info: dict[str, dict[str, Any]] = {}  # the extra batteries' inverter: device, model, serial
        self._sun_on_more: dict[str, bool] = {}
        self.more_why: dict[str, str] = {}
        self._sun_on = False  # the car is charging on the sun's surplus (for the start/stop margin)
        self._phase_at: dict[str, float] = {}  # when each charger last changed between 1 and 3 phases
        self.car_why = ""
        self.lone_ok: dict[str, bool] = {}  # a charger's only switch may start it (found on its own device)
        self.chosen: dict[str, str] = {}  # the switch picked for a charger in the settings
        self.switch_options: list[dict[str, Any]] = []
        self._devices: dict[str, dict[str, Any]] = {}
        self.registry: list[dict[str, Any]] = []
        self.discovered = False  # the controls looked up at least once since the start
        self.thing_candidates: list[dict[str, Any]] = []  # machines and small batteries worth offering (things.find)
        # Controls that went back to another value after they were set (Victron's defaults, Predbat, an automation):
        # part -> [(time, entity)], the last hour.
        self.drift: dict[str, list[tuple[float, str]]] = {}
        self._gone: dict[str, set[str]] = {}  # controls seen unavailable since the last send (sent again when back)
        self.testing: set[str] = set()  # parts the self-test drives right now - left alone meanwhile
        self.community_used: dict[str, dict[str, Any]] = {}  # shared fixes in use here (shown with an undo)
        self.safe_until: dict[str, float] = {}  # the battery did the opposite of what it was told: normal until then
        self._wrong: dict[str, float] = {}
        self._car_idle: dict[str, float] = {}
        self._kicked: dict[str, bool] = {}
        self.car_stuck: dict[str, bool] = {}
        self._bat_lock = asyncio.Lock()  # the battery's round and the minute's keep-alive never send at once

    # ---------- settings ----------

    def car_parts(self) -> list[str]:
        """The extra chargers as parts of their own: car2, car3 … - each starts in shadow and is turned on by itself."""
        from . import chargers

        return [f"car{i + 2}" for i in range(len(chargers.extras(self.ov.settings)))]

    def bat_parts(self) -> list[str]:
        """The extra batteries (bat2, bat3 …): each talks to its own inverter, starts in shadow, turned on by itself."""
        from . import batteries

        return [f"bat{i + 2}" for i in range(len(batteries.extras(self.ov.settings)))]

    def parts(self) -> list[str]:
        return ["battery", *self.bat_parts(), "car", "generator", *self.car_parts()]

    @staticmethod
    def is_battery(part: str) -> bool:
        return part == "battery" or part.startswith("bat")

    def mode(self, part: str) -> str:
        return ((self.ov.settings.get("control") or {}).get(part)) or "shadow"

    async def hand_back(self, part: str) -> None:
        """A battery leaving control: normal again and the owner's own settings back (a grid setpoint left selling
        would go on selling in shadow)."""
        if self.mode(part) != "control" or not self.is_battery(part) or self.blocked(part):
            return
        want = self.intents().get(part)
        if want:
            await self._send(self.calls(part, {**want, "intent": "normal"}) + self._restore(part, "normal"))

    def set_mode(self, part: str, mode: str) -> None:
        modes = dict(self.ov.settings.get("control") or {})
        modes[part] = mode
        self.ov.save({"control": modes})
        self.last.pop(part, None)  # act again at once

    def blocked(self, part: str) -> str | None:
        """Why the engine may not control this part (None: it may)."""
        if self.is_battery(part) and self.ov.role("battery_plan") and not self.ov.settings.get("battery_takeover"):
            return "other_system"  # another system plans the battery: never two at once
        if self.is_battery(part) and not self.profile_steps(part):
            return "no_profile"
        if self.is_battery(part) and adapters.missing(self.check(part)):
            return "missing_controls"
        if self.is_battery(part) and self.ov.settings.get("offgrid"):
            return "offgrid"  # no grid to charge from: the inverter runs the battery, the engine runs the generator
        if part == "generator" and not self.ov.role("generator_switch"):
            return "no_generator"
        if part.startswith("car") and not self._can_drive(part):
            return "no_charger"
        return None

    # ---------- what the controls are ----------

    async def discover(self) -> None:
        """The inverter's and the charger's controls: select/number/switch/button entities on the same device."""
        try:
            entities = await self.ha.command({"type": "config/entity_registry/list"})
        except Exception:  # noqa: BLE001
            return
        by_id = {e["entity_id"]: e for e in entities}
        self._ent_reg = by_id  # (the setup for the developer: setupinfo.py)
        self.phones = {e["entity_id"] for e in entities if e.get("platform") == "mobile_app"}  # phones and tablets
        try:
            devices = {d["id"]: d for d in await self.ha.command({"type": "config/device_registry/list"})}
            self._devices = devices
            dev = devices.get((by_id.get(self.ov.role("battery_soc") or "") or {}).get("device_id") or "") or {}
            parts = [x for x in (dev.get("model"), dev.get("model_id"), dev.get("name")) if x]
            self.model = " ".join(dict.fromkeys(parts)) or None  # "Growatt SPH", not "Growatt SPH Growatt SPH"
        except Exception:  # noqa: BLE001
            self.model = None
        try:  # the areas' names: taken out of the names sent to the developer (setupinfo.py)
            self._areas = [a.get("name") or "" for a in await self.ha.command({"type": "config/area_registry/list"})]
        except Exception:  # noqa: BLE001
            self._areas = []
        try:
            svc = await self.ha.command({"type": "get_services"})
            self.services = {f"{d}.{n}" for d, names in svc.items() for n in names}
        except Exception:  # noqa: BLE001
            self.services = None
        for part, role in (("battery", "battery_soc"), ("car", "ev_power")):
            anchor = self.ov.role(role) or (self.ov.role("ev_plug") if part == "car" else None)
            if part == "car":
                # The charger's own device: the power sensor's - or, when that is a sum/group/template of several
                # (no device), the plug's or the session's (a Zappi behind an "All EV power" group).
                for r in ("ev_power", "ev_plug", "ev_session"):
                    e = self.ov.role(r)
                    if e and (by_id.get(e) or {}).get("device_id"):
                        anchor = e
                        break
            dev = (by_id.get(anchor) or {}).get("device_id")
            plat = (by_id.get(anchor) or {}).get("platform")
            found = [e["entity_id"] for e in entities if not e.get("disabled_by") and e["entity_id"].split(".")[0] in ("select", "number", "switch", "button")
                     and ((dev and e.get("device_id") == dev) or (plat and e.get("platform") == plat and plat not in GENERIC_PLATFORMS
                                                                   and not (part == "car" and dev)))]
            # The charger: only its own device when it has one - Tuya, say, also has the air conditioner and the cat's
            # litter box, and their switches must never be taken for the charger's.
            if not found and anchor and part == "battery":  # MQTT inverters: same name prefix (never for a charger)
                prefix = anchor.split(".", 1)[1].split("_")[0]
                found = [e for e in self.ha.states if e.split(".")[0] in ("select", "number", "switch") and e.split(".", 1)[1].startswith(prefix + "_")]
            self.entities[part], self.platforms[part] = sorted(found), plat
            if part == "car":
                self.car_device = dev  # Easee's actions want the charger's device
                self.lone_ok["car"] = bool(dev)
            if part == "battery":
                self.battery_device = dev  # for services that want the device (Huawei, GivEnergy)
                d = (devices or {}).get(dev or "") if "devices" in dir() else None
                self.battery_serial = (d or {}).get("serial_number") or ""  # Alpha ESS wants the serial

        # The extra chargers: the controls on the device of their power (or plug) sensor.
        from . import chargers

        for part, c in zip(self.car_parts(), chargers.extras(self.ov.settings)):
            anchor = c.get("power") or c.get("plug")
            dev = (by_id.get(anchor) or {}).get("device_id")
            plat = (by_id.get(anchor) or {}).get("platform")
            found = [e["entity_id"] for e in entities if not e.get("disabled_by") and dev and e.get("device_id") == dev
                     and e["entity_id"].split(".")[0] in ("select", "number", "switch", "button")]
            self.entities[part], self.platforms[part], self.car_devices[part] = sorted(found), plat, dev
            self.lone_ok[part] = bool(dev)

        # The switch chosen for a charger (Settings → Car → Control): it starts and stops the car, and a current
        # control on its device (Tuya Local, ESPHome …) sets the speed. Only charging switches are offered.
        skip = {d for d in [getattr(self, "battery_device", None)] if d}
        self.registry = entities  # for Settings → Runs cheaply (what to pick from)
        self._chosen_switches(entities, by_id, skip)
        try:
            from . import things as _things

            taken = {x for t in (self.ov.settings.get("things") or []) for x in (t.get("switch"), t.get("start"), t.get("power")) if x}
            taken |= {x for x in (self.ov.role("ev_power"), self.ov.role("battery_power"), self.ov.role("house_power")) if x}
            self.thing_candidates = _things.find(entities, self._devices, self.ha.states, taken,
                                                 list(self.ov.settings.get("things_dismissed") or []))
        except Exception:  # noqa: BLE001
            self.thing_candidates = []
        self.discovered = True

        # The extra batteries: the controls of the inverter their level sensor sits on.
        from . import batteries

        for part, bt in zip(self.bat_parts(), batteries.extras(self.ov.settings)):
            reg = by_id.get(bt.get("soc")) or {}
            dev, plat = reg.get("device_id"), reg.get("platform")
            found = [e["entity_id"] for e in entities if not e.get("disabled_by") and e["entity_id"].split(".")[0] in ("select", "number", "switch", "button")
                     and ((dev and e.get("device_id") == dev) or (plat and e.get("platform") == plat and plat not in ("mqtt", "template")
                                                                   and plat != self.platforms.get("battery")))]
            d = (devices or {}).get(dev or "") if "devices" in dir() else None
            model = " ".join(dict.fromkeys(x for x in ((d or {}).get("model"), (d or {}).get("model_id"), (d or {}).get("name")) if x)) or None
            self.entities[part], self.platforms[part] = sorted(found), plat
            self.bat_info[part] = {"device": dev or "", "model": model, "serial": (d or {}).get("serial_number") or ""}

    def _chosen_switches(self, entities: list[dict[str, Any]], by_id: dict[str, dict[str, Any]], skip: set[str]) -> None:
        from . import chargers

        more = chargers.extras(self.ov.settings)
        anchors = [self.ov.role("ev_power"), self.ov.role("ev_plug")] + [x for c in more for x in (c.get("power"), c.get("plug"))]
        for b in (self.ov.settings.get("batteries") or []):
            if isinstance(b, dict) and (d := (by_id.get(b.get("soc") or "") or {}).get("device_id")):
                skip.add(d)
        self.switch_options = chargers.switch_options(entities, self._devices, self.ha.states, [a for a in anchors if a], skip)
        chosen = {"car": self.ov.settings.get("ev_switch")} | {p: c.get("switch") for p, c in zip(self.car_parts(), more)}
        self.chosen = {}
        for part, sw in chosen.items():
            reg = by_id.get(sw or "")
            if not reg:
                continue
            dev = reg.get("device_id")
            own = [e["entity_id"] for e in entities if not e.get("disabled_by") and dev and e.get("device_id") == dev
                   and re.match(r"(number|select)\.", e["entity_id"])]
            self.entities[part] = sorted(set(own) | {sw})
            self.platforms[part], self.chosen[part] = None, sw  # the generic way: the switch and a current control
            if part == "car":
                self.car_device = dev
            else:
                self.car_devices[part] = dev

    def _can_drive(self, part: str) -> bool:
        """A charger can be run: by its integration's own actions, a switch, or a current control."""
        if self.platforms.get(part) in adapters.CHARGER_SERVICES:
            return True
        ents = self.entities.get(part) or []
        return bool(self.auto_switch(part)) or any(re.search(adapters.CHARGER_CURRENT, e) for e in ents)

    def onoff(self, part: str) -> bool:
        """A charger that can only be switched on and off (a Shelly, a smart plug): full power or nothing."""
        if getattr(self, "platforms", {}).get(part) in adapters.CHARGER_SERVICES:
            return False
        ents = getattr(self, "entities", {}).get(part) or []
        return bool(ents) and not any(re.search(adapters.CHARGER_CURRENT, e) or re.search(adapters.CHARGER_CURRENT_SELECT, e) for e in ents)

    def auto_switch(self, part: str) -> str | None:
        """The switch this charger is started and stopped with now - chosen, or found by itself."""
        ents = self.entities.get(part) or []
        return self.chosen.get(part) or adapters.charger_switch(ents, self.lone_ok.get(part, False))

    def _extra_battery(self, part: str) -> dict[str, Any]:
        from . import batteries

        more = batteries.extras(self.ov.settings)
        i = self.bat_parts().index(part) if part in self.bat_parts() else -1
        return more[i] if 0 <= i < len(more) else {}

    def profile_key(self, part: str = "battery") -> str | None:
        if part != "battery":
            chosen = self._extra_battery(part).get("profile")
            if chosen:
                return chosen
            info = self.bat_info.get(part) or {}
            return adapters.guess_profile(self.entities.get(part, []), {self.platforms.get(part) or ""}, info.get("model"))
        chosen = self.ov.settings.get("inverter_profile")
        if chosen:
            return chosen
        return adapters.guess_profile(self.entities["battery"], {self.platforms["battery"] or ""}, self.model)

    def can_block_sun(self) -> bool:
        """The inverter's hold sets how much it may charge - then the sun can be kept out of the battery."""
        hold = str((self.profile_steps() or {}).get("hold") or "")
        return "{max_charge_w}" in hold or "{max_charge_kw}" in hold

    def profile_steps(self, part: str = "battery") -> dict[str, list] | None:
        key = self.profile_key(part)
        if key == "custom" and part == "battery":
            c = self.ov.settings.get("custom_profile") or {}
            steps = {i: [(s["entity"], s["kind"], s.get("value")) for s in c.get(i, []) if s.get("entity")] for i in ("normal", "hold", "charge")}
            return steps if any(steps.values()) else None
        p = adapters.PROFILES.get(key or "")
        return {i: p[i] for i in ("normal", "hold", "charge", "export") if i in p} if p else None

    def check(self, part: str = "battery") -> dict[str, dict]:
        """Which of the profile's controls were found on the inverter, and which are missing."""
        steps = self.profile_steps(part) or {}
        key = self.profile_key(part)
        optional = (adapters.PROFILES.get(key or "") or {}).get("optional") or []
        return adapters.check(steps, self._pool(part), optional, self.services) if steps else {}

    def _pool(self, part: str = "battery") -> list[str]:
        """Built-in profiles look only at the inverter's own controls; a custom one may pick any entity. A profile
        with distinctive names (Victron's ess_…) also finds its controls on another device."""
        own = self.entities.get(part, []) if part != "battery" else self.entities["battery"]
        key = self.profile_key(part)
        if part == "battery" and key == "custom":
            return own + list(self.ha.states)
        prof = adapters.PROFILES.get(key or "") or {}
        if prof.get("anywhere"):
            pats = [st[0] for i in ("normal", "hold", "charge", "export") for st in prof.get(i, []) if isinstance(st[0], str)]
            extra = [e for e in self.ha.states if e not in own and e.split(".")[0] in ("select", "number", "switch", "button")
                     and any(re.search(p, e) for p in pats)]
            return own + sorted(extra)
        return own

    # ---------- deciding and acting ----------

    def intents(self) -> dict[str, dict[str, Any]]:
        res = (self.engine.result or {}) if self.engine else {}
        out: dict[str, dict[str, Any]] = {}
        f = self.ov.flow()
        b = res.get("battery")
        if b and b.get("steps"):
            step = b["steps"][0]
            bat = self.engine.settings()
            intent = {"charge_grid": "charge", "hold": "hold", "export": "export"}.get(step["action"], "normal")
            slot_h = (b.get("slot_min") or 60) / 60  # the step is one price slot (a quarter of an hour in Europe)
            # The time left of the slot: the battery is to reach the step's level by its end, so the power follows
            # what is really left - not the whole slot (that left the battery above the plan when the house used less).
            left_h = slot_h
            try:
                start = datetime.fromisoformat(step["t"])
                left_h = min(slot_h, max(5 / 60, slot_h - (datetime.now(start.tzinfo) - start).total_seconds() / 3600))
            except (KeyError, TypeError, ValueError):
                pass
            charge_kw = min(bat.max_charge_kw, max(0.5, (step["soc"] - (f["soc"] or 0)) / 100 * bat.capacity_kwh / left_h))
            export_w = 0
            if intent == "export":  # the battery's discharge power: the house's share and what is sold
                charge_kw = min(bat.max_discharge_kw, max(0.5, ((f["soc"] or 0) - step["soc"]) / 100 * bat.capacity_kwh / left_h))
                export_w = int(round(max(0.0, -(step.get("grid") or 0.0)) / slot_h * 1000 / 50) * 50)
                if f.get("house") is not None:  # what the house really uses now is covered first, the rest is sold
                    net = max(0.0, (f.get("house") or 0.0) - (f.get("pv") or 0.0))
                    export_w = int(round(max(0.0, charge_kw * 1000 - net) / 100) * 100)
            out["battery"] = {"intent": intent, "ctx": {
                "grid_charge": bool(bat.grid_charge), "min_soc": round(bat.min_soc), "soc": round(max(f["soc"] or bat.min_soc, bat.min_soc)), "target": round(b.get("target") or step["soc"]),
                "rate": round(100 * charge_kw / bat.max_charge_kw), "power_w": round(charge_kw * 1000),
                "max_power_w": round(bat.max_discharge_kw * 1000), "max_charge_w": round(bat.max_charge_kw * 1000),
                "power_kw": round(charge_kw, 2), "max_charge_kw": round(bat.max_charge_kw, 2), "max_power_kw": round(bat.max_discharge_kw, 2), "export_w": export_w,
                "device_id": getattr(self, "battery_device", None) or "", "serial": getattr(self, "battery_serial", "") or "",
                **adapters.alpha_windows(datetime.now(ZoneInfo(self.ha.config.get("time_zone") or "UTC")))}}
            if any("{charge_a}" in str(self.profile_steps(p) or {}) for p in ["battery", *self.bat_parts()]):
                # Deye limits charging from the grid by a current: the planned power over the battery's voltage.
                out["battery"]["ctx"]["charge_a"] = max(1, round(charge_kw * 1000 / self._battery_volt()))
            if "{house_w}" in str(self.profile_steps() or {}):
                # Only for profiles that use it (EcoFlow), rounded - so others aren't re-sent at every small change.
                out["battery"]["ctx"]["house_w"] = int(round((f.get("house") or 0.0) / 50) * 50)
            # The plan holds while the sun has a surplus it sells: the battery mustn't fill up with it anyway (a plain
            # hold still takes the sun). Only inverters whose hold sets the charge limit can do this.
            if intent == "hold" and (step.get("grid") or 0.0) < -0.01 and getattr(self.ov, "sell_sun", lambda: False)() and self.can_block_sun():
                out["battery"]["ctx"].update(max_charge_w=0, max_charge_kw=0, sell_sun=True)
        # The car charging on the plan's cheap power right now: the battery holds, so the car takes it from the grid.
        bw = out.get("battery")
        cw = out.get("car")
        if bw and cw and bw["intent"] == "normal" and cw["intent"] == "charge" and not self.ov.settings.get("ev_now") \
                and self.car_why.startswith("planned"):
            out["battery"] = {**bw, "intent": "hold"}
        if out.get("battery") and self.bat_parts():
            out.update(self._share(out["battery"], f))
        g = res.get("generator")
        if g and self.ov.settings.get("offgrid"):
            out["generator"] = {"intent": "run" if g.get("run") else "off", "ctx": {"why": g.get("why")}}
        if self.ov.ev() is not None:
            tz = ZoneInfo(self.ha.config.get("time_zone") or "UTC")
            car = res.get("car") or {}
            now = datetime.now(tz)
            slot = int(car.get("slot_min") or 60)
            hour = now.replace(minute=now.minute // slot * slot if slot < 60 else 0, second=0, microsecond=0)  # the slot now
            planned = {datetime.fromisoformat(t) for t in (car.get("hours") or [])}
            manual = bool(self.ov.settings.get("ev_now"))
            from .carspeed import decide

            st = dict(self.ov.settings)
            if self.engine and (pt := self.engine.power_tariff()):
                st["peak_kw"] = pt["limit_kw"]
            if st.get("ev_follow_sun") is None:
                st["ev_follow_sun"] = bool(self.ov.role("pv_power"))  # on by default when there is solar
            need = float(car.get("need_kwh") if car.get("need_kwh") is not None else 1.0)
            ev = self.ov.ev() or {}
            if ev.get("soc") is not None and ev["soc"] >= ev.get("target", 100):
                manual = False  # at its grid target: never more from the grid, even on "charge now"
                if ev["soc"] < ev.get("sun_target", ev.get("target", 100)) and st.get("ev_follow_sun"):
                    need = 1.0  # the sun's surplus may fill it further (to its own limit) - no grid hours are planned for it
                    hour, planned = None, set()
                else:
                    need = 0.0  # at its limit: it stops, in the sun too (spares the battery)
            st["onoff"] = self.onoff("car")
            st["min_a"] = adapters.lowest_amps(getattr(self, "entities", {}).get("car", []), getattr(getattr(self, "ha", None), "states", {}))
            st.update(self._phase_settings("car", st))
            d = decide(f, st, hour in planned, manual, need, self._sun_on)
            self._sun_on, self.car_why = d["sun"], d["why"]
            self._phase_seen("car", st, d.get("phases"))
            out["car"] = {"intent": "charge" if d["charge"] else "stop", "ctx": {"current": d["current"], **({"phases": d["phases"]} if d.get("phases") else {})}}
        out.update(self._more_intents(f, res, out.get("car")))
        return out

    def _share(self, want: dict[str, Any], f: dict[str, Any]) -> dict[str, dict[str, Any]]:
        """More batteries: the same thing to all - the same level to charge to or hold at - with the power shared by
        what each can take. Battery 1 keeps its share under "battery", the others get theirs (bat2 …)."""
        from . import batteries

        s = self.ov.settings
        more = batteries.extras(s)
        c1 = float(s.get("battery_charge_kw") or 3)
        d1 = float(s.get("battery_discharge_kw") or s.get("battery_charge_kw") or 3)
        cs = [c1] + [float(b.get("charge_kw") or 3) for b in more]
        ds = [d1] + [float(b.get("discharge_kw") or b.get("charge_kw") or 3) for b in more]
        packs = f.get("batteries") or []
        ctx = want["ctx"]
        out = {}
        for i, part in enumerate(["battery", *self.bat_parts()]):
            cshare, dshare = cs[i] / sum(cs), ds[i] / sum(ds)
            share = dshare if want["intent"] == "export" else cshare
            own = packs[i]["soc"] if i < len(packs) and packs[i].get("soc") is not None else ctx["soc"]
            info = {"device": getattr(self, "battery_device", None) or "", "serial": getattr(self, "battery_serial", "") or ""} if i == 0 \
                else self.bat_info.get(part) or {}
            c = {**ctx, "soc": round(max(own, ctx.get("min_soc") or 0)), "power_w": round(ctx["power_w"] * share), "power_kw": round(ctx["power_kw"] * share, 2),
                 "max_power_w": round(ctx["max_power_w"] * dshare), "max_power_kw": round(ctx["max_power_kw"] * dshare, 2),
                 "max_charge_w": round(ctx["max_charge_w"] * cshare), "max_charge_kw": round(ctx["max_charge_kw"] * cshare, 2),
                 "export_w": int(round(ctx.get("export_w", 0) * dshare / 50) * 50),
                 **({"charge_a": max(1, round(ctx["charge_a"] * cshare))} if "charge_a" in ctx else {}),
                 "device_id": info.get("device") or "", "serial": info.get("serial") or ""}
            out[part] = {"intent": want["intent"], "ctx": c}
        return out

    def _more_intents(self, f: dict[str, Any], res: dict[str, Any], first: dict[str, Any] | None) -> dict[str, dict[str, Any]]:
        """The extra chargers, one after the other: charger 1 comes first, then 2 … - the sun's surplus and the room
        under the main fuse that the chargers before have taken are gone for the next. So the last one is turned
        down (and stopped) first."""
        from . import chargers
        from .carspeed import VOLT, decide

        more = chargers.extras(self.ov.settings)
        if not more:
            return {}
        tz = ZoneInfo(self.ha.config.get("time_zone") or "UTC")
        now = datetime.now(tz)
        st = self.ov.settings

        def watts(want: dict[str, Any] | None, kw: float, phases: Any) -> float:
            if not want or want["intent"] != "charge":
                return 0.0
            ph = int(phases or (3 if kw > 7.5 else 1))
            return float(want["ctx"]["current"]) * VOLT * ph

        main_kw = float(st.get("charger_kw") or 7.4)
        taken = watts(first, main_kw, ((first or {}).get("ctx") or {}).get("phases") or st.get("charger_phases"))
        cars_now = sum(max(0.0, x.get("power") or 0.0) for x in (f.get("cars") or []))
        main_now = max(0.0, (f.get("ev") or 0.0) - cars_now)  # flow's ev has all the chargers in it
        base_grid = (f.get("grid") - main_now - cars_now) if f.get("grid") is not None else None
        out = {}
        for part, c, now_c, plan in zip(self.car_parts(), more, f.get("cars") or [{}] * len(more), res.get("cars") or [{}] * len(more)):
            kw = float(c.get("charger_kw") or 7.4)
            slot = int((plan or {}).get("slot_min") or 60)
            hour = now.replace(minute=now.minute // slot * slot if slot < 60 else 0, second=0, microsecond=0)
            planned = hour in {datetime.fromisoformat(t) for t in ((plan or {}).get("hours") or [])}
            own = max(0.0, now_c.get("power") or 0.0)
            # This car sees the house as using what the chargers before it want - sun and fuse alike.
            g = None if base_grid is None else base_grid + taken + own
            flow = {"pv": f.get("pv"), "house": None if f.get("house") is None else f["house"] + taken,
                    "battery": f.get("battery"), "plug": now_c.get("plug"), "ev": own, "grid": g}
            cs = {**st, "charger_kw": kw, "charger_phases": c.get("phases"),
                  "peak_kw": (self.engine.power_tariff() or {}).get("limit_kw") if getattr(self, "engine", None) else None,
                  "ev_follow_sun": c.get("follow_sun", st.get("ev_follow_sun", bool(self.ov.role("pv_power")))), "onoff": self.onoff(part),
                  "min_a": adapters.lowest_amps(getattr(self, "entities", {}).get(part, []), getattr(getattr(self, "ha", None), "states", {}))}
            cs["ev_mode"] = c.get("mode")  # each charger's own Cheapest/Sun choice
            cs.update(self._phase_settings(part, cs))
            need = float((plan or {}).get("need_kwh") if (plan or {}).get("need_kwh") is not None else 1.0)
            d = decide(flow, cs, planned, bool(c.get("now")), need, self._sun_on_more.get(part, False))
            self._sun_on_more[part], self.more_why[part] = d["sun"], d["why"]
            self._phase_seen(part, cs, d.get("phases"))
            want = {"intent": "charge" if d["charge"] else "stop", "ctx": {"current": d["current"], **({"phases": d["phases"]} if d.get("phases") else {})}}
            out[part] = want
            taken += watts(want, kw, d.get("phases") or c.get("phases"))
        return out

    PHASE_HOLD_S = 600  # at most one change between 1 and 3 phases per 10 minutes (the car pauses at each)

    def _phase_settings(self, part: str, st: dict[str, Any]) -> dict[str, Any]:
        """What decide() needs to switch phases - only with the setting on and a phase choice on the charger."""
        if not st.get("ev_phase_switch"):
            return {}
        pc = adapters.phase_control(self.entities.get(part, []), self.ha.states)
        if not pc:
            return {}
        held = time.time() - self._phase_at.get(part, 0) < self.PHASE_HOLD_S
        return {"phase_switch": True, "phase_now": pc["now"], "phase_lock": held and pc["now"] is not None}

    def _phase_seen(self, part: str, st: dict[str, Any], phases: int | None) -> None:
        if phases and st.get("phase_switch") and st.get("phase_now") and phases != st["phase_now"]:
            self._phase_at[part] = time.time()

    def _phase_call(self, part: str, want: dict[str, Any]) -> list[dict[str, Any]]:
        ph = (want.get("ctx") or {}).get("phases")
        if want.get("intent") != "charge" or ph not in (1, 3):
            return []
        pc = adapters.phase_control(self.entities.get(part, []), self.ha.states)
        if not pc:
            return []
        if pc.get("switch"):
            return [{"domain": "switch", "service": f"turn_{pc[str(ph)]}", "data": {"entity_id": pc["entity"]}}]
        return [{"domain": "select", "service": "select_option", "data": {"entity_id": pc["entity"], "option": pc[str(ph)]}}]

    def calls(self, part: str, want: dict[str, Any]) -> list[dict[str, Any]]:
        if part == "generator":
            e = self.ov.role("generator_switch")
            if not e:
                return []
            return [{"domain": e.split(".")[0], "service": "turn_on" if want["intent"] == "run" else "turn_off", "data": {"entity_id": e}}]
        if self.is_battery(part):
            steps = self.profile_steps(part) or {}
            # A profile without a way to sell runs normally instead (the plan doesn't sell then anyway).
            calls = self._clamp(adapters.resolve(steps.get(want["intent"]) or steps.get("normal", []), self._pool(part), want["ctx"]))
            return self._fixed(part, want["intent"], calls)
        if part.startswith("car") and part != "car":
            return self._phase_call(part, want) + self._clamp(adapters.charger_calls(
                want["intent"], self.entities.get(part, []), self.platforms.get(part), want["ctx"]["current"],
                self.car_devices.get(part), self.ha.states, switch=self.auto_switch(part)))
        return self._phase_call("car", want) + self._clamp(adapters.charger_calls(
            want["intent"], self.entities["car"], self.platforms["car"], want["ctx"]["current"],
            getattr(self, "car_device", None), self.ha.states, switch=self.auto_switch("car")))

    def _clamp(self, calls: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Numbers within the control's own min/max - Home Assistant refuses a value outside them. A select value
        written "re:<pattern>" is the control's own option that matches (SolarAssistant names a mode its own way); any
        other option not in the control's list is matched to it ignoring case, spaces and underscores."""
        out = []
        for c in calls:
            d = c["data"]
            if c.get("service") == "select_option" and str(d.get("option", "")).startswith("re:"):
                a = (self.ha.states.get(d.get("entity_id")) or {}).get("attributes") or {}
                opt = adapters.pick_option(str(d["option"])[3:], a.get("options") or [])
                if opt is None:
                    _LOGGER.warning("No option like %s on %s", d["option"][3:], d.get("entity_id"))
                    continue
                d["option"] = opt
            elif c.get("service") == "select_option" and d.get("option") is not None:
                # A profile's option written as the label ("Maximise self consumption") where the integration has
                # the value ("maximise_self_consumption"), or the other way round: the control's own one is used.
                opts = ((self.ha.states.get(d.get("entity_id")) or {}).get("attributes") or {}).get("options") or []
                if opts and d["option"] not in opts:
                    key = re.sub(r"[^a-z0-9]", "", str(d["option"]).lower())
                    d["option"] = next((o for o in opts if re.sub(r"[^a-z0-9]", "", str(o).lower()) == key), d["option"])
            out.append(c)
        calls = out
        for c in calls:
            d = c["data"]
            if c.get("service") == "set_value" and isinstance(d.get("value"), (int, float)):
                a = (self.ha.states.get(d.get("entity_id")) or {}).get("attributes") or {}
                try:
                    lo, hi = float(a.get("min", "-inf")), float(a.get("max", "inf"))
                except (TypeError, ValueError):
                    continue
                v = min(hi, max(lo, d["value"]))
                d["value"] = int(v) if float(v).is_integer() else v
        return calls

    async def tick(self, parts: tuple[str, ...] | None = None) -> None:
        testing = getattr(self, "testing", set())
        for part, want in self.intents().items():
            if part in testing or (part.startswith("car") and "car" in testing):
                continue  # the test drives it now (selftest.py)
            if time.time() < getattr(self, "safe_until", {}).get(part, 0) and want.get("intent") not in (None, "normal"):
                want = {**want, "intent": "normal"}  # it did the opposite of what it was told: safe until checked
            if parts is not None and part not in parts and not (part.startswith("car") and "car" in parts):
                continue
            mode = self.mode(part)
            if mode == "off":
                continue
            calls = self.calls(part, want)
            prev = self.last.get(part)
            changed = prev is None or prev["intent"] != want["intent"] or prev["ctx"] != want["ctx"]
            prof = self._prof(part)
            again = prof.get("reassert_s", REASSERT_S) if self.is_battery(part) else REASSERT_S
            due = prev is None or time.time() - prev["t"] > again  # Solis' remote control times out after 30 min
            # A value that held and then changed by itself is set again at once (at most once a minute) - the
            # inverter put back its default, or something else changed it.
            if not (changed or due) and mode == "control" and prev.get("result") == "ok" and time.time() - prev["t"] > 60:
                moved = [c["data"]["entity_id"] for c in calls if self._matches(c) is False]
                if moved:
                    now_t = time.time()
                    _LOGGER.info("%s changed back by itself - set again: %s", part, ", ".join(moved))
                    if not ((adapters.PROFILES.get(self.profile_key(part) or "") or {}).get("resets_itself") and self.is_battery(part)):
                        # (Victron puts its own defaults back - that isn't another system steering)
                        self.drift[part] = [d for d in self.drift.get(part, []) if now_t - d[0] < 3600] + [(now_t, e) for e in moved]
                    due = True
            if not (changed or due):
                continue
            entry = {"t": time.time(), "intent": want["intent"], "ctx": want["ctx"], "calls": calls, "mode": mode}
            if mode == "control" and not self.blocked(part):
                restored = self._restore(part, want["intent"])
                calls = calls + restored
                entry["calls"] = calls
                # An inverter that forgets what it was told (Victron) or whose timer only starts over on a write (Solis,
                # SolarEdge) gets every value written each time - not only the changed ones, or an unchanged one (the
                # maximum charge power while the power follows the slot) is never written again and goes stale.
                force = self._forced(prof) and self.is_battery(part)
                if self.is_battery(part):
                    async with self._lock():
                        entry["result"] = await self._send(calls, force=force)
                else:
                    entry["result"] = await self._send(calls)
                if entry["result"] != "ok":  # what failed, for the developer's view of the brand (setupinfo.py)
                    errs = getattr(self, "part_errors", None)
                    if errs is None:
                        errs = self.part_errors = {}
                    entry["error"] = getattr(self, "last_send_error", None)
                    msg = f"{want['intent']}: {getattr(self, 'last_send_error', None) or entry['result']}"[:200]
                    if msg not in errs.setdefault(part, []):
                        errs[part] = (errs[part] + [msg])[-3:]
                if not changed:
                    self._note_resent(part, "due")
                if entry["result"] == "ok" and want["intent"] != "export" and self.is_battery(part):
                    back = {c["data"].get("entity_id") for c in calls[len(calls) - len(restored):]} if restored else set()
                    left = {e: v for e, v in (self.ov.settings.get("restore_values") or {}).items() if e not in back}
                    if left != (self.ov.settings.get("restore_values") or {}):
                        self.ov.save({"restore_values": left})
            elif mode == "control":
                entry["blocked"] = self.blocked(part)
            self.last[part] = entry
            if changed:
                self.log.setdefault(part, deque(maxlen=60)).appendleft(entry)

    def _battery_volt(self) -> float:
        """The battery's voltage: the BMS voltage on the battery level sensor, a battery voltage sensor, else 52 V."""
        states = self.ha.states
        try:
            soc = self.ov.roles().get("battery_soc")
        except Exception:  # noqa: BLE001
            soc = None
        for k in ("BMS Voltage", "bms_voltage", "voltage"):
            v = _num(((states.get(soc) or {}).get("attributes") or {}).get(k)) if soc else None
            if v and 40 <= v <= 1000:
                return v
        pre = soc.split(".", 1)[1].rsplit("_battery", 1)[0] if soc and "_battery" in soc else ""
        for e in sorted(states, key=lambda e: (pre not in e, e)):
            if re.fullmatch(r"sensor\..*battery_voltage", e):
                v = _num((states[e] or {}).get("state"))
                if v and 40 <= v <= 1000:
                    return v
        return 52.0

    def _restore(self, part: str, intent: str) -> list[dict[str, Any]]:
        """Settings that are the owner's own (Victron's grid setpoint, Deye's work mode when selling, Deye's grid charge
        current when charging): remembered before EP changes them, put back when that stops - kept on disk, so a
        restart in between doesn't lose them."""
        prof = (adapters.PROFILES.get(self.profile_key(part) or "") or {}) if self.is_battery(part) else {}
        by_intent = {"export": prof.get("restore") or [], "charge": prof.get("restore_charge") or []}
        pats = by_intent["export"] + by_intent["charge"]
        if not pats:
            return []
        pool = self._pool(part)
        saved = dict(self.ov.settings.get("restore_values") or {})
        keep = set()  # what EP sets now: remembered (once), not put back
        for p in by_intent.get(intent) or []:
            e = adapters._find(p, pool)
            if not e:
                continue
            keep.add(e)
            st = (self.ha.states.get(e) or {}).get("state")
            if e not in saved and st not in (None, "unknown", "unavailable"):
                saved[e] = "0" if _negative(e, st) else st  # a setpoint already selling is ours, not the owner's
        if saved != (self.ov.settings.get("restore_values") or {}):
            self.ov.save({"restore_values": saved})
        if intent == "export":
            return []
        mine = {e: v for e, v in saved.items() if e in pool and e not in keep}  # each inverter remembers its own
        pats = by_intent["export"]
        out = []
        # Not selling any more: a grid setpoint still below 0 keeps the inverter selling (Victron does exactly what it
        # is told) - back to 0, also when nothing was remembered (an older version kept a selling value as the owner's).
        for p in pats:
            e = adapters._find(p, pool)
            if e and e not in mine and _negative(e, (self.ha.states.get(e) or {}).get("state")):
                mine[e] = "0"
        for e, v in mine.items():
            if _negative(e, v):
                v = "0"
            if e.startswith("select."):
                out.append({"domain": "select", "service": "select_option", "data": {"entity_id": e, "option": v}})
            elif e.startswith("switch."):
                if v in ("on", "off"):
                    out.append({"domain": "switch", "service": f"turn_{v}", "data": {"entity_id": e}})
            else:
                try:
                    num = float(v)
                except ValueError:
                    continue
                out.append({"domain": e.split(".")[0], "service": "set_value", "data": {"entity_id": e, "value": int(num) if num.is_integer() else num}})
        return out

    def _lock(self) -> asyncio.Lock:
        if getattr(self, "_bat_lock", None) is None:
            self._bat_lock = asyncio.Lock()
        return self._bat_lock

    def _fixed(self, part: str, intent: str, calls: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """An option the test found works on this installation is used instead of the profile's (see selftest.py);
        else one that 3 other installations with the same profile found (telemetry.py) - only when this inverter
        offers it, and never one the user undid."""
        fx = (((self.ov.settings.get("profile_fixes") or {}).get(part) or {}).get(intent)) or {}
        shared = [f for f in ((self.ov.settings.get("community") or {}).get("fixes") or [])
                  if f.get("profile") == self.profile_key(part) and f.get("intent") == intent
                  and f"{intent}|{f.get('from')}|{f.get('to')}" not in (self.ov.settings.get("community_ignore") or [])]
        if not fx and not shared:
            return calls
        out = []
        for c in calls:
            e = c["data"].get("entity_id")
            if c.get("service") == "select_option" and e in fx:
                c = {**c, "data": {**c["data"], "option": fx[e]["to"]}}
            elif c.get("service") == "select_option":
                opts = ((self.ha.states.get(e) or {}).get("attributes") or {}).get("options") or []
                hit = next((f for f in shared if f.get("from") == c["data"].get("option") and f.get("to") in opts), None)
                if hit:
                    c = {**c, "data": {**c["data"], "option": hit["to"]}}
                    self.__dict__.setdefault("community_used", {})[f"{intent}|{hit['from']}|{hit['to']}"] = {"intent": intent, "from": hit["from"], "to": hit["to"]}
            out.append(c)
        return out

    @staticmethod
    def _forced(prof: dict[str, Any]) -> bool:
        """Written again on time even when Home Assistant shows the value: the inverter forgets it (Victron) or a
        remote-control timer only starts over on a write (Solis, SolarEdge)."""
        return bool(prof.get("resets_itself") or prof.get("keepalive"))

    def _prof(self, part: str) -> dict[str, Any]:
        return (adapters.PROFILES.get(self.profile_key(part) or "") or {}) if self.is_battery(part) else {}

    def _note_resent(self, part: str, why: str) -> None:
        """The log lists changes only; a value sent again is counted on the change it repeats (seen in diagnostics)."""
        log = self.log.get(part)
        if log:
            log[0]["resent"] = int(log[0].get("resent", 0)) + 1
            log[0]["resent_last"] = {"t": time.time(), "why": why}

    async def keep(self) -> None:
        """Every minute, for inverters that forget what they were told (Victron, EcoFlow): the last values are sent
        again on time - not up to a round later - and at once when a control is back after being unavailable."""
        now_t = time.time()
        for part in ["battery", *self.bat_parts()]:
            if part in getattr(self, "testing", set()):
                continue
            prof = self._prof(part)
            prev = self.last.get(part)
            if (not prof.get("reassert_s") or not prev or prev.get("mode") != "control" or "result" not in prev
                    or self.mode(part) != "control" or self.blocked(part) or self._lock().locked()):
                continue
            ids = {c["data"].get("entity_id") for c in prev["calls"] if isinstance(c["data"].get("entity_id"), str)}
            state = {e: (self.ha.states.get(e) or {}).get("state") for e in ids}
            down = {e for e, v in state.items() if v == "unavailable"}
            # "unknown" isn't gone: Victron's integration shows it when the GX hasn't repeated the value for 5
            # minutes - writing it now brings it back.
            blank = {e for e, v in state.items() if v == "unknown"}
            back = self._gone.get(part, set()) - down
            self._gone[part] = (self._gone.get(part, set()) & ids) | down
            if down:
                continue  # nothing can be written while it's away
            why = "back" if back else "unknown" if blank else "due" if now_t - prev["t"] > prof["reassert_s"] else None
            if not why:
                continue
            self._gone[part] = set()
            if why == "back":
                _LOGGER.info("%s controls are back (%s) - set again", part, ", ".join(sorted(back)))
            async with self._lock():
                prev["result"] = await self._send(prev["calls"], force=why != "due" or self._forced(prof))
            prev["t"] = time.time()
            self._note_resent(part, why)

    async def _send(self, calls: list[dict[str, Any]], force: bool = False) -> str:
        """Send the calls - only those whose value isn't already set (some links, like Solarman, drop writes now
        and then, so fewer writes is safer), or all of them when forced. A value that didn't stick is sent once more."""
        todo = list(calls) if force else [c for c in calls if not self._matches(c)]
        self.last_send_error = None
        for attempt in range(2):
            raised = []
            for c in todo:
                try:
                    await self.ha.call_service(c["domain"], c["service"], dict(c["data"]))
                    await asyncio.sleep(1.5)  # inverters take one change at a time
                except Exception as err:  # noqa: BLE001
                    _LOGGER.warning("Control call %s.%s failed: %s", c["domain"], c["service"], err)
                    self.last_send_error = f"{c['domain']}.{c['service']}: {err}"[:300]
                    raised.append(c)
                    if attempt:
                        return f"failed: {c['domain']}.{c['service']}"
            if not todo:
                return "ok"
            await asyncio.sleep(15)
            # A call that raised is tried once more - a service can't be read back, so it would otherwise count as done.
            todo = [c for c in calls if self._matches(c) is False or c in raised]
            if not todo:
                return "ok"
            if not attempt:
                _LOGGER.info("Not taken, sending again: %s", ", ".join(c["data"].get("entity_id", "") for c in todo))
        return "not_confirmed"

    def _matches(self, c: dict[str, Any]) -> bool | None:
        """Has this control the wanted value already? None: it can't be read back (a switch, a service)."""
        data = c["data"]
        e = data.get("entity_id")
        if c.get("service") in ("turn_on", "turn_off") and isinstance(e, str) and e.split(".")[0] in ("switch", "input_boolean"):
            state = (self.ha.states.get(e) or {}).get("state")
            return None if state not in ("on", "off") else state == c["service"][5:]  # a switch already on/off: not sent again
        want = data.get("option", data.get("value"))
        if not isinstance(e, str) or want is None or e not in self.ha.states:
            return None
        state = self.ha.states[e].get("state")
        try:
            return abs(float(state) - float(want)) <= 0.6
        except (TypeError, ValueError):
            return str(state) == str(want)

    OTHER = 3  # changed back this many times in an hour: something else is steering too
    WRONG_S = 15 * 60  # the battery doing the opposite this long: back to normal …
    SAFE_S = 3600  # … for an hour, with a warning
    CAR_IDLE_S = 10 * 60  # told to charge, plugged in, nothing flows this long: stop and start once

    @staticmethod
    def _opposite(intent: str, f: dict[str, Any]) -> bool:
        """Clearly the opposite of what it was told - not just slower (a full battery, a taper, the house's use)."""
        b = f.get("battery")
        if b is None:
            return False
        if intent == "charge":
            return b < -300
        if intent == "export":
            return b > 300 and (f.get("grid") or 0) > 300
        if intent == "hold":
            return b < -800
        return False

    async def guard(self) -> None:
        """Every minute while Energy Pilot controls: a battery doing the opposite of what it was told goes back to
        normal (the safe way) and the user is told; a charger that doesn't start is stopped and started once."""
        now_t = time.time()
        f = self.ov.flow()
        prev = self.last.get("battery")
        if (self.mode("battery") == "control" and "battery" not in self.testing and prev and prev.get("result") == "ok"
                and not self.blocked("battery") and not self.bat_parts() and now_t >= self.safe_until.get("battery", 0)):
            if self._opposite(prev["intent"], f):
                since = self._wrong.setdefault("battery", now_t)
                if now_t - since >= self.WRONG_S and now_t - prev["t"] >= self.WRONG_S:
                    _LOGGER.warning("The battery did the opposite of %s for %d min - back to normal for an hour", prev["intent"], self.WRONG_S // 60)
                    self.safe_until["battery"] = now_t + self.SAFE_S
                    self.safe_why = prev["intent"]
                    self._wrong.pop("battery", None)
                    self.last.pop("battery", None)
                    await self.tick(("battery",))
            else:
                self._wrong.pop("battery", None)
        else:
            self._wrong.pop("battery", None)
        # The charger: told to charge, the car in, nothing flowing.
        prev = self.last.get("car")
        if not f.get("plug"):
            self._car_idle.pop("car", None)
            self._kicked.pop("car", None)
            self.car_stuck.pop("car", None)
            return
        if (self.mode("car") != "control" or "car" in self.testing or not prev or prev.get("intent") != "charge"
                or prev.get("result") != "ok" or (f.get("ev") or 0) >= 100):
            self._car_idle.pop("car", None)
            if (f.get("ev") or 0) >= 100:
                self.car_stuck.pop("car", None)
            return
        since = self._car_idle.setdefault("car", now_t)
        if now_t - since < self.CAR_IDLE_S or now_t - prev["t"] < self.CAR_IDLE_S:
            return
        if not self._kicked.get("car"):
            _LOGGER.info("The car is in and told to charge, but nothing flows - stopping and starting the charger once")
            self._kicked["car"] = True
            await self._send(self.calls("car", {"intent": "stop", "ctx": prev.get("ctx") or {"current": 6}}), force=True)
            await asyncio.sleep(30)
            self.last.pop("car", None)
            self._car_idle.pop("car", None)
            await self.tick(("car",))
        else:
            self.car_stuck["car"] = True  # shown as a note: the car may be full or wait for its own timer

    def watch_checks(self) -> list[dict[str, Any]]:
        """Warnings for the self-check: another system steers the battery too (Predbat, an automation, the inverter's
        own schedule) - they work against each other."""
        out = []
        now_t = time.time()
        for part, seen in self.drift.items():
            recent = [e for t, e in seen if now_t - t < 3600]
            if self.mode(part) == "control" and len(recent) >= self.OTHER:
                names = ", ".join(sorted({e.split(".", 1)[1] for e in recent}))
                out.append({"key": "other_control", "level": "warn", "vals": {"list": names}, "goto": "battery"})
        if now_t < getattr(self, "safe_until", {}).get("battery", 0):
            out.append({"key": "acting_wrong", "level": "warn", "vals": {"intent": getattr(self, "safe_why", "")}, "goto": "battery"})
        if getattr(self, "car_stuck", {}).get("car"):
            out.append({"key": "charger_stuck", "level": "info", "vals": {}, "goto": "car"})
        pm = str((self.ha.states.get("select.predbat_mode") or {}).get("state") or "")
        if self.mode("battery") == "control" and pm and pm.lower() not in ("monitor", "unavailable", "unknown"):
            out.append({"key": "predbat_on", "level": "warn", "vals": {"mode": pm}, "goto": "battery"})
        return out

    def _took(self, calls: list[dict[str, Any]]) -> bool:
        """Did the controls take the values? (Selects and numbers that can be read back.)"""
        return all(self._matches(c) is not False for c in calls)

    async def release(self) -> None:
        """Back to shadow: the battery is put back to normal first, the charger is left as it is."""
        wants = self.intents()
        for part in ["battery", *self.bat_parts()]:
            if self.mode(part) == "control" and not self.blocked(part) and (want := wants.get(part)):
                await self._send(self.calls(part, {**want, "intent": "normal"}) + self._restore(part, "normal"))
        modes = {p: "shadow" for p in self.parts()}
        self.ov.save({"control": modes})
        self.last.clear()

    def status(self) -> dict[str, Any]:
        wants = self.intents()
        out = {}
        from . import chargers

        names = {p: c.get("name") or "" for p, c in zip(self.car_parts(), chargers.extras(self.ov.settings))}
        for part in self.parts():
            want = wants.get(part)
            out[part] = {
                "mode": self.mode(part), "blocked": self.blocked(part), "now": want,
                "calls": self.calls(part, want) if want else [], "log": list(self.log.get(part, []))[:20],
                "entities": self.entities.get(part, []),
            }
            if part in names:
                out[part].update(name=names[part], why=self.more_why.get(part, ""))
            if part.startswith("bat"):
                key = self.profile_key(part)
                prof = adapters.PROFILES.get(key or "") or {}
                out[part].update(name=self._extra_battery(part).get("name") or "", profile={
                    "key": key, "name": prof.get("name"), "model": (self.bat_info.get(part) or {}).get("model"),
                    "tested": bool(prof.get("tested")) if key else None, "check": self.check(part)})
        out["car_parts"] = self.car_parts()
        out["bat_parts"] = self.bat_parts()
        key = self.profile_key()
        prof = adapters.PROFILES.get(key or "") or {}
        out["profile"] = {"key": key, "name": prof.get("name") or ("custom" if key == "custom" else None),
                          "choices": {k: p["name"] for k, p in sorted(adapters.PROFILES.items(), key=lambda kv: kv[1]["name"].lower())},
                          "tested_keys": [k for k, p in adapters.PROFILES.items() if p.get("tested")],
                          "model": self.model, "tested": bool(prof.get("tested")) if key != "custom" else None, "check": self.check(),
                          # how many other installations with this profile have run the self-test (telemetry.py)
                          "community": ((self.ov.settings.get("community") or {}).get("tested") or {}).get(key or "")}
        # For "Chosen by you": every control in Home Assistant - the inverter's own first - not only the device
        # the battery level was found on (that could be the wrong one, e.g. a car).
        own = set(self.entities["battery"])
        everything = [e for e in self.ha.states if e.split(".")[0] in ("select", "number", "switch", "button", "time")]
        out["profile"]["all_controls"] = sorted(own) + sorted(e for e in everything if e not in own)
        return out


def _num(v: Any) -> float | None:
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def _negative(entity: str, value: Any) -> bool:
    """A grid setpoint below 0: the inverter sells to the grid."""
    if not entity.startswith("number.") or not re.search(r"grid_set_?point|acpowersetpoint", entity):
        return False
    try:
        return float(value) < 0
    except (TypeError, ValueError):
        return False

energy_pilot/curtail.py:
"""Stop selling solar when the price is negative: the inverter's export limit goes to 0 while selling would cost money,
and back to what it was afterwards. The house and the battery still use all the sun - only the grid gets none.

It follows the battery's mode: in shadow it only shows what it would do; in control it sets the chosen setting.
Off until the user turns it on and picks the setting (Settings -> Solar), because it changes the inverter.
"""

from __future__ import annotations

from datetime import datetime
import logging
import re
import time
from typing import Any

_LOGGER = logging.getLogger(__name__)
# Settings that limit what goes to the grid, by brand: a number in W or %, a mode to choose, or a switch.
PATTERNS = [
    r"^number\..*(export_limit|export_power_limit|feed_?in_limit|max_feed_?in|grid_export_limit|export_control_user_limit|export_power_rate|active_power_limit|zero_export|export_max)",
    r"^select\..*(export_limiter|active_power_control|export_rule|allow_export|limit_control_mode|export_limit_mode|zero_export)",
    r"^switch\..*(export_limit|export_power_limit|feed_?in|zero_export|grid_export)",
]
# By brand (the battery's inverter profile): the settings that stop the export, and the value. Growatt needs the
# limiter on AND the limit at 0 %.
PRESETS = {
    "growatt": [(r"^select\..*export_limiter$", "Enabled"), (r"^number\..*export_power_rate$", "0")],
    "growatt_tlxh": [(r"^select\..*export_limit(er)?(_enabled|_mode)?$", "Enabled"), (r"^number\..*export_(power_rate|limit_power_rate)$", "0")],
}
TEST_S = 120  # the test: how long it waits for the export to stop
RESET_S = 1800  # set again every 30 minutes while it lasts (an inverter may put its own value back)


def candidates(states: dict[str, Any]) -> list[dict[str, Any]]:
    """The settings in Home Assistant that look like an export limit - for the user to pick from."""
    out = []
    for e, st in states.items():
        if any(re.search(p, e) for p in PATTERNS) and (st.get("state") not in (None, "unavailable")):
            a = st.get("attributes") or {}
            out.append({"entity_id": e, "name": a.get("friendly_name") or e, "state": st.get("state"), "options": a.get("options"),
                        "unit": a.get("unit_of_measurement"), "min": a.get("min")})
    return sorted(out, key=lambda c: (not c["entity_id"].startswith("number."), c["name"]))


class Curtail:
    def __init__(self, ha: Any, ov: Any, controller: Any) -> None:
        self.ha, self.ov, self.ctl = ha, ov, controller
        self.last: dict[str, Any] = {}
        self.testing = False

    def suggest(self) -> dict[str, Any] | None:
        """What to use, from the brand: the known settings for the inverter - else the first export limit found (to 0)."""
        key = self.ctl.profile_key("battery") if self.ctl and hasattr(self.ctl, "profile_key") else None
        found = []
        for pat, val in PRESETS.get(key or "", []):
            e = next((x for x in sorted(self.ha.states) if re.search(pat, x)), None)
            if e:
                found.append((e, val))
        if found:
            return {"entity": found[0][0], "value": found[0][1], "extra": [list(x) for x in found[1:]], "from": key}
        num = next((c for c in candidates(self.ha.states) if c["entity_id"].startswith("number.")), None)
        return {"entity": num["entity_id"], "value": "0", "extra": [], "from": None} if num else None

    def targets(self) -> list[tuple[str, str]]:
        out = [(self.cfg["entity"], self.target())] if self.cfg.get("entity") and self.target() is not None else []
        return out + [(str(e), str(v)) for e, v in self.cfg.get("extra") or [] if e and e in self.ha.states]

    @property
    def cfg(self) -> dict[str, Any]:
        return self.ov.settings.get("curtail") or {}

    def sell_now(self) -> float | None:
        """What selling one kWh earns now: the feed-in price when it changes (a sensor or the tariff plan); otherwise
        the buying price itself when that is below 0 (then selling surely costs too)."""
        eng = self.ov.engine
        if not eng:
            return None
        now = datetime.now(eng.tz)
        sells = eng.sell_prices()
        if sells:
            return eng.sell_at(sells, now, 0.0)
        rows = [h for h in (self.ov.plan() or {}).get("hours") or [] if h.get("t") and h.get("price") is not None]
        past = [h for h in rows if datetime.fromisoformat(h["t"]) <= now]
        price = past[-1]["price"] if past else None
        return price if price is not None and price < 0 else 1.0

    def target(self) -> str | None:
        """The value that stops selling: 0 for a number, the chosen option for a mode, on/off for a switch."""
        e, c = self.cfg.get("entity") or "", self.cfg
        if e.startswith("number."):
            return str(c.get("value") if c.get("value") not in (None, "") else 0)
        if e.startswith(("select.", "switch.")):
            return str(c.get("value") or "") or None
        return None

    async def _set(self, e: str, v: str) -> bool:
        try:
            if e.startswith("number."):
                n = float(v)
                await self.ha.call_service(e.split(".")[0], "set_value", {"entity_id": e, "value": int(n) if n.is_integer() else n})
            elif e.startswith("select."):
                await self.ha.call_service("select", "select_option", {"entity_id": e, "option": v})
            elif e.startswith("switch."):
                await self.ha.call_service("switch", f"turn_{'on' if v == 'on' else 'off'}", {"entity_id": e})
            return True
        except Exception:  # noqa: BLE001
            _LOGGER.warning("Could not set %s", e, exc_info=True)
            return False

    async def tick(self) -> None:
        c = self.cfg
        if c.get("on") and not c.get("entity") and (sg := self.suggest()):
            self.ov.save({"curtail": {**c, **sg}})  # turned on: chosen from the brand (it can be changed)
            c = self.cfg
        if self.testing or not c.get("on") or not self.targets():
            if not c.get("on"):
                self.last = {}
            return
        sell = self.sell_now()
        want = sell is not None and sell < float(c.get("below", 0) or 0)
        mode = self.ctl.mode("battery") if self.ctl else "shadow"
        saved = self.ov.settings.get("curtail_saved")
        self.last = {"want": want, "sell": sell, "mode": mode, "active": saved is not None, "t": time.time()}
        if mode != "control":
            return
        # The battery is selling, or the test drives it: the same setting (a Deye's limit mode) is the battery's now.
        busy = self.ctl and ("battery" in getattr(self.ctl, "testing", set())
                             or ((getattr(self.ctl, "last", None) or {}).get("battery") or {}).get("intent") == "export")
        if want and busy:
            return
        if want:
            if saved is None:
                saved = {e: st for e, _v in self.targets() if (st := (self.ha.states.get(e) or {}).get("state")) not in (None, "unknown", "unavailable")}
                self.ov.save({"curtail_saved": saved})  # the owner's own values, put back afterwards
            again = time.time() - float(c.get("_t") or 0) > RESET_S
            todo = [(e, v) for e, v in self.targets() if again or (self.ha.states.get(e) or {}).get("state") != v]
            ok = [await self._set(e, v) for e, v in todo]
            if todo and all(ok):
                _LOGGER.info("Selling stopped - the price is %s", sell)
                self.ov.save({"curtail": {**c, "_t": time.time()}})
        elif saved is not None:
            await self._put_back(saved)
            self.ov.save({"curtail_saved": None})

    async def _put_back(self, saved: dict[str, Any]) -> None:
        if "entity" in saved and "value" in saved and len(saved) == 2:
            saved = {saved["entity"]: saved["value"]}  # (an older version kept one)
        for e, v in saved.items():
            if v is not None:
                await self._set(e, str(v))
                _LOGGER.info("Selling allowed again - %s back to %s", e, v)

    async def test(self) -> dict[str, Any]:
        """The guide's test: stop selling for up to 2 minutes and see the export fall to (nearly) 0 - then put it back."""
        import asyncio

        if self.testing:
            return self.ov.settings.get("curtail_test") or {}
        res: dict[str, Any] = {"t": time.time(), "targets": self.targets()}
        grid = (self.ov.flow() or {}).get("grid")
        res["grid_before"] = grid
        if not self.targets():
            res["result"] = "no_setting"
        elif grid is None or grid > -150:
            res["result"] = "no_sun"  # nothing is sold right now - nothing to see
        else:
            self.testing = True
            saved = {e: (self.ha.states.get(e) or {}).get("state") for e, _v in self.targets()}
            res["saved"] = saved
            try:
                sent = [await self._set(e, v) for e, v in self.targets()]
                if not all(sent):
                    res["result"] = "rejected"
                else:
                    res["result"] = "failed"
                    for _ in range(TEST_S // 5):
                        await asyncio.sleep(5)
                        g = (self.ov.flow() or {}).get("grid")
                        res["grid_after"] = g
                        if g is not None and g > -60:
                            res["result"] = "ok"
                            break
                res["states_after"] = {e: (self.ha.states.get(e) or {}).get("state") for e, _v in self.targets()}
            finally:
                await self._put_back(saved)
                self.testing = False
        self.ov.save({"curtail_test": res})
        _LOGGER.info("Stop-selling test: %s", res["result"])
        return res

    def status(self) -> dict[str, Any]:
        return {**self.last, "candidates": candidates(self.ha.states), "suggest": self.suggest(), "testing": self.testing,
                "test": self.ov.settings.get("curtail_test")}

energy_pilot/detect.py:
"""Finding what a home has, without being told: sun, battery, grid, house, car charger, prices, forecasts.

In this order, the first that gives an answer wins for each part:
1. Home Assistant's Energy dashboard (many have already picked solar, battery and grid there) - from its energy
   sensors to the power sensors on the same device.
2. Known integrations: price (Strømligning, Nord Pool, Energi Data Service, Tibber, …), solar forecast (Solcast,
   Forecast.Solar, …), chargers (KEBA, Easee, Zaptec, go-e, Wallbox, OCPP, …) and inverters (Growatt, Huawei,
   SolarEdge, Victron, GivEnergy, …).
3. Names and kinds: a power sensor called "…pv_power" is the sun, "…battery…state_of_charge" the battery level.

Every answer says where it came from, so the guide can show it ("found in your Energy dashboard").
"""

from __future__ import annotations

import logging
import re
from typing import Any

_LOGGER = logging.getLogger(__name__)

PRICE = ("stromligning", "nordpool", "energidataservice", "tibber", "octopus_energy", "entsoe", "easyenergy", "frank_energie",
         "awattar", "zonneplan_one", "amber", "elering")
SOLAR_FORECAST = ("solcast_solar", "forecast_solar", "open_meteo_solar_forecast", "solarman_forecast")
CHARGERS = ("keba", "easee", "zaptec", "goecharger", "go_e", "goe_charger", "wallbox", "ocpp", "ohme", "myenergi",
            "tesla_wall_connector", "evse_wifi", "openevse", "peblar", "alfen_wallbox", "v2c")
INVERTERS = ("growatt_server", "huawei_solar", "solaredge", "solaredge_modbus_multi", "victron", "victron_ble", "givenergy",
             "givenergy_local", "sungrow", "solax", "solax_modbus", "foxess", "foxess_modbus", "sofar", "fronius",
             "enphase_envoy", "goodwe", "sma", "deye", "solarman", "sunsynk", "growatt_local", "huawei_solar_modbus")
# Platforms whose "battery" is a phone's or a sensor's, never a home battery.
NOT_HOME_BATTERY = ("mobile_app", "zha", "matter", "mqtt_room", "ble_monitor", "bthome", "switchbot", "homekit_controller",
                    "eufy_security", "roborock", "ecovacs", "xiaomi_ble", "tado", "netatmo", "nest", "ring", "hue",
                    # Cars: their battery level is not the house battery (an ID. Buzz was taken for one)
                    "volkswagen_we_connect_id", "volkswagencarnet", "tesla", "tesla_fleet", "teslemetry", "tessie",
                    "bmw_connected_drive", "renault", "kia_uvo", "hyundai_kia_connect", "mercedes_me", "mbapi2020",
                    "polestar_api", "myskoda", "skodaconnect", "audiconnect", "nissan_leaf", "fordpass", "toyota",
                    "volvo", "volvooncall", "stellantis_vehicles", "smartcar", "seatconnect", "cupra_we_connect",
                    "jlrincontrol", "porscheconnect", "zoe", "leaf", "evcc_intg",
                    # Octopus Intelligent: the car's level and charge target (a Tesla was taken for the house battery)
                    "octopus_energy")

# The car's own battery level ("ev_soc"): only from a car's integration (or a device a car maker made), never by name
# alone - a phone, a watch, a Zigbee sensor, the house battery or the car's 12 V battery are all "battery %".
CAR_PLATFORMS = ("tesla", "tesla_custom", "tesla_fleet", "teslemetry", "tessie", "volkswagen_we_connect_id", "volkswagencarnet",
                 "myskoda", "skodaconnect", "audiconnect", "seatconnect", "cupra_we_connect", "porscheconnect",
                 "bmw_connected_drive", "mercedes_me", "mbapi2020", "kia_uvo", "hyundai_kia_connect", "renault", "zoe",
                 "nissan_leaf", "leaf", "polestar_api", "polestar", "volvo", "volvooncall", "volvo_cars", "fordpass",
                 "toyota", "stellantis_vehicles", "smartcar", "jlrincontrol", "mg_saic", "saic_ismart", "byd", "smart_hashtag",
                 "rivian", "lucid", "zeekr", "subaru", "mazda", "honda", "evcc_intg", "ocpp", "tronity", "carconnectivity")
CAR_BRANDS = re.compile(r"\b(tesla|volkswagen|vw|audi|skoda|škoda|seat|cupra|porsche|bmw|mercedes|kia|hyundai|renault|dacia|"
                        r"nissan|polestar|volvo|ford|toyota|lexus|peugeot|citro[eë]n|opel|vauxhall|ds automobiles|fiat|jeep|saic motor|"
                        r"byd|zeekr|xpeng|rivian|lucid|jaguar|land rover|honda|mazda|subaru|genesis|lynk)\b", re.I)
EV_SOC_WORDS = re.compile(r"state_of_charge|battery_level|\bsoc\b|_soc$|charge_level|battery_percent|ev_battery|hv_battery|"
                          r"battery_charge|ladestand|ladezustand|niveau_de_charge|batteriniveau|laddniva", re.I)
EV_SOC_NOT = re.compile(r"12v|12_v|car_battery|aux|auxiliary|lv_battery|low_voltage|starter|key|fob|phone|watch|tyre|tire|fuel|range|"
                        r"target|limit|min|max|setpoint|health|soh|temperature|temp|signal|rssi|wifi|sentry|charge_rate|"
                        r"remote|tag|tracker|predicted|forecast|estimate|at_departure|departure", re.I)


def car_socs(entities: list[dict[str, Any]], devices: list[dict[str, Any]], states: dict[str, Any]) -> list[dict[str, Any]]:
    """The cars' battery levels found: [{"entity_id", "device", "score"}], best first. A sensor in %, 0-100, from a car
    integration or a device made by a car maker, named like a battery level - and none of the look-alikes."""
    makers = {d["id"]: f"{d.get('manufacturer') or ''} {d.get('model') or ''}" for d in devices}
    out = []
    for e in entities:
        eid, platform, dev = e["entity_id"], e.get("platform"), e.get("device_id")
        if not eid.startswith("sensor.") or e.get("disabled_by"):
            continue
        s = states.get(eid) or {}
        a = s.get("attributes") or {}
        if a.get("unit_of_measurement") != "%":
            continue
        car = platform in CAR_PLATFORMS or bool(dev and CAR_BRANDS.search(makers.get(dev, "")))
        if not car or platform in GADGETS:  # a phone or a sensor on a device a car maker's name matches is still that
            continue
        text = f"{eid} {a.get('friendly_name', '')}"
        # Always named like the driving battery: a plain "battery" with device class battery is often the 12 V one (Ford).
        if EV_SOC_NOT.search(text):
            continue
        weak = not EV_SOC_WORDS.search(text)  # a % on the car named otherwise: offered to choose, never picked by itself
        if weak and re.search(r"_battery$|^sensor\.battery$", eid):
            continue  # a plain "battery" on a car is often the 12 V one (Ford) - not even offered
        try:
            v = float(s.get("state"))
            if not 0 <= v <= 100:
                continue
        except (TypeError, ValueError):
            if s.get("state") not in ("unavailable", "unknown"):
                continue  # a car asleep may be unknown for a while - that's fine
        score = 2 * (a.get("device_class") == "battery") + 2 * bool(re.search(r"state_of_charge|battery_level|\bsoc\b|_soc$", eid)) \
            + (platform in CAR_PLATFORMS) - (platform == "ocpp")  # the car's own app knows best; a charger only while it charges
        if weak:
            score = -5
        out.append({"entity_id": eid, "device": dev or eid, "score": score})
    return sorted(out, key=lambda r: -r["score"])


GADGETS = ("mobile_app", "zha", "zwave_js", "matter", "mqtt_room", "ble_monitor", "bthome", "switchbot", "homekit_controller",
           "xiaomi_ble", "hue", "deconz", "tuya", "shelly", "esphome_ble", "bluetooth", "ibeacon", "private_ble_device")

WORDS = {
    "pv_power": [r"\bpv\b|pv_power|pv_effekt|solar_power|solar_production|sol_produktion|input_power|photovoltaic"],
    "battery_power": [r"battery.*(power|effekt)|batteri.*(effekt|power)|charge_discharge_power"],
    "battery_soc": [r"state_of_charge|\bsoc\b|battery_level|batteri_niveau|battery_percentage"],
    "grid_power": [r"grid.*(power|effekt)|net.*(effekt|power)|meter_power|import_export|active_power_grid"],
    "house_power": [r"house|hus|home_(load|power|consumption)|load_power|forbrug|consumption_power"],
}
EXCLUDE = re.compile(r"forecast|prognose|today|daily|total|max|min|limit|setpoint|target|estimate|_rate$|cost|price")


async def detect(ha: Any) -> dict[str, dict[str, str]]:
    """{role: {"entity_id": …, "source": "energy" | "integration:<platform>" | "name"}}"""
    found: dict[str, dict[str, str]] = {}
    try:
        entities = await ha.command({"type": "config/entity_registry/list"})
        devices = await ha.command({"type": "config/device_registry/list"})
    except Exception:  # noqa: BLE001 - not allowed or old HA: names only
        entities, devices = [], []
    by_id = {e["entity_id"]: e for e in entities}
    on_device: dict[str, list[dict[str, Any]]] = {}
    for e in entities:
        if e.get("device_id") and not e.get("disabled_by"):
            on_device.setdefault(e["device_id"], []).append(e)
    dev_names = {d["id"]: (d.get("name_by_user") or d.get("name") or "") for d in devices}
    states = ha.states

    def attrs(entity_id: str) -> dict[str, Any]:
        return (states.get(entity_id) or {}).get("attributes") or {}

    def alive(entity_id: str) -> bool:
        return (states.get(entity_id) or {}).get("state") not in (None, "unavailable", "unknown")

    def sibling(entity_id: str, device_class: str, words: str | None = None) -> str | None:
        """A sensor of this device class on the same device as entity_id."""
        dev = (by_id.get(entity_id) or {}).get("device_id")
        best = None
        for e in on_device.get(dev, []):
            eid = e["entity_id"]
            if eid.startswith("sensor.") and attrs(eid).get("device_class") == device_class and alive(eid):
                if words is None or re.search(words, eid):
                    return eid
                best = best or eid
        return best

    def put(role: str, entity_id: str | None, source: str) -> None:
        if entity_id and role not in found and entity_id in states:
            found[role] = {"entity_id": entity_id, "source": source}

    # 1. The Energy dashboard.
    try:
        prefs = await ha.command({"type": "energy/get_prefs"})
    except Exception:  # noqa: BLE001
        prefs = {}
    for src in prefs.get("energy_sources") or []:
        kind = src.get("type")
        if kind == "solar":
            put("pv_power", src.get("stat_rate") or sibling(src.get("stat_energy_from", ""), "power", r"pv|solar|sol"), "energy")
        elif kind == "battery":
            put("battery_power", src.get("stat_rate") or sibling(src.get("stat_energy_from", ""), "power", r"batt"), "energy")
            put("battery_soc", sibling(src.get("stat_energy_from", ""), "battery"), "energy")
        elif kind == "grid":
            put("grid_power", src.get("stat_rate") or sibling(((src.get("flow_from") or [{}])[0]).get("stat_energy_from", ""), "power"), "energy")
            price = ((src.get("flow_from") or [{}])[0]).get("entity_energy_price")
            put("price", price, "energy")
    for dev in prefs.get("device_consumption") or []:
        stat = dev.get("stat_consumption", "")
        platform = (by_id.get(stat) or {}).get("platform")
        if platform in CHARGERS or re.search(r"charg|lader|wallbox|ev_|elbil", stat):
            put("ev_power", dev.get("stat_rate") or sibling(stat, "power"), "energy")

    # 2. Known integrations.
    prices: list[tuple[int, str, str]] = []
    for e in entities:
        eid, platform = e["entity_id"], e.get("platform")
        if e.get("disabled_by") or not alive(eid):
            continue
        a = attrs(eid)
        if platform in PRICE and eid.startswith("sensor.") and str(a.get("unit_of_measurement", "")).lower().endswith("/kwh"):
            # The one with the coming prices, preferably the price you pay (with tax).
            if any(isinstance(a.get(k), list) for k in ("prices", "raw_today", "forecast", "today")):
                score = 3 if re.search(r"current|aktuel", eid) else 2 if re.search(r"total", eid) else 1
                prices.append((score, -len(eid), eid, platform))
        elif platform in SOLAR_FORECAST and eid.startswith("sensor."):
            if "peak" in eid or "remaining" in eid:
                continue
            if re.search(r"forecast_today$|energy_production_today$|production_today$", eid):
                put("solar_today", eid, f"integration:{platform}")
            elif re.search(r"forecast_tomorrow$|energy_production_tomorrow$|production_tomorrow$", eid):
                put("solar_tomorrow", eid, f"integration:{platform}")
        elif platform in CHARGERS:
            if eid.startswith("sensor.") and a.get("device_class") == "power" and not EXCLUDE.search(eid):
                put("ev_power", eid, f"integration:{platform}")
            elif eid.startswith("binary_sensor.") and (a.get("device_class") == "plug" or re.search(r"plug|cable|stik", eid)):
                put("ev_plug", eid, f"integration:{platform}")
            elif eid.startswith("sensor.") and re.search(r"session_energy|session|energy_charged|added_energy", eid):
                put("ev_session", eid, f"integration:{platform}")
        elif platform in INVERTERS and eid.startswith("sensor."):
            for role, patterns in WORDS.items():
                cls = "battery" if role == "battery_soc" else "power"
                if a.get("device_class") == cls and re.search(patterns[0], eid) and not EXCLUDE.search(eid):
                    put(role, eid, f"integration:{platform}")

    if prices:
        _score, _len, eid, platform = max(prices)
        put("price", eid, f"integration:{platform}")

    # The car's battery level: picked by itself only when there is one car - with two, the user says which charges here.
    options = car_socs(entities, devices, states)
    cars = [c for c in options if c["score"] > -5]  # only ones named like a battery level are ever picked by themselves
    if options:
        found["_ev_soc_options"] = {"entity_id": " ".join(c["entity_id"] for c in options), "source": "options"}
    if cars:
        own = [c for c in cars if c["device"] == cars[0]["device"]]
        if len({c["device"] for c in cars if c["score"] >= 2}) <= 1:
            platform = (by_id.get(own[0]["entity_id"]) or {}).get("platform")
            put("ev_soc", own[0]["entity_id"], f"integration:{platform}")

    # 3. Names and kinds (inverters through MQTT, Modbus, templates …).
    for role, patterns in WORDS.items():
        if role in found:
            continue
        cls = "battery" if role == "battery_soc" else "power"
        best: tuple[int, str] | None = None
        for eid, s in states.items():
            if not eid.startswith("sensor.") or not alive(eid):
                continue
            a = s.get("attributes") or {}
            if a.get("device_class") != cls or EXCLUDE.search(eid):
                continue
            platform = (by_id.get(eid) or {}).get("platform")
            if role == "battery_soc" and (platform in NOT_HOME_BATTERY or a.get("unit_of_measurement") != "%"):
                continue
            text = f"{eid} {a.get('friendly_name', '')} {dev_names.get((by_id.get(eid) or {}).get('device_id'), '')}".lower()
            if not re.search(patterns[0], text):
                continue
            # Inverter words make it likelier; car/phone words make it unlikely.
            score = 1 + bool(re.search(r"growatt|huawei|solaredge|victron|inverter|sph|sungrow|goodwe|fronius|deye|foxess|solax", text))
            score -= 2 * bool(re.search(r"car|bil|tesla|phone|telefon|ipad|watch|laptop|ups", text))
            if role == "house_power" and re.search(r"uden_bil|without_ev|excl", text):
                score += 1
            # The plain names inverters use win over look-alikes ("grid to battery" is neither).
            if re.search({"pv_power": r"pv_power", "battery_power": r"battery_power", "grid_power": r"grid_power",
                          "house_power": r"load_power|house_power", "battery_soc": r"state_of_charge"}[role], eid):
                score += 2
            if role in ("battery_power", "grid_power") and re.search(r"net_til|_til_|_to_|from_grid|grid_to|to_battery", eid):
                score -= 3
            if best is None or score > best[0]:
                best = (score, eid)
        if best and best[0] > 0:
            put(role, best[1], "name")
    return found

energy_pilot/engine.py:
"""Energy Pilot's own engine - for homes that don't have a system of their own (and to compare with one that does).

1. House forecast: what the house uses, hour by hour, learned from its own history (recent weeks weigh most,
   weekdays and weekends apart).
2. Battery plan: dynamic programming over the hours prices are known - for each hour and battery level, the
   cheapest way on to the end, so the battery is filled when power is cheap or the sun gives too much, and used
   when power is dear. The energy left at the end is valued at what it will likely be worth later.
3. Car plan: the energy the car needs by the time it must be ready - sun first, then the cheapest hours.

Pure functions here (testable without Home Assistant); Engine at the bottom collects the numbers and runs them.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timedelta
import logging
import math
import re
from statistics import median
import time
from typing import Any
from zoneinfo import ZoneInfo

import aiohttp

_LOGGER = logging.getLogger(__name__)


def ready_time(value: Any, now: datetime | None = None) -> tuple[int, int] | None:
    """The car's "ready at" as (hour, minute), whatever the helper gives: "07:00", "07:00:00", "7:00 AM", a date and
    time ("2026-11-16T07:00:00+01:00", shown in local time) - None when unset ("00:00:00" is a helper left empty) or
    unreadable."""
    import re

    v = str(value or "").strip()
    if not v or v == "00:00:00" or v.lower() in ("unknown", "unavailable", "none"):
        return None
    if re.match(r"\d{4}-\d{2}-\d{2}[T ]", v):
        try:
            t = datetime.fromisoformat(v.replace("Z", "+00:00"))
        except ValueError:
            return None
        if t.tzinfo and now is not None and now.tzinfo:
            t = t.astimezone(now.tzinfo)
        hm = (t.hour, t.minute)
    else:
        m = re.match(r"^(\d{1,2})[:.](\d{2})(?::\d{2}(?:\.\d+)?)?\s*([ap]\.?m\.?)?$", v, re.I)
        if not m:
            return None
        h, mi, ap = int(m.group(1)), int(m.group(2)), (m.group(3) or "").lower()
        if ap.startswith("p") and h < 12:
            h += 12
        elif ap.startswith("a") and h == 12:
            h = 0
        if h > 23 or mi > 59:
            return None
        hm = (h, mi)
    return hm


# ---------- house forecast ----------


def over_cap(hours: list[Hour], p: Plan, cap: float) -> list[Hour]:
    """The paid slots past the day's feed-in cap: per day the best-paid exports are kept up to the cap."""
    by_day: dict[Any, list[tuple[Hour, float]]] = {}
    for h, st in zip(hours, p.steps):
        if h.sell > 0 and st.grid_kwh < 0:
            by_day.setdefault(h.start.date(), []).append((h, -st.grid_kwh))
    out = []
    for rows in by_day.values():
        sold = 0.0
        for h, kwh in sorted(rows, key=lambda r: (-r[0].sell, r[0].start)):
            if sold >= cap - 1e-9:
                out.append(h)
            sold += kwh
    return out


def computed_house(grid: dict, pv: dict, batt: dict, ev: dict, grid_sign: int = 1, batt_sign: int = 1) -> list[tuple[datetime, float]]:
    """kW per hour: grid (buying +) + sun - battery (charging +) - car; never below 0.
    An hour the battery has no history for is left out: counted as 0 its charging would look like house use
    (a battery sensor made lately, or one that was unavailable for a while)."""
    out = []
    for t in sorted(set(grid) & set(pv)):
        if batt and t not in batt:
            continue
        kw = pv[t] + grid[t] * grid_sign - batt.get(t, 0.0) * batt_sign - ev.get(t, 0.0)
        out.append((t, round(max(0.0, kw), 3)))
    return out


def solar_hours(fc: Any, ids: list[str]) -> dict[datetime, float]:
    """Home Assistant's energy/solar_forecast answer -> kWh per hour, the arrays (config entries) added up."""
    out: dict[datetime, float] = {}
    for i in ids:
        for t, wh in (((fc or {}).get(i) or {}).get("wh_hours") or {}).items():
            try:
                dt = datetime.fromisoformat(str(t)).replace(minute=0, second=0, microsecond=0)
                out[dt] = round(out.get(dt, 0.0) + float(wh) / 1000, 3)
            except (TypeError, ValueError):
                continue
    return out

def house_profile(rows: list[tuple[datetime, float]], now: datetime) -> dict[tuple[bool, int], float]:
    """{(weekend, hour): kWh} from hourly means (kW) - the last weeks weigh most."""
    sums: dict[tuple[bool, int], float] = {}
    weights: dict[tuple[bool, int], float] = {}
    for when, kw in rows:
        if kw is None or kw < 0 or kw > 50:
            continue
        age_days = max(0.0, (now - when).total_seconds() / 86400)
        w = 0.5 ** (age_days / 10)  # half the weight every 10 days
        key = (when.weekday() >= 5, when.hour)
        sums[key] = sums.get(key, 0.0) + kw * w
        weights[key] = weights.get(key, 0.0) + w
    return {k: sums[k] / weights[k] for k in sums if weights[k] > 0}


def house_forecast(profile: dict[tuple[bool, int], float], hours: list[datetime], fallback: float = 0.6) -> list[float]:
    out = []
    for h in hours:
        v = profile.get((h.weekday() >= 5, h.hour))
        if v is None:
            v = profile.get((not (h.weekday() >= 5), h.hour), fallback)
        out.append(round(v, 3))
    return out


# ---------- battery plan ----------

@dataclass
class Battery:
    capacity_kwh: float = 10.0
    max_charge_kw: float = 3.0
    max_discharge_kw: float = 3.0
    min_soc: float = 10.0  # %
    max_soc: float = 100.0
    grid_max_soc: float = 100.0  # charging from the grid stops here (the last % wear most); the sun may fill it up
    efficiency: float = 0.92  # round trip
    grid_charge: bool = True  # may charge from the grid when it pays
    import_limit_kw: float | None = None  # main fuse: never buy more than this in an hour
    quiet: frozenset = frozenset()  # hours (0-23) the battery must not charge from the grid (the sun still fills it)
    export: bool = False  # may sell from the battery when it pays (off unless the user turns it on)
    wear: float = 0.0  # what one kWh into or out of the battery wears it (money per kWh) - a move must beat it
    export_limit_kw: float | None = None  # what may be sent to the grid
    taper: tuple = ()  # (from level, share of the charge power it really takes) - learned; most slow down near full
    no_discharge: frozenset = frozenset()  # slots the battery must not discharge in (the car charges on cheap power)
    no_export: frozenset = frozenset()  # slots the battery must not sell in (the user keeps the cheap hours for charging)
    peak_kw: float | None = None  # power tariff: the month's peak so far - buying more costs peak_price per kW
    peak_price: float = 0.0
    targets: tuple = ()  # (hour, minute, soc %): the user wants at least this much in the battery at that time, every day
    at: tuple = ()  # (datetime, soc %): at least this much at that very time (a storm coming: storm.py)


@dataclass
class Hour:
    start: datetime
    price: float  # buy, per kWh
    sell: float  # sell, per kWh (0 when export isn't paid)
    house: float  # kWh
    sun: float  # kWh
    length: float = 1.0  # hours: 0.25 with quarter-hour prices (Europe since Oct 2025), 0.5 half-hour (UK Agile)


@dataclass
class Step:
    start: datetime
    action: str  # "charge_grid", "charge_sun", "discharge", "hold"
    soc_start: float
    soc_end: float
    grid_kwh: float  # + bought, - sold
    cost: float


@dataclass
class Plan:
    steps: list[Step] = field(default_factory=list)
    cost: float = 0.0
    cost_without: float = 0.0  # the same hours without a battery

    @property
    def saving(self) -> float:
        return round(self.cost_without - self.cost, 2)


def end_price(hours: list[Hour], b: Battery) -> float:
    """What a kWh still in the battery when the plan ends is worth (per kWh stored).

    It's what filling it again costs: the cheap hours, not the average of an expensive day - else the plan keeps
    power it could use in the morning, and even buys at 21:00 to have some left. Only when the plan sees at least
    18 hours (a night with its cheap hours) and the battery may charge from the grid; otherwise the median as before."""
    prices = sorted(h.price for h in hours)
    if not prices:
        return 0.0
    eff = math.sqrt(b.efficiency)
    span = (hours[-1].start - hours[0].start).total_seconds() / 3600 if len(hours) > 1 else 0
    if span < 18 or not b.grid_charge:
        return median(prices) * eff
    return prices[int(len(prices) * 0.1)] / eff


TARGET_PENALTY = 1000.0  # per % short of a target, times the dearest price: a target wins over any saving


def target_levels(hours: list[Hour], targets: tuple, at: tuple = ()) -> dict[int, float]:
    """Slot boundary (index i = before slot i, n = after the last) -> the least % the user wants there."""
    if not hours or not (targets or at):
        return {}
    start, end = hours[0].start, hours[-1].start + timedelta(hours=hours[-1].length)
    bounds = [h.start for h in hours] + [end]
    req: dict[int, float] = {}
    for t, soc in at:
        if start < t <= end:
            i = next(x for x in range(1, len(bounds)) if bounds[x] >= t)
            req[i] = max(req.get(i, 0.0), float(soc))
    for hh, mm, soc in targets:
        base = start.replace(hour=int(hh), minute=int(mm), second=0, microsecond=0)
        for k in range(-1, 4):
            t = base + timedelta(days=k)
            if start < t <= end:
                i = next(x for x in range(1, len(bounds)) if bounds[x] >= t)
                req[i] = max(req.get(i, 0.0), float(soc))
    return req


def cheap_slots(hours: list[Hour], share: float = 0.25) -> frozenset:
    """The cheap slots: a buy price in the lowest quarter of the span between the cheapest and the dearest.
    On a night tariff (Intelligent Go, Economy 7) that is the night; with flat prices nothing is cheap."""
    prices = [h.price for h in hours]
    if not prices or max(prices) - min(prices) < 1e-6:
        return frozenset()
    cut = min(prices) + share * (max(prices) - min(prices))
    return frozenset(h.start for h in hours if h.price <= cut + 1e-9)


def plan_battery(hours: list[Hour], soc_now: float, b: Battery, end_value: float | None = None, step_pct: float | None = None) -> Plan:
    """The cheapest way through the hours, starting at soc_now (%)."""
    if not hours:
        return Plan()
    if step_pct is None:
        # Small enough that one step is less than the house uses in a slot - else a quarter hour where the house
        # takes 0.2 kWh can't use the battery at all (one 2 % step of 13 kWh is 0.26 kWh).
        step_pct = 2.0 if min(h.length for h in hours) >= 1 else 1.0
    eff = math.sqrt(b.efficiency)
    levels = [round(b.min_soc + i * step_pct, 4) for i in range(int((b.max_soc - b.min_soc) / step_pct) + 1)]
    if levels[-1] < b.max_soc:
        levels.append(b.max_soc)
    kwh = lambda pct: pct / 100 * b.capacity_kwh  # noqa: E731
    if end_value is None:
        end_value = median(h.price for h in hours) * eff  # what a kWh left over will be worth later
    n, m = len(hours), len(levels)
    INF = float("inf")
    pct_step = step_pct / 100 * b.capacity_kwh  # kWh between two levels
    best = [[INF] * m for _ in range(n + 1)]
    choice: list[list[tuple[int, str, float, float]]] = [[(0, "hold", 0.0, 0.0)] * m for _ in range(n)]
    req = target_levels(hours, b.targets, b.at)
    pen = TARGET_PENALTY * max(1.0, max(h.price for h in hours))
    for j, lv in enumerate(levels):
        best[n][j] = -(kwh(lv) - kwh(b.min_soc)) * end_value + max(0.0, req.get(n, 0.0) - lv) * pen
    for i in range(n - 1, -1, -1):
        h = hours[i]
        # Only the levels the battery can reach in this slot (a quarter of an hour moves it a quarter as far).
        up = int(b.max_charge_kw * h.length * eff / pct_step) + 2
        down = int(b.max_discharge_kw * h.length / pct_step) + 2
        for j, lv in enumerate(levels):
            for k in range(max(0, j - down), min(m, j + up + 1)):
                nxt = levels[k]
                delta = kwh(nxt) - kwh(lv)  # + stored, - taken out (energy in the battery)
                if delta > 0:
                    share = next((sh for lvl, sh in sorted(b.taper, reverse=True) if lv >= lvl), 1.0)
                    if delta / eff > b.max_charge_kw * share * h.length + 1e-9:
                        continue  # more than it takes at this level (it slows down when nearly full)
                    into = delta / eff  # what has to go in
                    from_sun = min(into, max(0.0, h.sun - h.house))
                    grid = h.house - h.sun + into
                    if not b.grid_charge and grid > max(0.0, h.house - h.sun) + 1e-9:
                        continue
                    action = "charge_sun" if into - from_sun < 1e-6 else "charge_grid"
                    if h.start.hour in b.quiet and action == "charge_grid":
                        continue  # quiet hours: nothing bought for the battery - the sun's surplus still goes in
                    if action == "charge_grid" and nxt > b.grid_max_soc + 1e-9:
                        continue  # not above the grid limit with power bought - only the sun fills it beyond
                elif delta < 0:
                    if h.start in b.no_discharge:
                        continue  # the car charges on cheap power now: it takes it from the grid, not the battery
                    out = -delta * eff  # what comes out to the house
                    if -delta > b.max_discharge_kw * h.length + 1e-9:
                        continue
                    need = max(0.0, h.house - h.sun)
                    action = "discharge"
                    if out > need + 1e-9:
                        if b.export and h.sell > 0 and h.start not in b.no_export:
                            action = "export"  # sells what the house doesn't use
                        elif k != j - 1 or need <= 0:
                            continue  # no exporting from the battery
                        else:
                            out = need  # the smallest step is more than the house needs: it covers the house, no more
                    grid = h.house - h.sun - out
                    if action == "export" and b.export_limit_kw is not None and -grid > b.export_limit_kw * h.length + 1e-9:
                        continue  # more than may go out on the grid
                else:
                    grid = h.house - h.sun
                    action = "hold"
                if b.import_limit_kw is not None and grid > b.import_limit_kw * h.length + 1e-9 and delta > 0:
                    continue  # charging would trip the main fuse
                cost = grid * h.price if grid > 0 else grid * h.sell
                cost += abs(delta) * b.wear  # every kWh in or out wears the battery: a move must pay for that too
                if b.peak_kw is not None and b.peak_price and grid / h.length > b.peak_kw:
                    cost += (grid / h.length - b.peak_kw) * b.peak_price  # a new peak raises the month's power tariff
                # Equal prices (a night tariff): charge in the first slots, not the last - a battery that slows down
                # near full, or a slot the supplier moves, then still leaves it full. Far too small to change a choice
                # where prices differ (at most 0.0002 per kWh over two days of quarter hours).
                early = delta * i * 1e-6 if delta > 0 else 0.0
                total = cost + early + best[i + 1][k]
                if total < best[i][j] - 1e-12:
                    best[i][j] = total
                    choice[i][j] = (k, action, grid, cost)
        if i in req and i > 0:
            for j, lv in enumerate(levels):
                if lv < req[i]:
                    best[i][j] += (req[i] - lv) * pen  # short of what the user wants at this time
    j = min(range(m), key=lambda x: abs(levels[x] - soc_now))
    plan = Plan()
    for i, h in enumerate(hours):
        k, action, grid, cost = choice[i][j]
        plan.steps.append(Step(h.start, action, levels[j], levels[k], round(grid, 3), round(cost, 3)))
        plan.cost += cost
        base = h.house - h.sun
        plan.cost_without += base * h.price if base > 0 else base * h.sell
        if b.peak_kw is not None and b.peak_price and base / h.length > b.peak_kw:
            plan.cost_without += (base / h.length - b.peak_kw) * b.peak_price
        j = k
    plan.cost, plan.cost_without = round(plan.cost, 2), round(plan.cost_without, 2)
    return plan


def battery_targets(s: dict[str, Any]) -> tuple:
    """The user's "at least X % at HH:MM" from the settings, as (hour, minute, soc); bad rows are left out."""
    out = []
    for t in s.get("battery_targets") or []:
        try:
            hh, mm = (int(x) for x in str(t.get("time")).split(":")[:2])
            soc = float(t.get("soc"))
        except (TypeError, ValueError, AttributeError):
            continue
        if 0 <= hh < 24 and 0 <= mm < 60 and 0 < soc <= 100:
            out.append((hh, mm, soc))
    return tuple(out)


# ---------- car plan ----------

def plan_car(hours: list[Hour], need_kwh: float, charger_kw: float, ready: datetime | None, now: datetime,
             solar_only: bool = False, skip: set | None = None) -> list[datetime]:
    """The hours to charge in: sun surplus first, then the cheapest - all before 'ready' (or within 24 h).
    solar_only: only hours with a real surplus. skip: hours not to use (quiet hours, the battery's sun hours)."""
    if need_kwh <= 0 or charger_kw <= 0:
        return []
    until = ready or now + timedelta(hours=24)
    usable = [h for h in hours if now - timedelta(hours=h.length) < h.start < until and h.start not in (skip or set())
              and (not solar_only or h.sun - h.house >= charger_kw * h.length * 0.5)]
    # A surplus slot costs what the energy would have been sold for; others their price.
    ranked = sorted(usable, key=lambda h: h.sell if h.sun - h.house >= charger_kw * h.length * 0.7 else h.price)
    chosen, got = [], 0.0
    for h in ranked:
        if got >= need_kwh:
            break
        chosen.append(h.start)
        got += charger_kw * h.length
    return sorted(chosen)


# ---------- quarter-hour slots ----------

def resolution(prices: dict[datetime, float], now: datetime) -> int:
    """Minutes between prices from now on: 15 (Europe since October 2025), 30 (UK Agile) or 60."""
    coming = sorted(t for t in prices if t >= now - timedelta(hours=1))[:12]
    gaps = [round((b - a).total_seconds() / 60) for a, b in zip(coming, coming[1:])]
    gap = min((g for g in gaps if g > 0), default=60)
    return 15 if gap <= 15 else 30 if gap <= 30 else 60


def split_slots(hours: list[Hour], prices: dict[datetime, float], now: datetime,
                sells: dict[datetime, float] | None = None) -> list[Hour]:
    """Hours split into the market's price slots, each with its own price."""
    res = resolution(prices, now) if prices else 60
    k = 60 // res
    out = []
    for h in hours:
        for i in range(k):
            start = h.start + timedelta(minutes=i * res)
            if start + timedelta(minutes=res) <= now:
                continue  # already gone
            price = prices.get(start, h.price) if k > 1 else h.price
            sell = sells.get(start, h.sell) if sells and k > 1 else h.sell
            out.append(Hour(start, price, sell, h.house / k, h.sun / k, res / 60))
    # The slot now is planned whole, not scaled to what's left of it: late in a quarter the house would use less than one
    # battery step, and the plan would hold the battery for the rest of it while the house bought from the grid.
    return out


