    async def refresh_house_today(self) -> None:
        """What the house has used so far today (whole hours from the statistics, plus this hour's share)."""
        now = datetime.now(self.tz)
        day0 = now.replace(hour=0, minute=0, second=0, microsecond=0)
        rows = await self._house_rows(1)
        if not rows:
            return
        done = sum(kw for w, kw in rows if day0 <= w < now.replace(minute=0, second=0, microsecond=0))
        house_w = (self.ov.flow() or {}).get("house") or 0.0
        self.house_so_far = round(done + house_w / 1000 * now.minute / 60, 2)
        self.house_so_far_day = now.date()  # yesterday's total must never count after midnight

    def watch_sign(self, raw_w: float | None, soc: float | None) -> None:
        """Is positive battery power charging or discharging here? Seen from the level going up or down."""
        if raw_w is None or soc is None:
            return
        votes = self.learning.state.setdefault("battery_sign", {"same": 0, "opposite": 0})
        if abs(raw_w) < 200:
            self._sign_prev = None  # idle: start over
            return
        if self._sign_prev is None or (self._sign_prev[0] > 0) != (raw_w > 0):
            self._sign_prev = (raw_w, soc)  # a new run in one direction: remember where the level started
            return
        d = soc - self._sign_prev[1]
        if abs(d) >= 1:  # the level moved a whole percent during the run
            votes["same" if (d > 0) == (raw_w > 0) else "opposite"] += 1
            self._sign_prev = (raw_w, soc)

    def sign_found(self) -> int | None:
        v = self.learning.state.get("battery_sign") or {}
        same, opp = v.get("same", 0), v.get("opposite", 0)
        if opp >= 3 and opp > 3 * same:
            return -1
        if same >= 3 and same > 3 * opp:
            return 1
        return None

    def tou_plan(self) -> dict[str, Any] | None:
        """The own tariff plan, when it's the one in use."""
        from .sources import ZONES

        st = self.ov.settings
        country = (self.ha.config.get("country") or "").upper()
        use = st.get("price_source") == "tou" or (st.get("price_source") in (None, "auto") and country not in ZONES and st.get("tou"))
        return st.get("tou") if use and st.get("tou") else None

    def sell_prices(self) -> dict[datetime, float]:
        """A changing feed-in price (a chosen sensor, or the own tariff plan's feed-in times), with its forecast;
        empty when the price is fixed."""
        e = self.ov.role("sell_price")
        if not e and (plan := self.tou_plan()) and plan.get("sell_periods"):
            from .sources import tou_price

            st = self.ov.settings
            base = plan.get("sell_default")
            if base is None:
                base = float(st.get("sell_price") or 0) if st.get("sell") else 0.0
            sp = {"default": base, "periods": plan["sell_periods"]}
            day0 = datetime.now(self.tz).replace(hour=0, minute=0, second=0, microsecond=0)
            return {t: tou_price(sp, t) for t in (day0 + timedelta(minutes=15 * i) for i in range(2 * 96))}
        if not e or not (s := self.ha.states.get(e)):
            return {}
        from .pricefeed import companions, parse

        now = datetime.now(self.tz)
        out: dict[datetime, float] = {}
        for c in companions(self.ha.states, e):  # Octopus: today's and tomorrow's export rates
            out.update(parse((self.ha.states.get(c) or {}).get("attributes") or {}, self.tz,
                             now.replace(hour=0, minute=0, second=0, microsecond=0)))
        try:
            cur = float(s.get("state"))
            out.setdefault(now.replace(minute=now.minute // 15 * 15, second=0, microsecond=0), cur)
        except (TypeError, ValueError):
            pass
        if out and sorted(out.values())[len(out) // 2] < 0:
            out = {k: -v for k, v in out.items()}  # written as negative when it's paid to you (Amber): earnings are positive here
        return out

    def sell_at(self, prices: dict[datetime, float], when: datetime, fixed: float) -> float:
        if not prices:
            return fixed
        past = [k for k in prices if k <= when]
        return prices[max(past)] if past else prices[min(prices)]

    def ev_in_house(self) -> bool:
        """The user's choice wins; otherwise what was found."""
        chosen = self.ov.settings.get("ev_in_house")
        return bool(chosen) if chosen is not None else bool(self.ev_detected)

    def house_today(self) -> float | None:
        """Today in all: used so far plus the engine's own forecast for the rest of the day - the plan's numbers."""
        rows = (self.result or {}).get("house") or []
        if self.house_so_far is None and not rows:
            return None
        now = datetime.now(self.tz)
        if getattr(self, "house_so_far_day", None) != now.date():
            # Just after midnight, before the next refresh: only this hour's share so far.
            house_w = (self.ov.flow() or {}).get("house") or 0.0
            self.house_so_far, self.house_so_far_day = round(house_w / 1000 * now.minute / 60, 2), now.date()
        rest = sum(r["kwh"] for r in rows if datetime.fromisoformat(r["t"]).date() == now.date())
        rest -= (rows[0]["kwh"] * now.minute / 60) if rows else 0.0  # this hour's gone part is in "so far"
        return round((self.house_so_far or 0.0) + max(0.0, rest), 1)

    async def review(self) -> None:
        """After midnight: yesterday with the real numbers - the engine learns from it (see learning.py)."""
        now = datetime.now(self.tz)
        if now.hour == 0 and now.minute < 10:
            return  # let the statistics for the last hour be written first
        day = (now - timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
        if self.learning.state.get("reviewed") == day.strftime("%Y-%m-%d"):
            return
        def by_hour(rows: list[tuple[datetime, float]]) -> dict[str, float]:
            return {w.strftime("%Y-%m-%dT%H"): kw for w, kw in rows if w.date() == day.date()}
        house_rows = await self._house_rows(2)  # as the forecast was made (the car taken out)
        house = by_hour(house_rows)
        pv = by_hour(list((await self._hourly_sum(self.ov.role_all("pv_power"), 2)).items())) if self.ov.role_all("pv_power") else {}
        prices = {k: v["price"] for k, v in self.learning._expected(day.strftime("%Y-%m-%d")).items() if v.get("price") is not None}
        soc_start = None
        socs_end: dict[str, float] = {}
        if self.ov.role("battery_soc"):
            socs_all = await self._hourly_kw(self.ov.role("battery_soc"), 2)
            socs = by_hour(socs_all)
            first = socs.get(day.strftime("%Y-%m-%dT00"))
            # The level at the end of each hour = the mean of the next hour (the end of the day: the first of the next).
            scale = (lambda v: self.ov.scaled("battery_soc", v)) if hasattr(self.ov, "scaled") else (lambda v: v)
            socs_end = {(w - timedelta(hours=1)).strftime("%Y-%m-%dT%H"): scale(kw * 1000) for w, kw in socs_all
                        if (w - timedelta(hours=1)).date() == day.date()}
            soc_start = first * 1000 if first is not None else None  # _hourly_kw divides by 1000 for non-kW units
            soc_start = self.ov.scaled("battery_soc", soc_start) if hasattr(self.ov, "scaled") else soc_start
        if not house:
            return
        report = self.learning.review(day, house, pv, self.settings(), prices, soc_start,
                                      socs_end if self.ov.role("battery_soc") else None)
        if report is not None:
            # How well each way hit yesterday - the ML share moves towards what it earned.
            for kind in ("house", "sun"):
                days = (self.house_model.samples // 24) if kind == "house" else self.solar_model.days
                self.mixer.update(kind, report.get(f"{kind}_err_simple"), report.get(f"{kind}_err_ml"), days)
            es, em = self.price_model.score(now)
            if es is not None or em is not None:
                self.mixer.update("price", es, em, self.price_days)
            self.learning.save()
        if report:
            _LOGGER.info("Learned from %s: %s", report["day"], report)

    def _generator(self, now: datetime, f: dict[str, Any], hours: list[tuple[datetime, float, float]]) -> dict[str, Any]:
        """Off-grid: should the generator run now? (see generator.py)"""
        from .generator import GenSettings, decide

        st, b = self.ov.settings, self.settings()
        gs = GenSettings(capacity_kwh=b.capacity_kwh, efficiency=b.efficiency,
                         reserve_soc=float(st.get("reserve_soc") or 30), emergency_soc=float(st.get("emergency_soc") or 20),
                         stop_soc=float(st.get("gen_stop_soc") or 90), charge_kw=float(st.get("gen_charge_kw") or 5),
                         min_run_h=float(st.get("gen_min_run_h") or 2), quiet=frozenset(self.quiet_hours("gen")))
        e = self.ov.role("generator_running") or self.ov.role("generator_switch")
        running = str((self.ha.states.get(e) or {}).get("state")) == "on" if e else False
        if running and not getattr(self, "_gen_since", None):
            self._gen_since = now
        if not running:
            self._gen_since = None
        return decide(now, f.get("soc"), running, self._gen_since, hours, gs)

    def blend_info(self) -> dict[str, Any]:
        """Who decides now, and how well each one hits."""
        return {"house": self.mixer.info("house"), "sun": self.mixer.info("sun"), "price": self.mixer.info("price"),
                "battery": self.batt_learn.info(0.92), "car": self.habits.info(),
                "trained": {"house": self.house_model.samples // 24, "sun": self.solar_model.days, "price": self.price_days}}

    def sources_used(self) -> dict[str, Any]:
        from . import mlcheck

        return {"weather": bool(self.weather and self.weather.hours), "own_prices": bool(self.own_prices and not self.ov.role("price")),
                "own_solar": getattr(self.ov, "sun_source", None) == "own", "sun_source": getattr(self.ov, "sun_source", None), "house_model": self.house_model.model is not None,
                "house_error": self.house_model.error, "house_samples": self.house_model.samples, "ml": mlcheck.info()}

    def run(self) -> dict[str, Any] | None:
        """Plan from now over the hours with prices."""
        plan = self.ov.plan()
        tz = ZoneInfo(self.ha.config.get("time_zone") or "UTC")
        now = datetime.now(tz)
        from . import storm as _storm

        self.storm = _storm.find(self.weather, now, self.ov.settings, self.ha.states, getattr(getattr(self.ov, "controller", None), "_ent_reg", None)) if self.ov.settings.get("storm") else None
        start = now.replace(minute=0, second=0, microsecond=0)
        offgrid = bool(self.ov.settings.get("offgrid"))
        if offgrid:
            for h in plan["hours"]:
                h.setdefault("price", 0.0)  # no grid, no prices: the battery and the generator are all there is
        rows = [h for h in plan["hours"] if "price" in h and datetime.fromisoformat(h["t"]) >= start]
        if not rows:
            return None
        times = [datetime.fromisoformat(h["t"]) for h in rows]
        from .blend import Mixer

        w = self.weather if self.weather and self.weather.hours else None
        simple = house_forecast(self.profile, times) if self.profile else [h.get("house", 0.6) for h in rows]
        ml = self.house_model.predict(times, w) or [None] * len(times)
        hw = self.mixer.share("house")
        house = [Mixer.mix(s, m, hw) for s, m in zip(simple, ml)]
        st = self.ov.settings
        sell = float(st.get("sell_price") or 0) if st.get("sell") else 0.0  # what exported power earns
        sells = self.sell_prices()  # a changing feed-in price, when one is chosen
        # What it has learned: the sun forecast's usual error (cloudy/clear) and a margin on the house in the dear hours.
        L = self.learning
        clouds = [((self.weather.at(t) or {}).get("cloud") if self.weather else None) for t in times]
        dear = sorted(r["price"] for r in rows)[int(len(rows) * 0.75)] if len(rows) > 3 else None
        sun_simple = [L.sun(r.get("sun", 0.0), clouds[i]) for i, r in enumerate(rows)]
        sun_ml = self.solar_model.predict(times, w) if w else {}
        sw = self.mixer.share("sun")
        sun = [Mixer.mix(s, sun_ml.get(t), sw) for s, t in zip(sun_simple, times)]
        hours = [Hour(t, r["price"], self.sell_at(sells, t, sell), house[i] + (L.margin if dear is not None and r["price"] >= dear else 0.0), sun[i])
                 for i, (t, r) in enumerate(zip(times, rows))]
        L.expect([{"t": times[0].isoformat(), "house": house[0], "sun": hours[0].sun, "price": rows[0]["price"], "cloud": clouds[0],
                   "house_s": simple[0], "house_m": ml[0], "sun_s": sun_simple[0], "sun_m": sun_ml.get(times[0])}])
        # Prices per quarter (or half) hour where the market has them: plan in those slots, so the battery and
        # the car use the cheapest quarters inside an hour too. House and sun are spread evenly over the hour.
        hours = split_slots(hours, getattr(self.ov, "fine_prices", None) or {}, now, sells)
        slot_min = round(hours[0].length * 60) if hours else 60
        f = self.ov.flow()
        result: dict[str, Any] = {"at": now.isoformat(), "house": [{"t": t.isoformat(), "kwh": k} for t, k in zip(times, house)],
                                  "style": st.get("style") or "cheapest"}
        car_plan = self._car(hours, now, f, skip=set()) if (st.get("style") == "car_first") else None
        if car_plan:
            charger = float(st.get("charger_kw") or 7.4)
            for h in hours:
                if h.start in car_plan["set"]:
                    h.house += charger * h.length  # the car gets the sun first: what's left goes to the battery
        if offgrid:
            result["generator"] = self._generator(now, f, [(t, house[i], sun[i]) for i, t in enumerate(times)])
        if f["soc"] is not None and not offgrid:
            b = self.settings()
            # The car's cheap charging hours: the house battery doesn't empty itself into the car then.
            pre = car_plan or (self._car(hours, now, f, set()) if f.get("plug") else None)
            if pre and pre.get("set"):
                from dataclasses import replace

                b = replace(b, no_discharge=frozenset(pre["set"]))
            if st.get("battery_no_export_cheap"):
                from dataclasses import replace

                b = replace(b, no_export=cheap_slots(hours))  # no selling while power is cheap - only charging
            end_value = end_price(hours, b) * L.end_factor
            p = plan_battery(hours, f["soc"], b, end_value=end_value)
            # A daily cap on paid feed-in (15 kWh a day, say): what is sold past it earns nothing - the best-paid
            # slots keep the pay, the plan is made again without pay in the rest.
            cap = (self.tou_plan() or {}).get("sell_cap_kwh")
            for _ in range(3):
                over = over_cap(hours, p, float(cap)) if cap else []
                if not over:
                    break
                for h in over:
                    h.sell = 0.0
                p = plan_battery(hours, f["soc"], b, end_value=end_value)
            # The target: where the current action leads (not just the end of this quarter).
            run = 0
            while run + 1 < len(p.steps) and p.steps[run + 1].action == p.steps[0].action:
                run += 1
            result["battery"] = {
                "steps": [{"t": s.start.isoformat(), "action": s.action, "soc": s.soc_end, "grid": s.grid_kwh} for s in p.steps],
                "slot_min": slot_min,
                "now": ACTION_KIND[p.steps[0].action] if p.steps else "hold", "target": p.steps[run].soc_end if p.steps else None,
                "cost": p.cost, "cost_without": p.cost_without, "saving": p.saving, "capacity": b.capacity_kwh,
            }
            # The planned battery level at the end of this hour - set beside what really happened the next morning.
            end_h = times[0] + timedelta(hours=1)
            if inside := [st for st in p.steps if st.start < end_h]:
                L.expect([{"t": times[0].isoformat(), "soc_plan": inside[-1].soc_end}])
        try:
            from . import checks

            self.checks = checks.run(self, hours, self.settings(), p if f["soc"] is not None and not offgrid else None,
                                     end_value if f["soc"] is not None and not offgrid else 0.0)
        except Exception:  # noqa: BLE001
            _LOGGER.debug("Self-check failed", exc_info=True)
        if car_plan is None:
            skip = set()
            if st.get("style") == "battery_first" and result.get("battery"):
                skip = {datetime.fromisoformat(x["t"]) for x in result["battery"]["steps"] if x["action"] == "charge_sun"}
            car_plan = self._car(hours, now, f, skip)
        if car_plan:
            result["car"] = {"hours": car_plan["hours"], "need_kwh": car_plan["need"], "slot_min": slot_min}
        result["cars"] = self._more_cars(hours, now, f, car_plan, slot_min)
        try:
            result["things"] = self._things(hours, now, result, car_plan)
        except Exception:  # noqa: BLE001 - the small things must never stop the plan
            _LOGGER.debug("Things plan failed", exc_info=True)
        try:
            self._ghost_plans(hours, now, f, slot_min)
        except Exception:  # noqa: BLE001 - a comparison must never stop the plan
            _LOGGER.debug("Shadow car plan failed", exc_info=True)
        self.result = result
        self._compare()
        return result

    def _things(self, hours: list[Hour], now: datetime, result: dict[str, Any], car_plan: dict[str, Any] | None) -> list[dict[str, Any]]:
        """The small things, after the battery and the cars: only the sun the plan would sell, and the fuse with the cars."""
        st = self.ov.settings
        if not st.get("things"):
            return []
        steps = {datetime.fromisoformat(x["t"]): x for x in ((result.get("battery") or {}).get("steps") or [])}
        load: dict[datetime, float] = {}
        if car_plan:
            for t in car_plan.get("set") or []:
                load[t] = load.get(t, 0.0) + float(st.get("charger_kw") or 7.4)
        from . import chargers

        for c, p in zip(chargers.extras(st), result.get("cars") or []):
            for x in p.get("hours") or []:
                t = datetime.fromisoformat(x)
                load[t] = load.get(t, 0.0) + float(c.get("charger_kw") or 7.4)
        left = {}
        for h in hours:
            s = steps.get(h.start)
            spare = -float(s["grid"]) if s and s.get("grid") is not None else h.sun - h.house  # what the plan would sell
            left[h.start] = max(0.0, spare - load.get(h.start, 0.0) * h.length)
        limit = float(st["import_limit_kw"]) if st.get("import_limit_kw") else None
        self.things.aw = self.things.from_appliance_watch(self.ha.states)  # a machine Appliance Watch knows: its real programme
        return self.things.plan(st, hours, now, left, load, limit)

    def _car(self, hours: list[Hour], now: datetime, f: dict[str, Any], skip: set) -> dict[str, Any] | None:
        ev, st = self.ov.ev(), self.ov.settings
        if ev is None or not f.get("plug"):
            return None
        # What the user set wins; otherwise the car's learned habits (when it leaves, how much it takes).
        cap = float(ev.get("cap")) if self.ov.role("ev_cap") and ev.get("cap") else self.habits.need(float(ev.get("cap") or st.get("ev_need_kwh") or 20))
        need = cap - float(ev.get("session_kwh") or 0)
        if ev.get("soc") is not None:
            # The car says how full it is: what's missing up to the target (100 % before a long trip).
            from . import evsoc

            need = evsoc.need_kwh(ev["soc"], ev["target"], ev["car_kwh"])
        ready = None
        if (hm := ready_time(ev.get("ready"), now)) is not None:
            ready = now.replace(hour=hm[0], minute=hm[1], second=0, microsecond=0)
            if ready <= now:
                ready += timedelta(days=1)
        else:
            for ahead in (0, 1):
                day = now + timedelta(days=ahead)
                if (lv := self.habits.leave(day.weekday())) is not None:
                    cand = day.replace(hour=lv[0], minute=lv[1], second=0, microsecond=0)
                    if cand > now:
                        ready = cand
                        break
        if quiet := self.quiet_hours("car"):
            skip = skip | {h.start for h in hours if h.start.hour in quiet}
        kw = float(st.get("charger_kw") or 7.4)
        chosen = None
        if pt := self.power_tariff():
            # Power tariff: charge beside the peaks when that still gets the car full - else as usual.
            over = {h.start for h in hours if h.house / h.length + kw > pt["limit_kw"]}
            chosen = plan_car(hours, max(0.0, need), kw, ready, now, solar_only=st.get("ev_mode") == "solar", skip=skip | over)
            if sum(h.length for h in hours if h.start in set(chosen)) * kw < max(0.0, need) - 0.5:
                chosen = None
        if chosen is None:
            chosen = plan_car(hours, max(0.0, need), kw, ready, now, solar_only=st.get("ev_mode") == "solar", skip=skip)
        return {"hours": [t.isoformat() for t in chosen], "set": set(chosen), "need": round(max(0.0, need), 1)}

    def _ghost_plans(self, hours: list[Hour], now: datetime, f: dict[str, Any], slot_min: int) -> None:
        """A charger in shadow, just plugged in: the charge Energy Pilot would make, kept for comparison."""
        from . import chargers

        ctl = getattr(self.ov, "controller", None)
        st = self.ov.settings
        quiet = self.quiet_hours("car")
        prices = {h.start: h.price for h in hours}
        parts = [("car", None)] + [(f"car{i + 2}", c) for i, c in enumerate(chargers.extras(st))]
        for part, c in parts:
            if (ctl and ctl.mode(part) == "control") or not self.ghosts.wants_plan(part):
                continue
            if c is None:
                ev = self.ov.ev() or {}
                kw = float(st.get("charger_kw") or 7.4)
                need = self.ghosts.need(part, self.habits.need(float(st.get("ev_need_kwh") or 20)))
                if ev.get("soc") is not None and ev.get("car_kwh"):
                    from . import evsoc

                    need = evsoc.need_kwh(ev["soc"], ev["target"], ev["car_kwh"])
                ready = None
                if (hm := ready_time(ev.get("ready"), now)) is not None:
                    ready = now.replace(hour=hm[0], minute=hm[1], second=0, microsecond=0)
                    ready += timedelta(days=1) if ready <= now else timedelta(0)
                mode = st.get("ev_mode")
            else:
                kw = float(c.get("charger_kw") or 7.4)
                need = self.ghosts.need(part, float(c.get("need_kwh") or 20))
                ready, mode = chargers.ready_at(c, now), c.get("mode")
            skip = {h.start for h in hours if h.start.hour in quiet}
            chosen = plan_car(hours, max(0.0, need), kw, ready, now, solar_only=mode == "solar", skip=skip)
            self.ghosts.set_plan(part, chosen, max(0.0, need), prices, kw, slot_min / 60)

    def _more_cars(self, hours: list[Hour], now: datetime, f: dict[str, Any], car_plan: dict[str, Any] | None,
                   slot_min: int) -> list[dict[str, Any]] | None:
        """The other chargers: each car planned on its own - the cars before it and the main fuse taken into account."""
        from . import chargers

        more = chargers.extras(self.ov.settings)
        if not more:
            return None
        st = self.ov.settings
        limit = float(st["import_limit_kw"]) if st.get("import_limit_kw") else None
        load = {h.start: 0.0 for h in hours}  # what the cars already planned draw in each slot (kW)
        if car_plan:
            for t in car_plan["set"]:
                load[t] = load.get(t, 0.0) + float(st.get("charger_kw") or 7.4)
        quiet = self.quiet_hours("car")
        out = []
        for c, now_c in zip(more, f.get("cars") or [{}] * len(more)):
            kw = float(c.get("charger_kw") or 7.4)
            entry = {"name": c.get("name") or "", "plug": bool(now_c.get("plug")), "hours": [], "need_kwh": 0.0, "slot_min": slot_min}
            if now_c.get("plug"):
                need = max(0.0, float(c.get("need_kwh") or 20) - float(now_c.get("session_kwh") or 0))
                if c.get("now"):
                    ready = now + timedelta(hours=need / kw + 0.25)  # charge now: straight away, whatever the price
                else:
                    ready = chargers.ready_at(c, now)
                skip = {h.start for h in hours if h.start.hour in quiet}
                if limit is not None:  # never more than the main fuse: house + the other cars + this one
                    skip |= {h.start for h in hours if h.house / h.length + load.get(h.start, 0.0) + kw > limit + 1e-9}
                chosen = plan_car(hours, need, kw, ready, now, solar_only=c.get("mode") == "solar", skip=skip)
                for t in chosen:
                    load[t] = load.get(t, 0.0) + kw
                entry.update(hours=[t.isoformat() for t in chosen], need_kwh=round(need, 1))
            out.append(entry)
        return out

    def _compare(self) -> None:
        """How often the engine agrees with the system that controls today (when there is one)."""
        mine = ((self.result or {}).get("battery") or {}).get("now")
        theirs = self.ov.other_decision("en")
        if mine and theirs and self.ov.role("battery_plan"):
            self.agree["checks"] += 1
            self.agree["same"] += int(mine == theirs["kind"])

energy_pilot/evsoc.py:
"""The car's own battery level: charge to a target (80 % spares the battery), or 100 % for the next trip.

Two limits: from the grid up to the target, and with the sun's surplus up to its own (e.g. 80 % from the grid,
the last 20 % only when the sun gives it for free).

With the car's level known, what's missing is (target - level) x the car's battery size. The size is learned from the
charger: kWh put in against the % it rose (losses included). Without a level, the plan works on kWh as before.
"""

from __future__ import annotations

from statistics import median
from typing import Any

DEFAULT_TARGET = 80
DEFAULT_KWH = 60.0  # until it's learned or set - a middle-sized car
LOSS = 0.9  # what reaches the battery of what the charger gives


def target(settings: dict[str, Any]) -> int:
    """100 % when the next trip is long, else the everyday target."""
    if settings.get("ev_trip"):
        return 100
    try:
        return max(20, min(100, int(settings.get("ev_target") or DEFAULT_TARGET)))
    except (TypeError, ValueError):
        return DEFAULT_TARGET


def sun_target(settings: dict[str, Any]) -> int:
    """How far the sun's surplus may fill the car - never below the grid target (the same when not set)."""
    grid = target(settings)
    v = settings.get("ev_sun_target")
    try:
        return max(grid, min(100, int(v))) if v else grid
    except (TypeError, ValueError):
        return grid


def need_kwh(soc: float, goal: float, car_kwh: float) -> float:
    """What the charger must give to bring the car from soc to goal."""
    return max(0.0, goal - soc) / 100 * car_kwh / LOSS


def num(state: dict[str, Any] | None) -> float | None:
    try:
        v = float((state or {}).get("state"))
    except (TypeError, ValueError):
        return None
    return v if 0 <= v <= 100 else None


class CarSize:
    """The car's battery size, learned: during a charge, kWh from the charger against the rise in %."""

    def __init__(self, state: dict[str, Any]) -> None:
        self.state = state
        self._start: tuple[float, float] | None = None  # soc, session kWh when this charge began

    def see(self, plug: bool | None, soc: float | None, session_kwh: float | None) -> None:
        if not plug or soc is None or session_kwh is None:
            self._start = None
            return
        if self._start is None or session_kwh < self._start[1] - 0.5:  # a new session
            self._start = (soc, session_kwh)
            return
        s0, k0 = self._start
        if soc - s0 >= 15 and session_kwh - k0 >= 3:
            size = (session_kwh - k0) * LOSS / (soc - s0) * 100
            if 10 <= size <= 220:
                seen = (self.state.setdefault("ev_kwh_seen", []) + [round(size, 1)])[-6:]
                self.state["ev_kwh_seen"] = seen
            self._start = (soc, session_kwh)

    def kwh(self, settings: dict[str, Any]) -> tuple[float, str]:
        """(kWh, "set" | "learned" | "guess")."""
        try:
            if settings.get("ev_battery_kwh"):
                return float(settings["ev_battery_kwh"]), "set"
        except (TypeError, ValueError):
            pass
        seen = self.state.get("ev_kwh_seen") or []
        if len(seen) >= 2:
            return round(median(seen), 1), "learned"
        return DEFAULT_KWH, "guess"


def trip_done(settings: dict[str, Any], plug: bool | None, was_plugged: bool, soc: float | None) -> bool:
    """The trip button goes off by itself when the car leaves full (unplugged at 95 % or more)."""
    return bool(settings.get("ev_trip")) and was_plugged and not plug and (soc is None or soc >= 95)

energy_pilot/evsplit.py:
"""Is the car in the house's use? Many homes only have a sensor for everything, the car included.

The car is planned on its own, so it must not also be in the house's use: it would count twice, make the house
forecast high and uneven, and the battery would be saved for (and emptied into) the car.

Found from the hours the car charged: if the house's use rose by about as much as the charger took, compared
with the same hours of the day without charging, the car is in it - and is taken out, live and in the history.
"""

from __future__ import annotations

from datetime import datetime
from statistics import median


def detect(house: list[tuple[datetime, float]], ev: list[tuple[datetime, float]]) -> bool | None:
    """True: the car is in the house's use; False: it isn't; None: not enough charging seen to tell."""
    ev_by = {w: kw for w, kw in ev}
    charging = [(w, kw, ev_by[w]) for w, kw in house if ev_by.get(w, 0) >= 1.0]
    quiet: dict[int, list[float]] = {}
    for w, kw in house:
        if ev_by.get(w, 0) < 0.1:
            quiet.setdefault(w.hour, []).append(kw)
    ratios = []
    for w, kw, car in charging:
        base = quiet.get(w.hour)
        if base and len(base) >= 3:
            ratios.append((kw - median(base)) / car)
    if len(ratios) < 3:
        return None
    return median(ratios) > 0.6  # the house rose by most of what the car took


def subtract(house: list[tuple[datetime, float]], ev: list[tuple[datetime, float]]) -> list[tuple[datetime, float]]:
    ev_by = {w: kw for w, kw in ev}
    return [(w, max(0.0, kw - ev_by.get(w, 0.0))) for w, kw in house]

energy_pilot/generator.py:
"""Off-grid: when the generator should run - from the battery, the sun and the house's use ahead.

No grid and no prices: the battery is all there is, and the generator fills it. It runs:
- always when the battery falls to the emergency level (whatever the plan or the quiet hours)
- before the battery would fall below the reserve: the forecast (sun and house, hour by hour) is played forward,
  and the generator starts so late that it can still fill what's missing in time - not at all if the sun will do it
- in long runs, not many short ones: once started it runs at least its minimum time, then stops when the battery is
  full enough, or when the sun ahead will carry it to the next day
- not in the quiet hours (night) unless the battery would otherwise run dry before they end
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta
import math
from typing import Any


@dataclass
class GenSettings:
    capacity_kwh: float = 30.0
    efficiency: float = 0.92  # round trip
    reserve_soc: float = 30.0  # the plan never goes below this
    emergency_soc: float = 20.0  # start at once, always
    stop_soc: float = 90.0  # a run fills to this
    charge_kw: float = 5.0  # what the inverter's charger can take from the generator
    min_run_h: float = 2.0
    quiet: frozenset = frozenset()  # hours (0-23) the generator should rest


def simulate(soc: float, hours: list[tuple[datetime, float, float]], s: GenSettings) -> list[tuple[datetime, float]]:
    """The battery level hour by hour without the generator: (start, soc at the end of the hour).
    hours: (start, house kWh, sun kWh)."""
    out, kwh = [], soc / 100 * s.capacity_kwh
    eff = math.sqrt(s.efficiency)
    for t, house, sun in hours:
        net = sun - house
        kwh += net * eff if net > 0 else net / eff
        kwh = max(0.0, min(s.capacity_kwh, kwh))
        out.append((t, kwh / s.capacity_kwh * 100))
    return out


def decide(now: datetime, soc: float | None, running: bool, running_since: datetime | None,
           hours: list[tuple[datetime, float, float]], s: GenSettings) -> dict[str, Any]:
    """{"run": bool, "why": str, "low_at": iso | None, "start_at": iso | None, "need_kwh": float}."""
    if soc is None:
        return {"run": running, "why": "no_soc", "low_at": None, "start_at": None, "need_kwh": 0.0}
    ran_h = (now - running_since).total_seconds() / 3600 if running and running_since else 0.0
    path = simulate(soc, hours, s)
    low = next(((t, v) for t, v in path if v < s.reserve_soc), None)
    need = 0.0
    if low:
        # What it takes to stay at the reserve through the lowest point ahead (within the forecast).
        lowest = min(v for _t, v in path)
        need = max(0.0, (s.reserve_soc - lowest) / 100 * s.capacity_kwh)
    base = {"low_at": low[0].isoformat() if low else None, "need_kwh": round(need, 1)}

    if running:
        if ran_h < s.min_run_h:
            return {"run": True, "why": "min_run", "start_at": None, **base}
        if soc >= s.stop_soc:
            return {"run": False, "why": "full", "start_at": None, **base}
        if not low:
            return {"run": False, "why": "sun_carries", "start_at": None, **base}  # the sun ahead does the rest
        return {"run": True, "why": "filling", "start_at": None, **base}

    if soc <= s.emergency_soc:
        return {"run": True, "why": "emergency", "start_at": now.isoformat(), **base}
    if not low:
        return {"run": False, "why": "not_needed", "start_at": None, **base}
    # Fill from the reserve point back to the stop level, in a run of at least the minimum time.
    fill_kwh = need + (s.stop_soc - s.reserve_soc) / 100 * s.capacity_kwh
    run_h = max(s.min_run_h, fill_kwh / max(0.5, s.charge_kw))
    start = low[0] - timedelta(hours=math.ceil(run_h))
    # Not in the quiet hours: start before them if the battery would run low during them.
    while start.hour in s.quiet and start > now:
        start -= timedelta(hours=1)
    if now >= start:
        quiet_now = now.hour in s.quiet
        if quiet_now and low[0] > now + timedelta(hours=_hours_left_in_quiet(now, s.quiet)):
            return {"run": False, "why": "quiet", "start_at": None, **base}  # it can wait until the quiet hours end
        return {"run": True, "why": "before_low", "start_at": start.isoformat(), **base}
    return {"run": False, "why": "later", "start_at": start.isoformat(), **base}


def _hours_left_in_quiet(now: datetime, quiet: frozenset) -> int:
    h, n = now.hour, 0
    while (h + n) % 24 in quiet and n < 24:
        n += 1
    return n

energy_pilot/ghost.py:
"""A charger in shadow: what Energy Pilot would have done, beside what really happened - so the two can be compared.

When the car is plugged in, the plan Energy Pilot would follow is made once and kept for that charge (it doesn't
shrink as the car's own app or another system fills the car). Meanwhile the charge that really happens is measured:
when it drew power, how much, and what it cost at the prices of those slots. How much a car usually takes is learned
from the charges seen.
"""

from __future__ import annotations

from datetime import datetime
from statistics import median
from typing import Any


class Ghosts:
    def __init__(self, state: dict[str, Any]) -> None:
        self.s = state.setdefault("ghosts", {})

    def part(self, part: str) -> dict[str, Any]:
        return self.s.setdefault(part, {"plug": False, "plan": None, "own": None, "last": None, "needs": []})

    def see(self, part: str, now: datetime, plugged: bool | None, power_w: float | None, price: float | None, dt_s: float) -> None:
        """Every half minute: plugged in or out, and what the charger draws now."""
        if plugged is None:
            return
        g = self.part(part)
        if plugged and not g["plug"]:  # plugged in: a new charge - a new plan will be made
            g["plan"], g["own"] = None, {"start": now.isoformat(), "kwh": 0.0, "cost": 0.0, "first": None, "last": None}
        if not plugged and g["plug"]:  # unplugged: keep what happened, learn how much it took
            own = g.get("own") or {}
            if own.get("kwh", 0) >= 1:
                g["needs"] = (g.get("needs") or [])[-19:] + [round(own["kwh"], 1)]
                g["last"] = {"plan": g.get("plan"), "own": own}
            g["plan"], g["own"] = None, None
        g["plug"] = bool(plugged)
        own = g.get("own")
        if plugged and own is not None and power_w is not None and power_w > 200:
            kwh = power_w / 1000 * dt_s / 3600
            own["kwh"] = round(own["kwh"] + kwh, 5)
            if price is not None:
                own["cost"] = round(own["cost"] + kwh * price, 6)
            own["first"] = own["first"] or now.isoformat()
            own["last"] = now.isoformat()

    def need(self, part: str, setting: float) -> float:
        """How much this car usually takes per charge: learned once it has seen 3 charges, else the setting."""
        n = self.part(part).get("needs") or []
        return round(median(n), 1) if len(n) >= 3 else setting

    def wants_plan(self, part: str) -> bool:
        g = self.part(part)
        return bool(g["plug"]) and g.get("plan") is None

    def set_plan(self, part: str, hours: list[datetime], need: float, prices: dict[datetime, float], kw: float, slot_h: float) -> None:
        left, cost, kwh = need, 0.0, 0.0
        for t in sorted(hours):
            got = min(kw * slot_h, left)
            left -= got
            kwh += got
            cost += got * (prices.get(t) or 0.0)
        self.part(part)["plan"] = {"hours": [t.isoformat() for t in sorted(hours)], "need": round(need, 1),
                                   "kwh": round(kwh, 1), "cost": round(cost, 2), "kw": kw, "slot_h": slot_h}

    def view(self) -> dict[str, Any]:
        """Per charger in shadow: Energy Pilot's charge and the real one, with the average price of each."""
        out = {}
        for part, g in self.s.items():
            plan, own = g.get("plan"), g.get("own")
            if not (plan or own or g.get("last")):
                continue

            def avg(x: dict[str, Any] | None) -> float | None:
                return round(x["cost"] / x["kwh"], 3) if x and x.get("kwh") else None

            out[part] = {"plug": g["plug"], "plan": plan and {**plan, "avg": avg(plan)}, "own": own and {**own, "avg": avg(own)},
                         "last": g.get("last") and {"plan": g["last"]["plan"] and {**g["last"]["plan"], "avg": avg(g["last"]["plan"])},
                                                    "own": {**g["last"]["own"], "avg": avg(g["last"]["own"])}},
                         "learned_kwh": self.need(part, 0) or None}
        return out

energy_pilot/ha.py:
"""The connection to Home Assistant: every state kept up to date, services, history.

Inside Home Assistant (as an app) it uses the Supervisor's token; in Docker a long-lived token and the address.
"""

from __future__ import annotations

import asyncio
from datetime import datetime
import logging
import os
from typing import Any, Callable

import aiohttp

_LOGGER = logging.getLogger(__name__)


def endpoints() -> tuple[str, str, str]:
    """(websocket url, rest url, token)."""
    if token := os.environ.get("SUPERVISOR_TOKEN"):
        return "ws://supervisor/core/websocket", "http://supervisor/core/api", token
    url = os.environ.get("HA_URL", "http://homeassistant.local:8123").rstrip("/")
    return url.replace("http", "ws", 1) + "/api/websocket", url + "/api", os.environ["HA_TOKEN"]


class HomeAssistant:
    def __init__(self) -> None:
        self.ws_url, self.rest_url, self.token = endpoints()
        self.states: dict[str, dict[str, Any]] = {}
        self.session: aiohttp.ClientSession | None = None
        self._ws: aiohttp.ClientWebSocketResponse | None = None
        self._id = 0
        self._pending: dict[int, asyncio.Future] = {}
        self._event_handlers: dict[str, list[Callable[[dict[str, Any]], None]]] = {}
        self._subscribed: set[str] = set()
        self.on_state: list[Callable[[str, dict | None, dict | None], None]] = []
        self.connected = asyncio.Event()
        self.config: dict[str, Any] = {}

    @property
    def headers(self) -> dict[str, str]:
        return {"Authorization": f"Bearer {self.token}", "Content-Type": "application/json"}

    async def run(self) -> None:
        """Stay connected; reconnect after a Home Assistant restart."""
        self.session = aiohttp.ClientSession()
        while True:
            try:
                await self._connect()
            except Exception as err:  # noqa: BLE001
                _LOGGER.warning("Lost Home Assistant (%s) - trying again in 10 s", err)
            self.connected.clear()
            for fut in self._pending.values():
                if not fut.done():
                    fut.set_exception(ConnectionError("disconnected"))
            self._pending.clear()
            self._subscribed.clear()
            await asyncio.sleep(10)

    async def _connect(self) -> None:
        assert self.session is not None
        async with self.session.ws_connect(self.ws_url, heartbeat=30, max_msg_size=0) as ws:
            self._ws = ws
            await ws.receive_json()
            await ws.send_json({"type": "auth", "access_token": self.token})
            if (await ws.receive_json()).get("type") != "auth_ok":
                raise ConnectionError("Home Assistant refused the token")
            reader = asyncio.create_task(self._read(ws))
            try:
                self.config = await self.command({"type": "get_config"})
                states = await self.command({"type": "get_states"})
                self.states = {s["entity_id"]: s for s in states}
                await self._subscribe("state_changed")
                for event in list(self._event_handlers):
                    await self._subscribe(event)
                self.connected.set()
                _LOGGER.info("Connected to Home Assistant %s (%s entities)", self.config.get("version"), len(self.states))
                await reader
            finally:
                reader.cancel()

    async def _read(self, ws: aiohttp.ClientWebSocketResponse) -> None:
        async for msg in ws:
            if msg.type != aiohttp.WSMsgType.TEXT:
                continue
            data = msg.json()
            for item in data if isinstance(data, list) else [data]:
                if item.get("type") == "event":
                    self._event(item["event"])
                elif (fut := self._pending.pop(item.get("id"), None)) and not fut.done():
                    if item.get("success", True):
                        fut.set_result(item.get("result"))
                    else:
                        fut.set_exception(RuntimeError(str(item.get("error"))))

    def _event(self, event: dict[str, Any]) -> None:
        kind = event.get("event_type")
        if kind == "state_changed":
            d = event["data"]
            new, old = d.get("new_state"), d.get("old_state")
            if new is None:
                self.states.pop(d["entity_id"], None)
            else:
                self.states[d["entity_id"]] = new
            for cb in self.on_state:
                cb(d["entity_id"], old, new)
        for cb in self._event_handlers.get(kind, []):
            cb(event)

    async def command(self, msg: dict[str, Any], timeout: float = 60) -> Any:
        if self._ws is None or self._ws.closed:
            raise ConnectionError("not connected")
        self._id += 1
        msg = {**msg, "id": self._id}
        fut: asyncio.Future = asyncio.get_running_loop().create_future()
        self._pending[self._id] = fut
        await self._ws.send_json(msg)
        return await asyncio.wait_for(fut, timeout)

    async def _subscribe(self, event: str) -> None:
        if event in self._subscribed:
            return
        await self.command({"type": "subscribe_events", "event_type": event})
        self._subscribed.add(event)

    async def listen_event(self, event: str, cb: Callable[[dict[str, Any]], None]) -> None:
        self._event_handlers.setdefault(event, []).append(cb)
        if self.connected.is_set():
            await self._subscribe(event)

    async def call_service(self, domain: str, service: str, data: dict[str, Any], response: bool = False) -> Any:
        # device_id stays in the data: integration actions (Easee, Huawei, GivEnergy) take it as one text - as a target
        # Home Assistant turns it into a list, which they refuse ("value should be a string at 'device_id'").
        target = {k: data.pop(k) for k in ("entity_id", "area_id") if k in data}
        msg: dict[str, Any] = {"type": "call_service", "domain": domain, "service": service, "service_data": data}
        if target:
            msg["target"] = target
        if response:
            msg["return_response"] = True
        return await self.command(msg, timeout=170)

    async def set_state(self, entity_id: str, state: Any, attributes: dict[str, Any] | None) -> None:
        assert self.session is not None
        async with self.session.post(f"{self.rest_url}/states/{entity_id}", headers=self.headers,
                                     json={"state": state, "attributes": attributes or {}}) as resp:
            resp.raise_for_status()

    async def history(self, entity_id: str, start: datetime, end: datetime | None) -> list[list[dict[str, Any]]]:
        assert self.session is not None
        params = {"filter_entity_id": entity_id}
        if end is not None:
            params["end_time"] = end.isoformat()
        async with self.session.get(f"{self.rest_url}/history/period/{start.isoformat()}", headers=self.headers,
                                    params=params, timeout=aiohttp.ClientTimeout(total=120)) as resp:
            resp.raise_for_status()
            return await resp.json()

energy_pilot/hassapi.py:
"""The part of AppDaemon's API the energy apps use - so they run here unchanged.

Every app runs in its own thread, like AppDaemon (callbacks of one app never run at the same time). Reading a state
is instant (all states are kept here); calling a service, setting a state and reading history go through the
runner, which in shadow mode only writes down what the app *would* have done.
"""

from __future__ import annotations

from datetime import datetime, time as dtime, timedelta
import logging
from typing import TYPE_CHECKING, Any, Callable

if TYPE_CHECKING:
    from .runner import Runner


class Hass:
    def __init__(self, runner: Runner, name: str, args: dict[str, Any] | None = None) -> None:
        self._runner = runner
        self.name = name
        self.args = args or {}
        self.logger = logging.getLogger(f"app.{name}")

    # ---------- logging ----------

    def log(self, msg: Any, *args: Any, level: str = "INFO", **kwargs: Any) -> None:
        text = str(msg) % args if args else str(msg)
        self._runner.app_log(self.name, level.upper(), text)

    def error(self, msg: Any, *args: Any, level: str = "ERROR", **kwargs: Any) -> None:
        self.log(msg, *args, level=level)

    # ---------- time ----------

    def datetime(self, aware: bool = False) -> datetime:
        now = datetime.now(self._runner.tz)
        return now if aware else now.replace(tzinfo=None)

    def get_now(self) -> datetime:
        return datetime.now(self._runner.tz)

    def get_now_ts(self) -> float:
        return datetime.now(self._runner.tz).timestamp()

    def time(self) -> dtime:
        return self.datetime().time()

    def date(self):
        return self.datetime().date()

    # ---------- states ----------

    def get_state(self, entity_id: str | None = None, attribute: str | None = None, default: Any = None,
                  copy: bool = True, **kwargs: Any) -> Any:
        if entity_id is None:
            return {e: dict(s) for e, s in self._runner.all_states(self.name).items()}
        if "." not in entity_id:
            return {e: dict(s) for e, s in self._runner.all_states(self.name).items() if e.startswith(entity_id + ".")}
        s = self._runner.state_of(self.name, entity_id)
        if s is None:
            return default
        if attribute is None:
            return s.get("state", default)
        if attribute == "all":
            return {**s, "attributes": dict(s.get("attributes") or {})}
        return (s.get("attributes") or {}).get(attribute, default)

    def entity_exists(self, entity_id: str, **kwargs: Any) -> bool:
        return self._runner.state_of(self.name, entity_id) is not None

    def set_state(self, entity_id: str, state: Any = None, attributes: dict[str, Any] | None = None,
                  replace: bool = False, **kwargs: Any) -> dict[str, Any]:
        return self._runner.set_state(self.name, entity_id, state, attributes, replace)

    def call_service(self, service: str, **kwargs: Any) -> Any:
        kwargs.pop("namespace", None)
        return_result = kwargs.pop("return_result", False)
        kwargs.pop("callback", None)
        result = self._runner.call_service(self.name, service, kwargs)
        return result if return_result else result

    def turn_on(self, entity_id: str, **kwargs: Any) -> Any:
        return self.call_service("homeassistant/turn_on", entity_id=entity_id, **kwargs)

    def turn_off(self, entity_id: str, **kwargs: Any) -> Any:
        return self.call_service("homeassistant/turn_off", entity_id=entity_id, **kwargs)

    def fire_event(self, event: str, **kwargs: Any) -> None:
        self._runner.fire_event(self.name, event, kwargs)

    def get_history(self, entity_id: str | None = None, days: int | None = None, start_time: datetime | None = None,
                    end_time: datetime | None = None, **kwargs: Any) -> list[list[dict[str, Any]]]:
        entity_id = entity_id or kwargs.get("entity")
        if start_time is None:
            start_time = self.datetime(aware=True) - timedelta(days=days or 1)
        return self._runner.history(entity_id, start_time, end_time)

    # ---------- listening ----------

    def listen_state(self, callback: Callable, entity_id: str | None = None, attribute: str | None = None,
                     new: Any = None, old: Any = None, duration: float | None = None, **kwargs: Any) -> str:
        return self._runner.listen_state(self.name, callback, entity_id, attribute, new, old, duration, kwargs)

    def listen_event(self, callback: Callable, event: str | None = None, **kwargs: Any) -> str:
        return self._runner.listen_event(self.name, callback, event, kwargs)

    def cancel_listen_state(self, handle: str, **kwargs: Any) -> bool:
        return self._runner.cancel(handle)

    def cancel_listen_event(self, handle: str, **kwargs: Any) -> bool:
        return self._runner.cancel(handle)

    # ---------- timers ----------

    def run_in(self, callback: Callable, delay: float, **kwargs: Any) -> str:
        return self._runner.schedule(self.name, callback, delay=float(delay), kwargs=kwargs)

    def run_once(self, callback: Callable, start: Any, **kwargs: Any) -> str:
        return self._runner.schedule(self.name, callback, at=self._runner.next_time(start), kwargs=kwargs)

    def run_at(self, callback: Callable, start: Any, **kwargs: Any) -> str:
        return self.run_once(callback, start, **kwargs)

    def run_every(self, callback: Callable, start: Any, interval: float, **kwargs: Any) -> str:
        return self._runner.schedule(self.name, callback, at=self._runner.next_time(start), every=float(interval),
                                     kwargs=kwargs)

    def run_minutely(self, callback: Callable, start: Any = None, **kwargs: Any) -> str:
        return self.run_every(callback, start or "now", 60, **kwargs)

    def run_hourly(self, callback: Callable, start: Any = None, **kwargs: Any) -> str:
        return self.run_every(callback, start or "now", 3600, **kwargs)

    def run_daily(self, callback: Callable, start: Any, **kwargs: Any) -> str:
        return self._runner.schedule(self.name, callback, at=self._runner.next_time(start, daily=True),
                                     every=86400.0, daily=start, kwargs=kwargs)

    def cancel_timer(self, handle: str, **kwargs: Any) -> bool:
        return self._runner.cancel(handle)

    def timer_running(self, handle: str) -> bool:
        return self._runner.running(handle)

    # ---------- what AppDaemon apps sometimes override ----------

    def initialize(self) -> None:  # noqa: D401 - the app's own
        """Set up by the app."""

    def terminate(self) -> None:
        """Clean up by the app."""

energy_pilot/househist.py:
"""The house's own use per hour, kept by Energy Pilot itself - for homes where Home Assistant keeps no statistics of
the house sensor (no state_class), so there is no history to learn from. Kept for 60 days, saved with the learning."""

from __future__ import annotations

from datetime import datetime, timedelta
from typing import Any

KEEP_DAYS = 60


class HouseHistory:
    def __init__(self, state: dict[str, Any]) -> None:
        self.s = state.setdefault("house_hist", {})
        self._hour: str | None = None
        self._sum, self._n = 0.0, 0

    def see(self, now: datetime, house_w: float | None) -> None:
        """Every half minute: the house's use now (W, without the car). A whole hour's mean is kept as kW."""
        if house_w is None or house_w < 0:
            return
        hour = now.replace(minute=0, second=0, microsecond=0).isoformat()
        if hour != self._hour:
            if self._hour is not None and self._n >= 60:  # most of the hour seen (120 rounds in an hour)
                self.s[self._hour] = round(self._sum / self._n / 1000, 3)
                cut = (now - timedelta(days=KEEP_DAYS)).isoformat()
                for k in [k for k in self.s if k < cut]:
                    del self.s[k]
            self._hour, self._sum, self._n = hour, 0.0, 0
        self._sum += house_w
        self._n += 1

    def rows(self) -> list[tuple[datetime, float]]:
        return [(datetime.fromisoformat(k), v) for k, v in sorted(self.s.items())]

    def days(self) -> int:
        return len(self.s) // 24

energy_pilot/learning.py:
"""Learning from its own results, every night - no dice, just looking back at yesterday with the real numbers.

Every hour the engine writes down what it expected (house use, sun, price). After midnight it compares yesterday's
expectations with what really happened and adjusts:

- sun: how much the solar forecast is usually off, apart for cloudy and clear hours
- house margin: how much the house's use varies from the forecast - added in the expensive hours, so the battery
  doesn't run dry just before they end
- end value: what a kWh left in the battery at the end of the plan is worth - yesterday is planned again with
  the real numbers for a few values, and the one that would have cost least is moved towards
- a report: what the battery saved yesterday and how good the forecasts were

All of it is kept in Energy Pilot's own folder.
"""

from __future__ import annotations

from datetime import datetime, timedelta
import json
import logging
from pathlib import Path
from statistics import mean
from typing import Any

from .engine import Battery, Hour, plan_battery

_LOGGER = logging.getLogger(__name__)
FACTORS = (0.6, 0.75, 0.9, 1.0, 1.1, 1.25)


class Learning:
    def __init__(self, data_dir: Path) -> None:
        self.file = data_dir / "energy_pilot_learning.json"
        self.log_file = data_dir / "energy_pilot_expected.jsonl"
        self.state: dict[str, Any] = {"solar_bias": {"cloudy": 1.0, "clear": 1.0}, "house_margin": 0.0, "end_factor": 1.0,
                                      "reports": [], "reviewed": None}
        try:
            self.state.update(json.loads(self.file.read_text()))
        except (OSError, ValueError):
            pass

    def save(self) -> None:
        self.file.write_text(json.dumps(self.state, indent=1, default=str))

    # ---------- what the engine uses ----------

    def sun(self, kwh: float, cloud: float | None) -> float:
        bias = self.state["solar_bias"]["cloudy" if (cloud or 0) >= 60 else "clear"]
        return kwh * bias

    @property
    def end_factor(self) -> float:
        return float(self.state.get("end_factor", 1.0))

    @property
    def margin(self) -> float:
        return float(self.state.get("house_margin", 0.0))

    # ---------- writing down what was expected ----------

    def expect(self, rows: list[dict[str, Any]]) -> None:
        """rows: [{t, house, sun, price, cloud}] for the coming hours - the first is kept (this hour's best guess)."""
        if not rows:
            return
        try:
            with self.log_file.open("a") as f:
                f.write(json.dumps(rows[0]) + "\n")
        except OSError:
            pass

    def _expected(self, day: str) -> dict[str, dict[str, Any]]:
        out: dict[str, dict[str, Any]] = {}
        try:
            for line in self.log_file.read_text().splitlines():
                row = json.loads(line)
                if str(row.get("t", "")).startswith(day):
                    hour = out.setdefault(row["t"][:13], {})
                    for k, v in row.items():
                        hour.setdefault(k, v)  # the first guess for each hour (house and sun, the battery apart)
        except (OSError, ValueError):
            pass
        return out

    # ---------- the nightly review ----------

    def review(self, day: datetime, house: dict[str, float], pv: dict[str, float], battery: Battery,
               prices: dict[str, float], soc_start: float | None, soc: dict[str, float] | None = None) -> dict[str, Any] | None:
        """Yesterday with the real numbers. house/pv/prices: {"YYYY-MM-DDTHH": kWh or price}."""
        key = day.strftime("%Y-%m-%d")
        if self.state.get("reviewed") == key:
            return None
        exp = self._expected(key)
        report: dict[str, Any] = {"day": key}
        # How good were the forecasts?
        h_err = [abs(exp[h]["house"] - house[h]) for h in exp if h in house and exp[h].get("house") is not None]
        if h_err:
            report["house_error"] = round(mean(h_err), 3)
            margin = sorted(h_err)[int(len(h_err) * 0.7)] if len(h_err) > 3 else mean(h_err)
            self.state["house_margin"] = round(0.8 * self.margin + 0.2 * margin, 3)
        for kind in ("cloudy", "clear"):
            pairs = [(exp[h]["sun"], pv[h]) for h in exp if h in pv and (exp[h].get("sun") or 0) > 0.2
                     and ((exp[h].get("cloud") or 0) >= 60) == (kind == "cloudy")]
            if len(pairs) >= 3:
                ratio = sum(a for _, a in pairs) / max(0.01, sum(f for f, _ in pairs))
                ratio = min(2.0, max(0.3, ratio))
                b = self.state["solar_bias"]
                b[kind] = round(0.8 * b[kind] * 1 + 0.2 * b[kind] * ratio, 3)  # moves a fifth of the way
                report[f"sun_{kind}"] = round(ratio, 2)
        # What would each end value have cost, planning yesterday with the real numbers?
        hours = [Hour(datetime.fromisoformat(h + ":00:00").replace(tzinfo=day.tzinfo), prices[h], 0.0, house[h], pv.get(h, 0.0))
                 for h in sorted(house) if h in prices]
        if len(hours) >= 18 and soc_start is not None:
            from .engine import end_price

            base = end_price(hours, battery)
            costs = {f: plan_battery(hours, soc_start, battery, end_value=base * f).cost for f in FACTORS}
            best = min(costs, key=costs.get)
            self.state["end_factor"] = round(0.75 * self.end_factor + 0.25 * best, 3)
            p = plan_battery(hours, soc_start, battery, end_value=base * self.end_factor)
            report.update(saving=p.saving, cost=p.cost, cost_without=p.cost_without, best_factor=best)
        # Both ways of forecasting, each against what really happened (for the blend).
        for kind, real in (("house", house), ("sun", pv)):
            for way, col in (("simple", f"{kind}_s"), ("ml", f"{kind}_m")):
                pairs = [(exp[h][col], real[h]) for h in exp if h in real and exp[h].get(col) is not None
                         and (kind == "house" or (exp[h].get("sun_s") or 0) > 0.05 or real[h] > 0.05)]
                if len(pairs) >= 6:
                    report[f"{kind}_err_{way}"] = round(mean(abs(a - b) for a, b in pairs), 3)
        # Plan against what happened, hour by hour - the "Plan vs. real" chart. Only the newest day keeps them.
        rows = []
        for h in sorted(set(exp) | set(house)):
            e = exp.get(h) or {}
            rows.append({"h": int(h[11:13]), "house": [_r(e.get("house")), _r(house.get(h))], "sun": [_r(e.get("sun")), _r(pv.get(h)) if pv else None],
                         "soc": [_r(e.get("soc_plan"), 0), _r((soc or {}).get(h), 0)]})
        report["hours"] = rows
        report["accuracy"] = accuracy(rows)
        old = [{k: v for k, v in r.items() if k != "hours"} for r in (self.state.get("reports") or [])[-29:]]
        self.state["reports"] = old + [report]
        self.state["reviewed"] = key
        self.save()
        self._trim(day)
        return report

    def _trim(self, day: datetime) -> None:
        """Keep two weeks of expectations."""
        cut = (day - timedelta(days=14)).strftime("%Y-%m-%d")
        try:
            lines = [ln for ln in self.log_file.read_text().splitlines() if json.loads(ln).get("t", "") >= cut]
            self.log_file.write_text("\n".join(lines) + ("\n" if lines else ""))
        except (OSError, ValueError):
            pass

    def summary(self) -> dict[str, Any]:
        reports = self.state.get("reports") or []
        week = reports[-7:]
        return {
            "yesterday": reports[-1] if reports else None,
            "week_saving": round(sum(r.get("saving", 0) for r in week), 2) if any("saving" in r for r in week) else None,
            "solar_bias": self.state["solar_bias"], "house_margin": self.margin, "end_factor": self.end_factor,
            "days": len(reports),
        }


def _r(v: Any, nd: int = 2) -> float | None:
    return round(float(v), nd) if isinstance(v, (int, float)) else None


def accuracy(rows: list[dict[str, Any]]) -> dict[str, float | None]:
    """How close the plan came, 0-100 %: 100 minus the hourly misses against the real total (house, sun);
    the battery: 100 minus the mean miss in percentage points."""
    out: dict[str, float | None] = {}
    for kind in ("house", "sun"):
        pairs = [r[kind] for r in rows if r[kind][0] is not None and r[kind][1] is not None]
        real = sum(b for _, b in pairs)
        out[kind] = round(max(0.0, 100 - 100 * sum(abs(a - b) for a, b in pairs) / real)) if pairs and real > 0.5 else None
    pairs = [r["soc"] for r in rows if r["soc"][0] is not None and r["soc"][1] is not None]
    out["soc"] = round(max(0.0, 100 - mean(abs(a - b) for a, b in pairs))) if len(pairs) >= 6 else None
    return out

energy_pilot/mlcheck.py:
"""Can this machine run the learning models? Checked once.

numpy 2 needs a CPU with x86-64-v2 (SSE4.2, POPCNT). An old CPU - or a Proxmox VM with the CPU type "kvm64" - stops
it with a RuntimeError when it loads. Then the simple forecasts are used, without an error every hour.
"""

from __future__ import annotations

import logging

_LOGGER = logging.getLogger(__name__)
_state: dict[str, str | bool | None] = {}


def ok() -> bool:
    if "ok" not in _state:
        try:
            from sklearn.ensemble import GradientBoostingRegressor, HistGradientBoostingRegressor  # noqa: F401

            _state.update(ok=True, why=None, detail=None)
        except Exception as err:  # noqa: BLE001 - ImportError, or RuntimeError from numpy on an old CPU
            text = str(err)
            cpu = any(k in text.lower() for k in ("baseline", "x86_v", "cpu", "illegal instruction", "sse", "avx"))
            _state.update(ok=False, why="cpu" if cpu else "missing" if isinstance(err, ImportError) else type(err).__name__, detail=text[:300])
            _LOGGER.info("Learning models off (%s): %s", _state["why"], text[:300])
    return bool(_state["ok"])


def why() -> str | None:
    ok()
    return _state.get("why")  # type: ignore[return-value]


def info() -> dict[str, object]:
    ok()
    return {"ok": _state.get("ok"), "why": _state.get("why"), "detail": _state.get("detail")}

energy_pilot/powertariff.py:
"""Power tariffs (Belgium's capacity tariff, Norway's and Sweden's "effektavgift"): part of the bill is the month's peak.

The peak is measured over a window (15 minutes in Belgium, an hour elsewhere) and is either the month's highest, or the
average of the highest on three different days (Norway, Sweden). Energy Pilot keeps the month's peaks itself; the plan
then pays a price for every kW above the peak so far, so the battery shaves the peaks and the car charges beside them.
"""

from __future__ import annotations

from datetime import datetime
from typing import Any

# By country: window in minutes, peaks counted (on different days). The price per kW is the user's own.
PRESETS = {"BE": (15, 1), "NO": (60, 3), "SE": (60, 3)}
FLOOR_KW = 2.0  # early in the month the peak is low - never plan as if 1 kW were the limit


def kind(settings: dict[str, Any], country: str | None) -> tuple[int, int]:
    k = settings.get("power_tariff_kind")
    if k == "15min":
        return 15, 1
    if k == "top3":
        return 60, 3
    if k == "hour":
        return 60, 1
    return PRESETS.get(str(country or "").upper(), (60, 1))


class MonthPeak:
    """The month's peaks (kW over the window), kept in the learning state so a restart keeps them."""

    def __init__(self, state: dict[str, Any]) -> None:
        self.state = state
        self._slot: tuple[datetime, float, int] | None = None  # window start, sum of kW, samples

    def see(self, now: datetime, grid_w: float | None, window_min: int) -> None:
        if grid_w is None:
            return
        start = now.replace(minute=now.minute // window_min * window_min if window_min < 60 else 0, second=0, microsecond=0)
        kw = max(0.0, grid_w) / 1000
        if self._slot and self._slot[0] != start:
            s0, total, n = self._slot
            if n >= 3:
                self._record(s0, total / n)
            self._slot = None
        if self._slot is None:
            self._slot = (start, 0.0, 0)
        s0, total, n = self._slot
        self._slot = (s0, total + kw, n + 1)

    def _record(self, start: datetime, kw: float) -> None:
        m = self.state.setdefault("month_peak", {})
        month = start.strftime("%Y-%m")
        if m.get("month") != month:
            if m.get("month"):
                m["last_level"] = self.level()  # last month's, a guide for the first days of the new one
            m["month"], m["peaks"] = month, {}
        day = start.strftime("%d")
        peaks = m.setdefault("peaks", {})
        if kw > peaks.get(day, 0.0):
            peaks[day] = round(kw, 2)

    def level(self, count: int | None = None) -> float | None:
        """What the bill is based on so far: the highest, or the average of the highest days."""
        m = self.state.get("month_peak") or {}
        vals = sorted((m.get("peaks") or {}).values(), reverse=True)
        if not vals:
            return None
        n = count or m.get("count") or 1
        top = vals[:n]
        return round(sum(top) / len(top), 2)

    def limit(self, count: int) -> float:
        """The peak the plan tries to stay under: this month's so far, at least a share of last month's and 2 kW."""
        m = self.state.setdefault("month_peak", {})
        m["count"] = count
        now = self.level(count) or 0.0
        last = float(m.get("last_level") or 0.0) * 0.8
        return round(max(now, last, FLOOR_KW), 2)

energy_pilot/pricefeed.py:
"""Reading coming prices from any price integration, today and tomorrow - and filling what's missing.

Price integrations keep the coming prices in different places and shapes:
- Strømligning: "prices" [{start, end, price}] on the current-price sensor, tomorrow on a separate "…tomorrow…" entity
- Nord Pool: "raw_today" / "raw_tomorrow" [{start, end, value}]
- Energi Data Service: "raw_today" / "raw_tomorrow" / "forecast" [{hour, price}]
- Tibber / Octopus and others: "today" / "tomorrow", lists of numbers or of {startsAt, total}
All of it is read, from the price sensor and from its "tomorrow" companions of the same integration. Hours still
missing (tomorrow's prices not in the integration) are filled from Energy Pilot's own spot prices, moved to the level of
the user's own prices, so the plan always reaches as far as anything is known.
"""

from __future__ import annotations

import re
from datetime import datetime, timedelta
from typing import Any
from zoneinfo import ZoneInfo

LIST_KEYS = ("prices", "raw_today", "raw_tomorrow", "today", "tomorrow", "forecast", "forecasts", "rates", "data", "prices_today",
             "prices_tomorrow")  # "forecasts": Amber, "rates": Octopus Energy
TIME_KEYS = ("start", "startsAt", "starts_at", "hour", "time", "from", "start_time", "valid_from", "datetime", "timestamp")
VALUE_KEYS = ("price", "value", "total", "price_inc_vat", "value_inc_vat", "price_ct_per_kwh", "per_kwh", "electricity_price")


def _when(value: Any, tz: ZoneInfo) -> datetime | None:
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=tz)
    if isinstance(value, str):
        try:
            dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError:
            return None
        return dt if dt.tzinfo else dt.replace(tzinfo=tz)
    return None


def parse(attrs: dict[str, Any], tz: ZoneInfo, day0: datetime) -> dict[datetime, float]:
    """{start: price per kWh} from one entity's attributes, whatever the shape."""
    per_mwh = str(attrs.get("unit_of_measurement") or "").lower().endswith("/mwh")
    out: dict[datetime, float] = {}
    for key in LIST_KEYS:
        items = attrs.get(key)
        if not isinstance(items, list) or not items:
            continue
        # A bare list of numbers (Nord Pool "today"/"tomorrow", one per hour or quarter).
        if all(isinstance(x, (int, float)) for x in items):
            base = day0 + timedelta(days=1 if "tomorrow" in key else 0)
            step = timedelta(hours=24 / len(items)) if len(items) in (24, 23, 25, 96, 92, 100) else timedelta(hours=1)
            for i, v in enumerate(items):
                out[base + i * step] = float(v) / (1000 if per_mwh else 1)
            continue
        for item in items:
            if not isinstance(item, dict):
                continue
            start = _when(next((item[k] for k in TIME_KEYS if k in item), None), tz)
            value = next((item[k] for k in VALUE_KEYS if isinstance(item.get(k), (int, float))), None)
            if start is None or value is None:
                continue
            used = next((k for k in VALUE_KEYS if k in item), "")
            if used.endswith("ct_per_kwh"):  # cents (not "ct" inside "electricity")
                value = value / 100
            elif used == "electricity_price" and abs(value) > 100:
                value = value / 10_000_000  # Zonneplan gives tenths of a micro-euro
            out[start.astimezone(tz)] = float(value) / (1000 if per_mwh else 1)
    return out


def companions(states: dict[str, dict], entity_id: str) -> list[str]:
    """The price entity and its "tomorrow" companion from the same integration - only one, of the same kind.

    An integration can have several entities for tomorrow: Strømligning has the full price (…_tomorrow_available_vat)
    and the spot price alone (…_tomorrow_spotprice_vat), with and without VAT. Only the one that matches today's
    entity is used (same markers: vat, spot, export, feed-in …), the most alike by name - never a mix.
    Octopus Energy keeps the rates on event entities (…_current_day_rates, …_next_day_rates) beside the
    …_current_rate sensor; Amber keeps the coming prices on a …_forecast sensor beside the …_price one."""
    obj = entity_id.split(".", 1)[1]
    prefix = obj.split("_")[0]
    base = re.sub(r"_(?:current_rate|current_day_rates|next_day_rates|previous_day_rates)$", "", obj)

    def marks(o: str) -> frozenset:
        return frozenset(m for m in ("vat", "spot", "export", "feed", "ex_vat", "excl", "incl", "raw") if m in o)

    def has_list(s: dict) -> bool:
        return any(isinstance((s.get("attributes") or {}).get(k), list) for k in LIST_KEYS)

    out = [entity_id]
    exact = {f"{base}_current_day_rates", f"{base}_next_day_rates", obj.replace("_price", "_forecast")} - {obj}
    for e, s in states.items():
        if e != entity_id and e.split(".", 1)[1] in exact and has_list(s):
            out.append(e)  # Octopus / Amber: the known pair
    if len(out) == 1:
        tomorrow = [e for e, s in states.items() if e != entity_id and has_list(s)
                    and (o := e.split(".", 1)[1]).startswith(prefix + "_")
                    and any(w in o for w in ("tomorrow", "i_morgen", "imorgen", "morgen")) and marks(o) == marks(obj)]
        if tomorrow:
            from difflib import SequenceMatcher

            out.append(max(tomorrow, key=lambda e: SequenceMatcher(None, e.split(".", 1)[1], obj).ratio()))
    return out


def now_price(states: dict[str, dict], entity_id: str | None, tz: ZoneInfo, scale: float = 1.0) -> float | None:
    """The price now: the entity's state, or (an event entity like Octopus') the slot now from its rates. scale: a
    price given in øre/cents is turned into kroner/euros (found by autofix.py)."""
    if not entity_id or not (s := states.get(entity_id)):
        return None
    try:
        return float(s.get("state")) * scale
    except (TypeError, ValueError):
        pass
    now = datetime.now(tz)
    prices: dict[datetime, float] = {}
    for e in companions(states, entity_id):
        prices.update(parse((states.get(e) or {}).get("attributes") or {}, tz, now.replace(hour=0, minute=0, second=0, microsecond=0)))
    past = [k for k in prices if k <= now]
    return prices[max(past)] * scale if past else None


def collect(states: dict[str, dict], entity_id: str | None, own: list[dict[str, Any]], tz: ZoneInfo,
            service: list[dict[str, Any]] | None = None, scale: float = 1.0) -> tuple[dict[datetime, float], dict[str, Any]]:
    """All known prices from the integration, with the missing hours filled from Energy Pilot's own prices.
    Returns (prices, info) - info says what was filled and if tomorrow is still missing."""
    now = datetime.now(tz)
    day0 = now.replace(hour=0, minute=0, second=0, microsecond=0)
    prices: dict[datetime, float] = {}
    if entity_id:
        for e in companions(states, entity_id):
            prices.update(parse((states.get(e) or {}).get("attributes") or {}, tz, day0))
        for p in service or []:  # prices an integration gives through its action
            when = _when(p.get("start"), tz)
            if when is not None:
                prices[when.astimezone(tz)] = float(p["price"])
        if "tempo" in entity_id:
            from . import tempo  # EDF Tempo: the prices come from the day colours

            if tempo.found(states):
                prices.update(tempo.prices(states, tz, now))
                own = []  # spot prices say nothing about tomorrow's colour - don't fill with them
        if scale != 1.0:
            prices = {k: v * scale for k, v in prices.items()}
    mine = {}
    for p in own or []:
        when = _when(p.get("start"), tz)
        if when is not None and isinstance(p.get("price"), (int, float)):
            mine[when.astimezone(tz)] = float(p["price"])
    filled = 0
    if prices and mine:
        # Same level as the user's own prices: the mean difference where both are known.
        both = [k for k in mine if k in prices]
        offset = sum(prices[k] - mine[k] for k in both) / len(both) if both else 0.0
        last = max(prices)
        for k, v in mine.items():
            if k > last:
                prices[k] = round(v + offset, 4)
                filled += 1
    elif not prices:
        prices = dict(mine)
    tomorrow = day0 + timedelta(days=1)
    has_tomorrow = any(tomorrow <= k < tomorrow + timedelta(days=1) for k in prices)
    return prices, {"filled": filled, "tomorrow_missing": now.hour >= 14 and not has_tomorrow}

energy_pilot/runner.py:
"""Runs the energy apps unchanged - in shadow (they only say what they would do) or in control.

Shadow means: no service is called and no state is written to Home Assistant. What the app would have done is kept,
and what it would have shown (its own sensors) is compared with what the running system shows, so you can see
whether the two agree before anything is switched over. The apps write their files (models, logs) in Energy Pilot's
own folder, never in AppDaemon's.
"""

from __future__ import annotations

import asyncio
from collections import deque
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, time as dtime, timedelta
import importlib.util
import json
import logging
import math
import os
from pathlib import Path
import re
import sys
import threading
import time
import traceback
import types
import uuid
from typing import Any, Callable
from zoneinfo import ZoneInfo

from . import hassapi
from .ha import HomeAssistant

_LOGGER = logging.getLogger(__name__)
SHADOW, CONTROL, OFF = "shadow", "control", "off"
CALL_TIMEOUT = 60


def install_shim() -> None:
    """`import appdaemon.plugins.hass.hassapi as hass` and `import hassapi as hass` both give our Hass."""
    for name in ("appdaemon", "appdaemon.plugins", "appdaemon.plugins.hass"):
        sys.modules.setdefault(name, types.ModuleType(name))
    sys.modules["appdaemon.plugins.hass.hassapi"] = hassapi
    sys.modules["hassapi"] = hassapi
    sys.modules["appdaemon"].plugins = sys.modules["appdaemon.plugins"]  # type: ignore[attr-defined]
    sys.modules["appdaemon.plugins"].hass = sys.modules["appdaemon.plugins.hass"]  # type: ignore[attr-defined]
    sys.modules["appdaemon.plugins.hass"].hassapi = hassapi  # type: ignore[attr-defined]


class App:
    def __init__(self, name: str, module: str, cls: str, args: dict[str, Any]) -> None:
        self.name, self.module, self.cls, self.args = name, module, cls, args
        self.instance: hassapi.Hass | None = None
        self.thread = ThreadPoolExecutor(max_workers=1, thread_name_prefix=name)
        self.log: deque = deque(maxlen=400)
        self.would: deque = deque(maxlen=300)  # services it would have called (shadow)
        self.errors = 0
        self.started: float | None = None
        self.shown: dict[str, dict[str, Any]] = {}  # entity -> what the app showed (its set_state)


class Runner:
    def __init__(self, ha: HomeAssistant, apps_dir: Path, data_dir: Path, apps: list[dict[str, Any]]) -> None:
        self.ha = ha
        self.apps_dir, self.data_dir = apps_dir, data_dir
        self.loop: asyncio.AbstractEventLoop | None = None
        self.apps: dict[str, App] = {a["name"]: App(a["name"], a["module"], a["class"], a.get("args") or {}) for a in apps}
        self.modes: dict[str, str] = {}
        self._handles: dict[str, Any] = {}
        self._state_listeners: dict[str, tuple[str, Callable, str | None, str | None, Any, Any, dict]] = {}
        self._overrides: dict[str, dict[str, Any]] = {}  # entities set by apps in shadow: what they see themselves
        self._lock = threading.RLock()
        self.compare: dict[str, dict[str, Any]] = {}
        self.tz = ZoneInfo("UTC")

    # ---------- modes ----------

    @property
    def _modes_file(self) -> Path:
        return self.data_dir / "energy_pilot_modes.json"

    def load_modes(self) -> None:
        try:
            self.modes = json.loads(self._modes_file.read_text())
        except (OSError, ValueError):
            self.modes = {}
        for name in self.apps:
            self.modes.setdefault(name, SHADOW)  # always starts in shadow

    def set_mode(self, name: str, mode: str) -> None:
        if name in self.apps and mode in (SHADOW, CONTROL, OFF):
            old = self.modes.get(name)
            self.modes[name] = mode
            self._modes_file.write_text(json.dumps(self.modes, indent=2))
            self.app_log(name, "INFO", f"Mode: {old} -> {mode}")
            if old == OFF and mode != OFF:
                self.loop.call_soon_threadsafe(lambda: asyncio.ensure_future(self._start_app(self.apps[name])))

    def all_to_shadow(self) -> None:
        for name in self.apps:
            if self.modes.get(name) == CONTROL:
                self.set_mode(name, SHADOW)

    def mode(self, name: str) -> str:
        return self.modes.get(name, SHADOW)

    # ---------- starting ----------

    async def start(self) -> None:
        self.loop = asyncio.get_running_loop()
        install_shim()
        self.load_modes()
        self.ha.on_state.append(self._on_state)
        await self.ha.connected.wait()
        self.tz = ZoneInfo(self.ha.config.get("time_zone") or "UTC")
        for app in self.apps.values():
            if self.mode(app.name) != OFF:
                await self._start_app(app)

    def _load_module(self, app: App) -> types.ModuleType:
        """The app's own file - with its "/config/..." paths pointed at Energy Pilot's folder."""
        path = self.apps_dir / f"{app.module}.py"
        source = path.read_text()
        data = str(self.data_dir).rstrip("/")
        source = re.sub(r"""(["'])/config/""", lambda m: f"{m[1]}{data}/", source)
        module = types.ModuleType(app.module)
        module.__file__ = str(path)
        sys.modules[app.module] = module
        exec(compile(source, str(path), "exec"), module.__dict__)  # noqa: S102 - the user's own app
        return module

    async def _start_app(self, app: App) -> None:
        def init() -> None:
            module = self._load_module(app)
            cls = getattr(module, app.cls)
            instance = cls.__new__(cls)
            hassapi.Hass.__init__(instance, self, app.name, app.args)
            app.instance = instance
            instance.initialize()

        try:
            await self.loop.run_in_executor(app.thread, init)
            app.started = time.time()
            self.app_log(app.name, "INFO", f"Started ({self.mode(app.name)})")
        except Exception:  # noqa: BLE001
            app.errors += 1
            self.app_log(app.name, "ERROR", "Could not start:\n" + traceback.format_exc())

    # ---------- logging ----------

    def app_log(self, name: str, level: str, text: str) -> None:
        app = self.apps.get(name)
        if app is not None:
            app.log.append({"t": time.time(), "level": level, "text": text[:4000]})
            if level in ("ERROR", "CRITICAL"):
                app.errors += 1
        logging.getLogger(f"app.{name}").log(getattr(logging, level, logging.INFO), text)

    # ---------- states (called from app threads) ----------

    def all_states(self, name: str) -> dict[str, dict[str, Any]]:
        with self._lock:
            return {**self.ha.states, **self._overrides}

    def state_of(self, name: str, entity_id: str) -> dict[str, Any] | None:
        with self._lock:
            if entity_id in self._overrides:
                return self._overrides[entity_id]
        return self.ha.states.get(entity_id)

    def set_state(self, name: str, entity_id: str, state: Any, attributes: dict[str, Any] | None,
                  replace: bool) -> dict[str, Any]:
        app = self.apps[name]
        old = self.state_of(name, entity_id) or {}
        attrs = dict(attributes or {}) if replace else {**(old.get("attributes") or {}), **(attributes or {})}
        now = datetime.now(self.tz).isoformat()
        new = {"entity_id": entity_id, "state": str(state) if state is not None else old.get("state", "unknown"),
               "attributes": attrs, "last_changed": now if old.get("state") != state else old.get("last_changed", now),
               "last_updated": now}
        app.shown[entity_id] = new
        if self.mode(name) == CONTROL:
            self._sync(self.ha.set_state(entity_id, new["state"], attrs))
            with self._lock:
                self._overrides.pop(entity_id, None)
        else:
            with self._lock:
                self._overrides[entity_id] = new
            self._compare(name, entity_id)
        return new

    def call_service(self, name: str, service: str, data: dict[str, Any]) -> Any:
        domain, _, svc = service.replace(".", "/", 1).partition("/")
        if svc.startswith("get_"):
            # Only reads (statistics, calendars, forecasts): done in shadow too, or the app would plan blind.
            result = self._sync(self.ha.call_service(domain, svc, dict(data), response=True), timeout=180)
            return {"success": True, "result": result}
        if self.mode(name) != CONTROL:
            self.apps[name].would.append({"t": time.time(), "service": f"{domain}.{svc}", "data": _plain(data)})
            # What the app sets on a helper it sees itself, as if it had happened.
            self._pretend(domain, svc, data)
            return None
        return {"success": True, "result": self._sync(self.ha.call_service(domain, svc, dict(data)))}

    def _pretend(self, domain: str, svc: str, data: dict[str, Any]) -> None:
        entity = data.get("entity_id")
        if not isinstance(entity, str):
            return
        value = data.get("value", data.get("option"))
        if svc in ("set_value", "select_option") and value is not None:
            base = self.ha.states.get(entity) or {"entity_id": entity, "attributes": {}}
            with self._lock:
                self._overrides[entity] = {**base, "state": str(value)}

    def fire_event(self, name: str, event: str, data: dict[str, Any]) -> None:
        if self.mode(name) != CONTROL:
            self.apps[name].would.append({"t": time.time(), "service": f"event:{event}", "data": _plain(data)})
            return
        self._sync(self.ha.command({"type": "fire_event", "event_type": event, "event_data": data}))

    def history(self, entity_id: str, start: datetime, end: datetime | None) -> list[list[dict[str, Any]]]:
        if start.tzinfo is None:
            start = start.replace(tzinfo=self.tz)
        if end is not None and end.tzinfo is None:
            end = end.replace(tzinfo=self.tz)
        rows = self._sync(self.ha.history(entity_id, start, end), timeout=180) or []
        for group in rows:
            for row in group:
                for key in ("last_changed", "last_updated"):
                    if isinstance(row.get(key), str):
                        try:
                            row[key] = datetime.fromisoformat(row[key]).astimezone(self.tz)
                        except ValueError:
                            pass
        return rows

    def _sync(self, coro: Any, timeout: float = CALL_TIMEOUT) -> Any:
        """Run a coroutine on the loop from an app thread, and wait for it."""
        if threading.current_thread() is threading.main_thread():
            raise RuntimeError("called from the loop")
        return asyncio.run_coroutine_threadsafe(coro, self.loop).result(timeout)

    # ---------- comparing with the running system ----------

    def _compare(self, name: str, entity_id: str) -> None:
        """Shadow vs. the real entity (written by the system that runs now): same value?"""
        mine = self.apps[name].shown.get(entity_id)
        real = self.ha.states.get(entity_id)
        if mine is None or real is None:
            return
        c = self.compare.setdefault(entity_id, {"app": name, "checks": 0, "same": 0})
        c["checks"] += 1
        same = _same(mine.get("state"), real.get("state"))
        c["same"] += 1 if same else 0
        c.update(mine=mine.get("state"), real=real.get("state"), t=time.time(), last_same=same)

    # ---------- listening and timers ----------

    def _on_state(self, entity_id: str, old: dict | None, new: dict | None) -> None:
        for app in self.apps.values():
            if entity_id in app.shown and self.mode(app.name) != CONTROL:
                self._compare(app.name, entity_id)  # the running system just wrote its value: compare again
        for handle, (name, cb, ent, attribute, want_new, want_old, kwargs) in list(self._state_listeners.items()):
            if ent is not None and ent != entity_id:
                continue
            if self.mode(name) == OFF:
                continue
            if attribute is None:
                o, n = (old or {}).get("state"), (new or {}).get("state")
            elif attribute == "all":
                o, n = old, new
            else:
                o, n = ((old or {}).get("attributes") or {}).get(attribute), ((new or {}).get("attributes") or {}).get(attribute)
            if attribute != "all" and o == n:
                continue
            if want_new is not None and n != want_new:
                continue
            if want_old is not None and o != want_old:
                continue
            self._run(name, cb, entity_id, attribute or "state", o, n, dict(kwargs))

    def listen_state(self, name: str, cb: Callable, entity_id: str | None, attribute: str | None, new: Any, old: Any,
                     duration: float | None, kwargs: dict[str, Any]) -> str:
        handle = uuid.uuid4().hex
        self._state_listeners[handle] = (name, cb, entity_id, attribute, new, old, kwargs)
        return handle

    def listen_event(self, name: str, cb: Callable, event: str | None, kwargs: dict[str, Any]) -> str:
        handle = uuid.uuid4().hex
        filters = {k: v for k, v in kwargs.items() if k not in ("namespace",)}

        def on_event(e: dict[str, Any]) -> None:
            data = e.get("data") or {}
            if any(data.get(k) != v for k, v in filters.items()):
                return
            if handle in self._handles and self.mode(name) != OFF:
                self._run(name, cb, e.get("event_type"), data, dict(kwargs))

        self._handles[handle] = ("event", name)
        self.loop.call_soon_threadsafe(lambda: asyncio.ensure_future(self.ha.listen_event(event or "*", on_event)))
        return handle

    def next_time(self, start: Any, daily: bool = False) -> float:
        """A timestamp for "now", a datetime (local, naive or aware), a time or "HH:MM:SS"."""
        now = datetime.now(self.tz)
        if start in (None, "now"):
            return now.timestamp()
        if isinstance(start, datetime):
            return (start if start.tzinfo else start.replace(tzinfo=self.tz)).timestamp()
        if isinstance(start, str):
            h, m, *s = (int(x) for x in start.split(":"))
            start = dtime(h, m, s[0] if s else 0)
        if isinstance(start, dtime):
            at = now.replace(hour=start.hour, minute=start.minute, second=start.second, microsecond=0)
            if at <= now:
                at += timedelta(days=1)
            return at.timestamp()
        raise ValueError(f"Unknown start time {start!r}")

    def schedule(self, name: str, cb: Callable, kwargs: dict[str, Any], delay: float | None = None,
                 at: float | None = None, every: float | None = None, daily: Any = None) -> str:
        handle = uuid.uuid4().hex
        when = time.time() + delay if delay is not None else at
        self._handles[handle] = ("timer", name)

        def arm(at_ts: float) -> None:
            if handle not in self._handles:
                return
            timer = self.loop.call_later(max(0.0, at_ts - time.time()), fire)
            self._handles[handle] = ("timer", name, timer)

        def fire() -> None:
            if handle not in self._handles:
                return
            if every:
                nxt = self.next_time(daily, daily=True) if daily is not None else time.time() + every
                arm(nxt)
            else:
                self._handles.pop(handle, None)
            if self.mode(name) != OFF:
                self._run(name, cb, dict(kwargs))

        self.loop.call_soon_threadsafe(arm, when)
        return handle

    def cancel(self, handle: str) -> bool:
        item = self._handles.pop(handle, None)
        self._state_listeners.pop(handle, None)
        if item and len(item) > 2:
            self.loop.call_soon_threadsafe(item[2].cancel)
        return item is not None

    def running(self, handle: str) -> bool:
        return handle in self._handles

    def _run(self, name: str, cb: Callable, *args: Any) -> None:
        app = self.apps[name]

        def call() -> None:
            try:
                cb(*args)
            except Exception:  # noqa: BLE001 - one failing callback doesn't stop the app
                self.app_log(name, "ERROR", f"{getattr(cb, '__name__', cb)} failed:\n" + traceback.format_exc())

        app.thread.submit(call)

    def stop(self) -> None:
        for app in self.apps.values():
            if app.instance is not None:
                try:
                    app.thread.submit(app.instance.terminate).result(10)
                except Exception:  # noqa: BLE001
                    pass
            app.thread.shutdown(wait=True, cancel_futures=True)
        for item in list(self._handles.values()):
            if len(item) > 2:
                item[2].cancel()
        self._handles.clear()

    # ---------- for the panel ----------

    def status(self) -> dict[str, Any]:
        out = []
        for app in self.apps.values():
            shown = sorted(app.shown)
            checks = [self.compare[e] for e in shown if e in self.compare]
            total = sum(c["checks"] for c in checks)
            same = sum(c["same"] for c in checks)
            out.append({
                "name": app.name, "mode": self.mode(app.name), "started": app.started, "errors": app.errors,
                "agree": round(100 * same / total) if total else None, "checks": total,
                "would": list(app.would)[-60:][::-1],
                "log": list(app.log)[-80:][::-1],
                "entities": [{"entity_id": e, **{k: v for k, v in self.compare.get(e, {}).items() if k != "app"},
                              "mine_now": app.shown[e].get("state")} for e in shown],
            })
        return {"apps": out, "connected": self.ha.connected.is_set(), "ha": self.ha.config.get("version")}


def _same(a: Any, b: Any) -> bool:
    try:
        x, y = float(a), float(b)
        return math.isclose(x, y, rel_tol=0.02, abs_tol=0.05)
    except (TypeError, ValueError):
        return str(a) == str(b)


def _plain(data: dict[str, Any]) -> dict[str, Any]:
    out = {}
    for k, v in data.items():
        out[k] = v if isinstance(v, (str, int, float, bool, type(None), list, dict)) else str(v)
    return out

energy_pilot/runtime.py:
"""How long the battery lasts - worked out hour by hour, not from the power right now (that jumps every time the
kettle is on). Two answers:

- "until": how long the battery carries the house without power from the grid - the house's expected use (what the
  engine has learned) minus the sun's forecast, from the level now down to the lowest level. The number people want,
  also when the grid goes down.
- the plan's curve: the battery hour by hour as planned - where it is lowest tonight, when it charges cheaply, when
  it is full.
"""

from __future__ import annotations

from datetime import datetime, timedelta
from typing import Any


def _f(v: Any) -> float | None:
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


ACTION = {"charge_grid": "charge", "charge_sun": "sun", "discharge": "use", "hold": "hold", "export": "sell"}


def next_action(steps: list[dict[str, Any]] | None, now: datetime) -> dict[str, Any] | None:
    """What the battery does now and until when - and what comes after. From the plan's steps."""
    rows = []
    for x in steps or []:
        try:
            rows.append((datetime.fromisoformat(x["t"]), ACTION.get(x.get("action"), "hold"), x.get("soc")))
        except (KeyError, TypeError, ValueError):
            continue
    rows.sort(key=lambda r: r[0])
    # the plan's slots may be quarters: each step lasts until the next one starts
    slot = min((b[0] - a[0] for a, b in zip(rows, rows[1:]) if b[0] > a[0]), default=timedelta(hours=1))
    rows = [r for r in rows if r[0] + slot > now]
    if not rows:
        return None
    do, i = rows[0][1], 0
    while i + 1 < len(rows) and rows[i + 1][1] == do:
        i += 1
    out = {"do": do, "to": (rows[i][0] + slot).isoformat(), "soc": rows[i][2]}
    if i + 1 < len(rows):
        out["then"] = rows[i + 1][1]
    return out


def evening(curve: list[dict[str, Any]], soc: float, cap: float, min_soc: float, hours: int = 4) -> dict[str, Any] | None:
    """The dearest few hours ahead: does the battery hold enough for them?"""
    if len(curve) < hours + 1 or any(c.get("price") is None for c in curve):
        return None
    best, at = None, None
    for i in range(1, len(curve) - hours + 1):
        avg = sum(c["price"] for c in curve[i:i + hours]) / hours
        if best is None or avg > best:
            best, at = avg, i
    win = curve[at:at + hours]
    need = sum(max(0.0, (c.get("house") or 0.0) - (c.get("sun") or 0.0)) for c in win)
    if need < 0.3:
        return None
    start = curve[at - 1]["soc"] if at else soc
    have = max(0.0, (start - min_soc) / 100 * cap)
    return {"from": win[0]["t"], "to": (datetime.fromisoformat(win[-1]["t"]) + timedelta(hours=1)).isoformat(),
            "need": round(need, 1), "have": round(have, 1), "ok": have >= need * 0.95}


def compute(plan: dict[str, Any], flow: dict[str, Any], capacity_kwh: float, min_soc: float, now: datetime,
            storm: dict[str, Any] | None = None, steps: list[dict[str, Any]] | None = None,
            events: list[dict[str, Any]] | None = None, sky: dict[str, Any] | None = None) -> dict[str, Any] | None:
    soc = _f((flow or {}).get("soc"))
    rows = [(datetime.fromisoformat(h["t"]), h) for h in (plan or {}).get("hours") or [] if h.get("t")]
    rows = [(t, h) for t, h in rows if t + timedelta(hours=1) > now]
    if soc is None or not capacity_kwh or not rows:
        return None
    house_now_kw = (_f((flow or {}).get("house")) or 0.0) / 1000
    room = max(0.0, (soc - min_soc) / 100 * capacity_kwh)  # what can still come out
    top = max(0.0, (100 - min_soc) / 100 * capacity_kwh)
    until, used, hours_used = None, 0.0, 0.0
    for i, (t, h) in enumerate(rows):
        frac = 1.0 if i else max(0.05, 1 - (now - t).total_seconds() / 3600)  # what is left of this hour
        start = now if i == 0 else t
        house = _f(h.get("house"))
        house = house if house is not None else house_now_kw
        net = (house - (_f(h.get("sun")) or 0.0)) * frac  # kWh the battery must give (minus: the sun fills it)
        if net > 0 and room - net <= 0:
            until = start + timedelta(hours=frac * room / net)
            used += room
            break
        room = min(top, room - net)
        if net > 0:
            used += net
        hours_used += frac
    curve = [{"t": t.isoformat(), "soc": round(_f(h.get("soc")) or 0, 1), "charge": bool(h.get("charge")), "sun": round(_f(h.get("sun")) or 0, 2),
              "house": round(_f(h.get("house")) or house_now_kw, 2), "price": _f(h.get("price"))}
             for t, h in rows if t < now + timedelta(hours=24) and h.get("soc") is not None]
    prices = sorted(c["price"] for c in curve if c["price"] is not None)
    if len(prices) >= 6:  # the dear hours: the top quarter - when prices differ at all
        thr = prices[int(len(prices) * 0.75)]
        for c in curve:
            c["dear"] = c["price"] is not None and c["price"] >= thr and c["price"] > prices[0] * 1.15
    night = [c for c in curve if datetime.fromisoformat(c["t"]) < now + timedelta(hours=18)]
    low = min(night, key=lambda c: c["soc"]) if night else None
    full = next((c for c in curve if c["soc"] >= 95), None)
    cheap = None
    for i, c in enumerate(curve):
        if c["charge"]:
            j = i
            while j + 1 < len(curve) and curve[j + 1]["charge"]:
                j += 1
            cheap = {"from": c["t"], "to": (datetime.fromisoformat(curve[j]["t"]) + timedelta(hours=1)).isoformat()}
            break
    end = rows[-1][0] + timedelta(hours=1)
    span_h = ((until or end) - now).total_seconds() / 3600
    return {
        "soc": round(soc, 1), "kwh": round(soc / 100 * capacity_kwh, 1), "min_soc": min_soc, "empty": soc <= min_soc + 0.5,
        "until": until.isoformat() if until else None, "beyond": None if until else end.isoformat(),
        "hours": round(span_h, 2), "house_kw": round(used / hours_used, 2) if hours_used and used else round(house_now_kw, 2),
        "low": low, "full": full["t"] if full else None, "cheap": cheap, "curve": curve, "storm": storm,
        "cap": capacity_kwh, "next": next_action(steps, now), "evening": evening(curve, soc, capacity_kwh, min_soc),
        "base": _base(curve, soc, capacity_kwh, min_soc),
        "events": [e for e in events or [] if curve and curve[0]["t"] <= e["t"] <= curve[-1]["t"]], "sky": sky,
    }


def _base(curve: list[dict[str, Any]], soc: float, cap: float, min_soc: float) -> dict[str, Any] | None:
    """With only the house's least use (fridge, lights, internet): how long the battery lasts."""
    use = sorted(c["house"] for c in curve if c.get("house"))
    if len(use) < 6:
        return None
    kw = max(0.1, sum(use[:3]) / 3)
    room = max(0.0, (soc - min_soc) / 100 * cap)
    return {"kw": round(kw, 2), "h": round(min(99.0, room / kw), 1)}

energy_pilot/scene.py:
"""What the flow card is dressed in: the time of day, the real weather, the season and the day's holiday - by country.

The holidays are the ones the country keeps (the holidays library gives the moving dates: Easter, Eid, Chinese New
Year, Diwali, Midsummer), each drawn in the card's own language: a ring of lights around the house in the holiday's
colours, or a few particles (fireworks, confetti, embers). A country not listed gets the weather and the season only.
The seasons follow the hemisphere (summer in December south of the equator) and stay away near the equator.
"""

from __future__ import annotations

from datetime import date, datetime, timedelta
from functools import lru_cache
import logging
from typing import Any

_LOGGER = logging.getLogger(__name__)

# where Christmas and Easter are kept (the rest of the world gets New Year and its own days)
NO_CHRISTMAS = {"IL", "SA", "AE", "QA", "KW", "OM", "BH", "IR", "IQ", "AF", "PK", "YE", "TR", "EG", "DZ", "MA", "TN", "LY",
                "JO", "SY", "LB", "ID", "MY", "BD", "CN", "IN", "NP", "TH", "VN", "KH", "LA", "MM", "MN", "JP", "KR", "TW"}
ORTHODOX = {"GR", "CY", "RU", "UA", "BY", "RO", "BG", "RS", "ME", "MK", "GE", "MD"}
CARNIVAL = {"DK", "NO", "SE", "DE", "AT", "CH", "NL", "BE", "LU", "FR", "IT", "ES", "PT", "BR", "AR", "UY", "CO", "MX", "HR", "SI"}
HALLOWEEN = {"US", "CA", "GB", "IE", "AU", "NZ", "DK", "NO", "SE", "NL", "DE", "BE"}
MIDSUMMER = {"DK": "23-06", "NO": "23-06", "EE": "23-06", "LV": "23-06", "LT": "23-06"}  # SE and FI: the library's Midsummer Eve
# national days: (day-month, colours of the flag)
NATIONAL = {
    "DK": ("05-06", ["#c8102e", "#ffffff"]), "NO": ("17-05", ["#ba0c2f", "#ffffff", "#00205b"]), "SE": ("06-06", ["#006aa7", "#fecc00"]),
    "FI": ("06-12", ["#002f6c", "#ffffff"]), "US": ("04-07", ["#b22234", "#ffffff", "#3c3b6e"]), "FR": ("14-07", ["#0055a4", "#ffffff", "#ef4135"]),
    "NL": ("27-04", ["#ff7f00", "#ffa62e"]), "DE": ("03-10", ["#000000", "#dd0000", "#ffce00"]), "CA": ("01-07", ["#d52b1e", "#ffffff"]),
    "IE": ("17-03", ["#169b62", "#ffffff", "#ff883e"]), "CH": ("01-08", ["#d52b1e", "#ffffff"]), "BE": ("21-07", ["#000000", "#fdda24", "#ef3340"]),
    "IT": ("02-06", ["#009246", "#ffffff", "#ce2b37"]), "ES": ("12-10", ["#aa151b", "#f1bf00"]), "PL": ("03-05", ["#ffffff", "#dc143c"]),
    "AT": ("26-10", ["#ed2939", "#ffffff"]), "PT": ("10-06", ["#006600", "#ff0000"]), "IS": ("17-06", ["#02529c", "#ffffff", "#dc1e35"]),
}
LUNAR = {"CN", "TW", "HK", "MO", "SG", "VN", "KR", "MY"}
DIWALI = {"IN", "NP", "SG", "MY", "LK", "MU", "FJ"}
EID = {"SA", "AE", "QA", "KW", "OM", "BH", "TR", "EG", "ID", "MY", "PK", "BD", "MA", "DZ", "TN", "JO", "IQ", "IR", "SN", "NG"}

COLOURS = {
    "jul": ["#ff4d5e", "#ffd34d", "#3ddc84", "#4dc3ff"], "paaske": ["#ffb3cf", "#ffe680", "#a8e6a1", "#9fd0ff"],
    "halloween": ["#ff8a2a", "#9b5de5"], "thanksgiving": ["#e8892c", "#c4542a", "#f0b04a"], "lunar": ["#e0262a", "#ffd34d"],
    "diwali": ["#ffb02e", "#ff7a2a", "#ffe08a"], "eid": ["#1f9e5a", "#ffd34d"],
}


@lru_cache(maxsize=32)
def _hol(country: str, year: int) -> dict[date, str]:
    try:
        import holidays

        return dict(holidays.country_holidays(country, years=year, language="en_US"))
    except Exception:  # noqa: BLE001 - a country the library doesn't know, or no library: the fixed days only
        try:
            import holidays

            return dict(holidays.country_holidays(country, years=year))
        except Exception:  # noqa: BLE001
            return {}


def _named(country: str, day: date, *names: str) -> bool:
    return any(any(n.lower() in str(v).lower() for n in names) for d, v in _hol(country, day.year).items() if d == day)


def _near(country: str, day: date, before: int, after: int, *names: str) -> bool:
    """A holiday of that name within some days of today (Eid lasts three days, Chinese New Year starts the eve before)."""
    found = set()
    for y in {day.year - 1, day.year, day.year + 1}:
        for d, v in _hol(country, y).items():
            if any(n.lower() in str(v).lower() for n in names):
                found.add(d)
    return any(d - timedelta(days=before) <= day <= d + timedelta(days=after) for d in found)

def easter(year: int, orthodox: bool = False) -> date:
    """Easter Sunday - western (Gauss/Meeus) or Orthodox (Julian, given in the Gregorian calendar)."""
    if orthodox:
        a, b, c = year % 4, year % 7, year % 19
        d = (19 * c + 15) % 30
        e = (2 * a + 4 * b - d + 34) % 7
        month, day = divmod(d + e + 114, 31)
        return date(year, month, day + 1) + timedelta(days=year // 100 - year // 400 - 2)  # Julian to Gregorian
    a, b, c = year % 19, year // 100, year % 100
    d, e = b // 4, b % 4
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i, k = c // 4, c % 4
    l_ = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * l_) // 451
    month, day = divmod(h + l_ - 7 * m + 114, 31)
    return date(year, month, day + 1)


def holiday(country: str | None, today: date) -> dict[str, Any] | None:
    """The day's holiday where the home is: {"key", "colours"} - None on an ordinary day."""
    c = (country or "").upper()
    d, dm = today, today.strftime("%d-%m")
    if (d.month, d.day) in ((12, 31), (1, 1)):
        return {"key": "nytaar", "colours": ["#ff5d8f", "#ffd84d", "#5dd6ff"]}
    if c in NATIONAL and NATIONAL[c][0] == dm:
        return {"key": "national", "colours": NATIONAL[c][1]}
    if c == "GB" and dm == "05-11":
        return {"key": "bonfire", "colours": ["#ff7a2a", "#ffd84d"]}
    if c in MIDSUMMER and MIDSUMMER[c] == dm or c in ("SE", "FI") and (_named(c, d, "Midsummer Eve") or _named(c, d + timedelta(days=1), "Midsummer Day")):
        return {"key": "midsummer", "colours": ["#ffb02e", "#ff7a2a"]}  # Sweden lists only the Day: the evening before is the feast
    if c == "US" and d.month == 11 and d.weekday() == 3 and 22 <= d.day <= 28 or c == "CA" and d.month == 10 and d.weekday() == 0 and 8 <= d.day <= 14:
        return {"key": "thanksgiving", "colours": COLOURS["thanksgiving"]}
    if c in LUNAR and _near(c, d, 1, 3, "Lunar New Year", "Chinese New Year", "Spring Festival", "Tet", "Seollal", "Korean New Year"):
        return {"key": "lunar", "colours": COLOURS["lunar"]}
    if c in DIWALI and _near(c, d, 2, 2, "Diwali", "Deepavali"):
        return {"key": "diwali", "colours": COLOURS["diwali"]}
    if c in EID and _near(c, d, 0, 2, "Eid al-Fitr", "Eid ul-Fitr", "Id-ul-Fitr", "Ramazan", "Hari Raya Puasa", "Lebaran"):
        return {"key": "eid", "colours": COLOURS["eid"]}
    if c not in NO_CHRISTMAS:
        e = easter(d.year, c in ORTHODOX)
        if c in CARNIVAL and e - timedelta(days=51) <= d <= e - timedelta(days=47):  # Fastelavn / Rosenmontag / Mardi Gras
            return {"key": "carnival", "colours": ["#ff5d8f", "#ffd84d", "#5dd6ff", "#3ddc84", "#a78bfa"]}
        if e - timedelta(days=7) <= d <= e + timedelta(days=1):
            return {"key": "paaske", "colours": COLOURS["paaske"]}
    if c in HALLOWEEN and d.month == 10 and d.day >= 24:
        return {"key": "halloween", "colours": COLOURS["halloween"]}
    if c not in NO_CHRISTMAS:
        xmas = date(d.year, 12, 25)
        advent1 = xmas - timedelta(days=(xmas.isoweekday() % 7 or 7) + 21)  # the fourth Sunday before Christmas
        if advent1 <= d <= date(d.year, 12, 26):
            return {"key": "jul", "colours": COLOURS["jul"]}
    return None


def season(today: date, lat: float | None) -> str | None:
    """spring/summer/autumn/winter where the home is - None near the equator, where there are none to speak of."""
    if lat is not None and abs(lat) < 23.5:
        return None
    m = today.month
    s = "winter" if m in (12, 1, 2) else "spring" if m in (3, 4, 5) else "summer" if m in (6, 7, 8) else "autumn"
    if lat is not None and lat < 0:
        s = {"winter": "summer", "summer": "winter", "spring": "autumn", "autumn": "spring"}[s]
    return s


def build(states: dict[str, Any], config: dict[str, Any], now: datetime) -> dict[str, Any]:
    """Everything the card needs to dress itself, from Home Assistant's own sun, weather and location."""
    sun = (states.get("sun.sun") or {}).get("attributes") or {}
    w = next((v for e, v in sorted(states.items()) if e.startswith("weather.")), None) or {}
    a = w.get("attributes") or {}
    wind = a.get("wind_speed")
    try:
        unit = str(a.get("wind_speed_unit") or "km/h").lower()
        wind = round(float(wind) / {"km/h": 3.6, "mph": 2.237, "kn": 1.944, "ft/s": 3.281}.get(unit, 1.0), 1)
    except (TypeError, ValueError):
        wind = None
    try:
        lat = float(config.get("latitude"))
    except (TypeError, ValueError):
        lat = None
    try:
        outdoor = float(a.get("temperature"))
        if "F" in str(a.get("temperature_unit") or ""):
            outdoor = (outdoor - 32) * 5 / 9
    except (TypeError, ValueError):
        outdoor = None
    try:
        hol = holiday(config.get("country"), now.date())
    except Exception:  # noqa: BLE001 - never let decoration break the page
        _LOGGER.debug("No holiday", exc_info=True)
        hol = None
    try:
        el = float(sun.get("elevation"))
        time_ = "day" if el > 6 else "dusk" if el > -6 else "night"
    except (TypeError, ValueError):
        time_ = "night" if (states.get("sun.sun") or {}).get("state") == "below_horizon" else "day"
    return {"elevation": sun.get("elevation"), "time": time_, "condition": w.get("state"), "cloud": a.get("cloud_coverage"), "wind": wind,
            "outdoor": outdoor, "season": season(now.date(), lat), "holiday": hol}

energy_pilot/selftest.py:
"""Test your system: Energy Pilot tries each thing it can tell the battery and the charger to do, watches whether it
really happens, mends what it can by itself, and puts everything back as it was.

Safe by design:
- Only the controls the brand's profile uses are touched - the same ones Energy Pilot controls anyway.
- At most 1 kW, a couple of minutes per step, and only when the user presses the button. A stop button puts it all
  back at once.
- Before the test every control's value is saved - on disk, so a restart in the middle still puts them back.
- A step only passes when the battery has done the right thing for 30 seconds in a row, after at least a minute.
- When a step fails, the control's other options are tried one at a time (never off-grid, calibration, factory …).
  One that works is kept for this installation and shown, and the user can undo it.
"""

from __future__ import annotations

import asyncio
import logging
import re
import time
from typing import Any
from urllib.parse import quote

_LOGGER = logging.getLogger(__name__)

REPO = "https://github.com/Clahen86/Energy-pilot/issues/new"
TEST_W = 1000  # at most this much power during a test
SAMPLE_S = 10  # how often the battery is looked at
STEADY_S = 30  # right this long in a row …
MIN_S = 60  # … and never sooner than this after a command
WAIT_S = {"local": 120, "cloud": 600, "car": 180}  # a cloud (AlphaESS, Tesla, EcoFlow) can take several minutes
CLOUD = {"alphaess", "tesla", "ecoflow"}
MAX_TRIES = 5  # other options tried for one step
# Options never tried: they could take the house off the grid, wipe settings or stop the inverter.
UNSAFE = re.compile(r"off.?grid|island|\beps\b|backup|calibrat|factory|reset|emergenc|maint|\btest|update|firmware|"
                    r"shut.?down|power.?off|standby|forbid|disable|\boff\b|sleep|debug|service", re.I)


def _norm(x: Any) -> str:
    return re.sub(r"[^a-z0-9]", "", str(x).lower())


def _expect(intent: str, f: dict[str, Any], base: dict[str, Any]) -> bool | None:
    """Is the battery doing what the step asked for? None: there is nothing to tell by."""
    b, g = f.get("battery"), f.get("grid")
    if b is None:
        return None
    if intent == "charge":
        return b >= 300
    if intent == "hold":
        return b >= -150  # not discharging (the sun may still charge it)
    if intent == "export":
        return b <= -300 and (g is None or g <= -100)
    # normal: the battery covers the house again - not charging from the grid, not selling
    return not (b > 300 and (g or 0) > 300) and not (b < -300 and (g or 0) < -300)


def _expect_car(step: str, f: dict[str, Any], base: dict[str, Any]) -> bool | None:
    ev = f.get("ev")
    if ev is None:
        return None
    if step == "start":
        return ev >= 1000
    if step == "low":
        return ev >= 500 and ev <= (base.get("ev_high") or 99999) * 0.75
    return ev < 200  # stop


class SelfTest:
    def __init__(self, controller: Any, overview: Any) -> None:
        self.ctl, self.ov = controller, overview
        self._task: asyncio.Task | None = None
        self._stop = False

    # ---------- what the page shows ----------
    @property
    def state(self) -> dict[str, Any]:
        return self.ov.settings.get("selftest") or {}

    def _save(self, **kw: Any) -> None:
        self.ov.save({"selftest": {**self.state, **kw}})

    def status(self) -> dict[str, Any]:
        s = dict(self.state)
        s.pop("saved", None)
        s["running"] = bool(self._task and not self._task.done())
        s["can"] = self.can()
        s["fixes"] = self.fixes_list()
        s["report_url"] = self.report_url() if s.get("results") else None
        return s

    def can(self) -> dict[str, Any]:
        """What can be tested now - and why not."""
        f = self.ov.flow()
        out: dict[str, Any] = {}
        if self.ctl.profile_steps("battery") and (f.get("has") or {}).get("battery"):
            out["battery"] = None if f.get("battery") is not None else "no_power"
        else:
            out["battery"] = "no_battery"
        if self.ctl.entities.get("car") or self.ctl.platforms.get("car"):
            out["car"] = None if f.get("plug") else "not_plugged"
        else:
            out["car"] = "no_charger"
        return out

    def fixes_list(self) -> list[dict[str, Any]]:
        fx = self.ov.settings.get("profile_fixes") or {}
        return [{"part": p, "intent": i, "entity": e, **v} for p, by in fx.items() for i, ents in by.items() for e, v in ents.items()]

    # ---------- start / stop ----------
    def start(self, parts: list[str]) -> bool:
        if self._task and not self._task.done():
            return False
        can = self.can()
        parts = [p for p in parts if p in ("battery", "car") and can.get(p) is None]
        if not parts:
            return False
        self._stop = False
        self._save(parts=parts, results=[], step=None, started=time.time(), finished=None, restored=None, stopped=False)
        self._task = asyncio.create_task(self._run(parts))
        return True

    def stop(self) -> None:
        self._stop = True

    def undo(self, part: str, intent: str, entity: str) -> None:
        fx = dict(self.ov.settings.get("profile_fixes") or {})
        fx.get(part, {}).get(intent, {}).pop(entity, None)
        self.ov.save({"profile_fixes": fx})
        self.ctl.last.pop(part, None)

    async def recover(self) -> None:
        """After a restart in the middle of a test: put the saved values back."""
        if self.state.get("saved") and not self.state.get("restored"):
            _LOGGER.info("A test was cut short - putting the saved settings back")
            await self._restore()

    # ---------- the test ----------
    async def _run(self, parts: list[str]) -> None:
        self.ctl.testing = set(parts)
        try:
            snap = self._snapshot(parts)
            self._mem = snap  # kept here too: put back even if the file can't hold it
            self._save(saved=snap)
            if snap and self.state.get("saved") != snap:
                raise RuntimeError("the saved settings could not be stored - nothing is tried")
            if "battery" in parts:
                await self._battery()
            if "car" in parts and not self._stop:
                await self._car()
        except Exception:  # noqa: BLE001
            _LOGGER.warning("Test failed", exc_info=True)
            self._result("error", "error", "failed", note="error")
        finally:
            await self._restore()
            self.ctl.testing = set()
            for p in parts:
                self.ctl.last.pop(p, None)  # the plan takes over again at once
            self._save(step=None, finished=time.time(), stopped=self._stop)
            tel = getattr(self.ov, "telemetry", None)
            if tel and not self._stop:
                tel.test_result(self.state.get("results") or [])

    def _result(self, part: str, step: str, result: str, **kw: Any) -> None:
        res = [r for r in self.state.get("results") or [] if not (r["part"] == part and r["step"] == step)]
        self._save(results=res + [{"part": part, "step": step, "result": result, **kw}])

    def _entities(self, part: str) -> list[str]:
        """Every control the profile (or the charger) could touch."""
        if part == "battery":
            steps = self.ctl.profile_steps("battery") or {}
            try:
                want = (self.ctl.intents().get("battery") or {"ctx": {}})["ctx"]
            except Exception:  # noqa: BLE001
                want = {}
            ids: set[str] = set()
            for intent, st in steps.items():
                if intent in ("normal", "hold", "charge", "export") and isinstance(st, list):
                    try:
                        from . import adapters
                        for c in adapters.resolve(st, self.ctl._pool("battery"), {**_ctx_defaults(), **want}):
                            e = (c.get("data") or {}).get("entity_id")
                            if isinstance(e, str):
                                ids.add(e)
                    except Exception:  # noqa: BLE001
                        continue
            return sorted(ids)
        return sorted(e for e in self.ctl.entities.get("car", []) if e.split(".")[0] in ("select", "number", "switch"))

    def _snapshot(self, parts: list[str]) -> dict[str, str]:
        out = {}
        for p in parts:
            for e in self._entities(p):
                st = self.ctl.ha.states.get(e) or {}
                v = st.get("state")
                if e.split(".")[0] in ("select", "number", "switch") and v not in (None, "unavailable", "unknown"):
                    out[e] = v
        return out

    @staticmethod
    def _restore_calls(saved: dict[str, str]) -> list[dict[str, Any]]:
        calls = []
        for e, v in saved.items():
            d = e.split(".")[0]
            if d == "select":
                calls.append({"domain": "select", "service": "select_option", "data": {"entity_id": e, "option": v}})
            elif d == "number":
                try:
                    n = float(v)
                except ValueError:
                    continue
                calls.append({"domain": "number", "service": "set_value", "data": {"entity_id": e, "value": int(n) if n.is_integer() else n}})
            elif d == "switch" and v in ("on", "off"):
                calls.append({"domain": "switch", "service": f"turn_{v}", "data": {"entity_id": e}})
        return calls

    def _offline(self, e: str | None) -> bool:
        return (self.ctl.ha.states.get(e or "") or {}).get("state") in (None, "unavailable", "unknown")

    async def _restore(self) -> None:
        saved = self.state.get("saved") or getattr(self, "_mem", None) or {}
        calls = self._restore_calls(saved)
        result = await self.ctl._send(calls) if calls else "ok"
        left = [c["data"]["entity_id"] for c in calls if self.ctl._matches(c) is False]
        # What is offline now (the charger's integration gone) goes back by itself once it returns (retry_pending).
        pending = {e: saved[e] for e in left if self._offline(e)}
        self._mem = {}
        self._save(saved={}, restored={"result": result, "left": [{"entity": e, "value": saved[e]} for e in left],
                                       "pending": pending or None, "pending_since": time.time() if pending else None})

    async def retry_pending(self) -> None:
        """Settings the test couldn't put back because their device was offline: put back as soon as it's online
        again - once, and not after two days (by then they may have been changed on purpose)."""
        r = self.state.get("restored") or {}
        pending = r.get("pending") or {}
        if not pending or (self._task and not self._task.done()):
            return
        if time.time() - (r.get("pending_since") or 0) > 2 * 86400:
            self._save(restored={**r, "pending": None})
            return
        back = {e: v for e, v in pending.items() if not self._offline(e)}
        if not back:
            return
        calls = self._restore_calls(back)
        result = await self.ctl._send(calls) if calls else "ok"
        wrong = {c["data"]["entity_id"] for c in calls if self.ctl._matches(c) is False}
        still = {e: v for e, v in pending.items() if e not in back}
        left = [{"entity": e, "value": v} for e, v in pending.items() if e in still or e in wrong]
        _LOGGER.info("Put back %d setting(s) the test left while offline", len(back) - len(wrong))
        self._save(restored={**r, "result": "ok" if not left else result, "left": left, "pending": still or None})

    async def _watch(self, check: Any, wait_s: int, base: dict[str, Any]) -> tuple[bool | None, dict[str, Any]]:
        """Look every 10 s; right for 30 s in a row and at least a minute after the command = passed."""
        t0, good_since, seen, last = time.time(), None, False, {}
        while time.time() - t0 < wait_s and not self._stop:
            await asyncio.sleep(SAMPLE_S)
            last = self.ov.flow()
            ok = check(last, base)
            if ok is None:
                good_since = None
                continue
            seen = True
            good_since = (good_since or time.time()) if ok else None
            if good_since and time.time() - good_since >= STEADY_S and time.time() - t0 >= MIN_S:
                return True, last
        return (False if seen else None), last

    async def _step(self, part: str, intent: str, calls: list[dict[str, Any]], check: Any, wait_s: int,
                    base: dict[str, Any]) -> None:
        self._save(step={"part": part, "step": intent, "since": time.time()})
        sent = await self.ctl._send(calls, force=True)
        ok, f = await self._watch(check, wait_s, base)
        if ok:
            self._result(part, intent, "ok")
            return
        if self._stop:
            return
        # Not right: try the control's other options, one at a time.
        for c, opt in self._alternatives(calls):
            if self._stop:
                return
            self._save(step={"part": part, "step": intent, "since": time.time(), "trying": {"entity": c["data"]["entity_id"], "option": opt}})
            tried = [x if x is not c else {**c, "data": {**c["data"], "option": opt}} for x in calls]
            await self.ctl._send(tried, force=True)
            ok, f = await self._watch(check, wait_s, base)
            if ok:
                e = c["data"]["entity_id"]
                fx = dict(self.ov.settings.get("profile_fixes") or {})
                fx.setdefault(part, {}).setdefault(intent, {})[e] = {"from": c["data"]["option"], "to": opt}
                self.ov.save({"profile_fixes": fx})
                self._result(part, intent, "fixed", entity=e, option_from=c["data"]["option"], option_to=opt)
                return
        why = "rejected" if sent != "ok" else ("no_reaction" if ok is False else "no_data")
        if any(self._offline(c["data"].get("entity_id")) for c in calls if isinstance(c["data"].get("entity_id"), str)):
            why = "offline"  # the device's integration went away in Home Assistant (e.g. evcc unreachable), not a refusal
        err = getattr(self.ctl, "last_send_error", None) if sent != "ok" else None
        from .checks import ALPHA_PERIOD
        if err and ALPHA_PERIOD.search(err):
            why = "alpha_period"  # AlphaESS changes only a period that exists: one has to be made in its app first
        rejected = [{"entity": c["data"].get("entity_id"), "value": c["data"].get("option", c["data"].get("value"))}
                    for c in calls if self.ctl._matches(c) is False]
        self._result(part, intent, "failed", why=why, rejected=rejected, error=err,
                     seen={k: f.get(k) for k in ("battery", "grid", "ev") if f})

    def _alternatives(self, calls: list[dict[str, Any]]) -> list[tuple[dict[str, Any], str]]:
        """Other safe options for the selects in a step, the most alike first; at most a handful in all."""
        out = []
        for c in calls:
            if c.get("service") != "select_option":
                continue
            e, want = c["data"]["entity_id"], str(c["data"].get("option"))
            opts = ((self.ctl.ha.states.get(e) or {}).get("attributes") or {}).get("options") or []
            words = set(re.findall(r"[a-z]{3,}", want.lower()))
            cands = [o for o in opts if str(o) != want and not UNSAFE.search(str(o))]
            cands.sort(key=lambda o: -len(words & set(re.findall(r"[a-z]{3,}", str(o).lower()))))
            out += [(c, str(o)) for o in cands]
        return out[:MAX_TRIES]

    async def _battery(self) -> None:
        f = self.ov.flow()
        soc = f.get("soc")
        try:
            want = self.ctl.intents().get("battery") or {"ctx": {}}
        except Exception:  # noqa: BLE001 - no plan yet: the test still runs
            want = {"ctx": {}}
        ctx = {**_ctx_defaults(), **want["ctx"]}
        ctx = _limit(ctx, soc)
        steps = self.ctl.profile_steps("battery") or {}
        key = self.ctl.profile_key("battery") or ""
        wait_s = WAIT_S["cloud" if key in CLOUD else "local"]
        plan = ["hold", "charge"]
        if steps.get("export") and self.ov.settings.get("battery_export"):
            plan.append("export")
        plan.append("normal")
        base = {"battery": f.get("battery"), "grid": f.get("grid")}
        for intent in plan:
            if self._stop:
                return
            if intent == "charge" and soc is not None and soc >= 97:
                self._result("battery", intent, "skipped", why="full")
                continue
            min_soc = float(ctx.get("min_soc") or 10)
            if intent == "export" and soc is not None and soc <= min_soc + 5:
                self._result("battery", intent, "skipped", why="empty")
                continue
            c = dict(ctx)
            if intent == "export":
                c["target"] = c["_export_target"]
            elif intent == "hold" and soc is not None:
                c["target"] = round(soc)
            calls = self.ctl.calls("battery", {"intent": intent, "ctx": c})
            await self._step("battery", intent, calls, lambda fl, b, i=intent: _expect(i, fl, b), wait_s, base)

    async def _car(self) -> None:
        base: dict[str, Any] = {}
        top = 16
        for step, intent, amps in (("start", "charge", top), ("low", "charge", 6), ("stop", "stop", top)):
            if self._stop:
                return
            calls = self.ctl.calls("car", {"intent": intent, "ctx": {"current": amps}})
            await self._step("car", step, calls, lambda fl, b, s=step: _expect_car(s, fl, b), WAIT_S["car"], base)
            if step == "start":
                base["ev_high"] = self.ov.flow().get("ev")
                if not base["ev_high"] or base["ev_high"] < 1000:
                    self._result("car", "low", "skipped", why="not_charging")
                    self._result("car", "stop", "skipped", why="not_charging")
                    return

    # ---------- the report ----------
    def report_url(self) -> str | None:
        s = self.state
        res = s.get("results") or []
        if not res:
            return None
        import os
        prof = self.ctl.profile_key("battery")
        lines = [f"**Energy Pilot** {os.environ.get('BUILD_VERSION', 'dev')} · profile `{prof}` · model `{getattr(self.ctl, 'model', None)}`",
                 f"Battery integration `{self.ctl.platforms.get('battery')}` · charger `{self.ctl.platforms.get('car')}`", "",
                 "| Part | Step | Result | Details |", "|---|---|---|---|"]
        mark = {"ok": "✅", "fixed": "🔧", "failed": "❌", "skipped": "⏭️"}
        for r in res:
            det = ""
            if r["result"] == "fixed":
                det = f"`{r.get('entity')}`: `{r.get('option_from')}` → `{r.get('option_to')}`"
            elif r["result"] == "failed":
                bad = ", ".join("`%s`=%s" % (x["entity"], x["value"]) for x in r.get("rejected") or [])
                det = f"{r.get('why')} {bad} seen {r.get('seen')}"
            elif r["result"] == "skipped":
                det = str(r.get("why"))
            lines.append(f"| {r['part']} | {r['step']} | {mark.get(r['result'], r['result'])} | {det} |")
        left = (s.get("restored") or {}).get("left") or []
        if left:
            lines += ["", "Not put back: " + ", ".join("`%s`=%s" % (x["entity"], x["value"]) for x in left)]
        body = "\n".join(lines)[:6000]
        title = f"Test result: {prof or 'battery'}"
        return f"{REPO}?title={quote(title)}&labels=test-result&body={quote(body)}"


def _ctx_defaults() -> dict[str, Any]:
    from datetime import datetime

    from . import adapters

    return {"grid_charge": True, "min_soc": 10, "soc": 50, "target": 50, "rate": 10, "power_w": TEST_W, "max_power_w": TEST_W,
            "max_charge_w": TEST_W, "power_kw": TEST_W / 1000, "max_charge_kw": TEST_W / 1000, "max_power_kw": TEST_W / 1000,
            "export_w": 800, "house_w": 0, "device_id": "", "serial": "", "charge_a": 20,
            **adapters.alpha_windows(datetime.now())}


def _limit(ctx: dict[str, Any], soc: float | None) -> dict[str, Any]:
    """At most 1 kW, and a target a few percent away - so a step can't run on."""
    out = dict(ctx)
    for k in ("power_w", "export_w"):
        out[k] = min(float(out.get(k) or TEST_W), TEST_W if k == "power_w" else 800)
    out["power_kw"] = round(out["power_w"] / 1000, 2)
    if "charge_a" in out:
        out["charge_a"] = max(1, min(int(out["charge_a"] or 20), 20))
    if soc is not None:
        out["soc"] = round(soc)
        out["target"] = round(min(100, soc + 5))
    out["_export_target"] = round(max(float(out.get("min_soc") or 10), (soc or 50) - 5))
    return out

energy_pilot/setupinfo.py:
"""How this installation is set up - sent with the daily question when sharing is on, so the brand profiles can be
fixed: each inverter/battery and charger with its integration, profile, maker and model, the entities used (what for,
their values), what failed. Entity names are sent with the user's own device name taken out
("select.<device>_export_limiter") unless "Share my setup" is on. Never names of people or places, never history."""

from __future__ import annotations

import re
from typing import Any

BATTERY_ROLES = ("battery_power", "battery_soc", "pv_power", "grid_power", "house_power", "solar_today", "sell_price")
CAR_ROLES = ("ev_power", "ev_plug", "ev_soc")


_TRANSLIT = str.maketrans({"æ": "ae", "ø": "o", "å": "a", "ä": "a", "ö": "o", "ü": "u", "ß": "ss", "œ": "oe", "ð": "d", "þ": "th", "ł": "l", "đ": "d"})


def _slug(text: str) -> str:
    """Like Home Assistant's own slugify: "Badeværelse" -> "badevaerelse", "Küche" -> "kuche" - so the names match the
    entity ids Home Assistant made."""
    import unicodedata

    t = str(text).lower().translate(_TRANSLIT)
    t = unicodedata.normalize("NFKD", t).encode("ascii", "ignore").decode()
    return re.sub(r"_+", "_", re.sub(r"[^a-z0-9]+", "_", t)).strip("_")


# Words integrations use in their entity names that a zone or the home may also be called.
GENERIC = {"work", "home", "house", "grid", "solar", "battery", "garage", "office", "car", "load", "main", "power",
           "energy", "charger", "inverter", "meter", "total", "today", "mode"}


def personal_words(ov: Any, devices: dict[str, Any], areas: list[str], floors: list[str] | None = None) -> list[tuple[str, str]]:
    """The user's own names in this Home Assistant - people, rooms, zones, the home and devices - as slugs with what
    they become. Longest first, so "lilly_room" goes before "lilly"."""
    words: dict[str, str] = {}

    def add(name: Any, token: str, split: bool = False) -> None:
        s = _slug(name or "")
        if len(s) >= 3:
            words.setdefault(s, token)
        if split:  # a person's first name alone too
            for p in s.split("_"):
                if len(p) >= 3:
                    words.setdefault(p, token)
    states = ov.ha.states
    for e, st in states.items():
        nm = (st.get("attributes") or {}).get("friendly_name")
        if e.startswith("person."):
            add(nm, "<person>", True)
            add(e.split(".", 1)[1], "<person>", True)
        elif e.startswith("zone."):
            add(nm, "<zone>")
            add(e.split(".", 1)[1], "<zone>")
    add(ov.ha.config.get("location_name"), "<home>")
    # Rooms and floors stay in the names (the developer wants them - they help the profiles); people do not.
    for d in devices.values():
        if d.get("name_by_user"):
            add(d["name_by_user"], "<device>")
    return sorted(words.items(), key=lambda kv: -len(kv[0]))


def mask(entity_id: str, reg: dict[str, Any], devices: dict[str, Any], words: list[tuple[str, str]] | None = None) -> str:
    """Nearly the whole name: only the user's own names in it are swapped - this device's name for <device>, and
    people, rooms, zones and the home for <person>, <area>, <zone>, <home>. The rest is the integration's own words,
    which is what the profiles match on."""
    dom, obj = entity_id.split(".", 1)
    e = reg.get(entity_id) or {}
    d = devices.get(e.get("device_id") or "") or {}
    for n in [x for x in (d.get("name_by_user"), d.get("name")) if x]:
        s = _slug(n)
        if s and (obj == s or obj.startswith(s + "_")):
            obj = "<device>" + obj[len(s):]
            break
    parts = f"_{obj}_"
    # The integration's own words are never the user's: a zone called "Work" must not turn "work_mode" into
    # "<zone>_mode", nor a home called "Home" "home_power" - words in the entity's translation key, or common ones.
    own = set(_slug(e.get("translation_key") or "").split("_")) | GENERIC
    for w, token in words or []:
        if token in ("<zone>", "<home>") and w in own:
            continue
        parts = parts.replace(f"_{w}_", f"_{token}_")
    return f"{dom}.{parts.strip('_')}"


def entity(entity_id: str, use: str, states: dict[str, Any], reg: dict[str, Any], devices: dict[str, Any], full: bool,
           words: list[tuple[str, str]] | None = None) -> dict[str, Any]:
    st = states.get(entity_id) or {}
    a = st.get("attributes") or {}
    e = reg.get(entity_id) or {}
    out: dict[str, Any] = {"name": entity_id if full else mask(entity_id, reg, devices, words), "use": use, "platform": e.get("platform")}
    if e.get("translation_key"):
        out["key"] = e["translation_key"]
    for k in ("unit_of_measurement", "device_class", "min", "max", "step"):
        if isinstance(a.get(k), (str, int, float)) and len(str(a[k])) < 30:
            out[k] = a[k]
    if isinstance(a.get("options"), list):
        out["options"] = [str(x)[:40] for x in a["options"][:25]]
    dom = entity_id.split(".")[0]
    if dom in ("select", "switch", "binary_sensor") and st.get("state") is not None:
        out["state"] = str(st["state"])[:40]
    return out


def brand_device(entity_ids: list[str], reg: dict[str, Any], devices: dict[str, Any], platform: str | None = None,
                 known: list[str | None] | None = None) -> dict[str, Any]:
    """The device that tells the maker and model: the first of the entities used that belongs to a device with a maker;
    else a device Energy Pilot already found (the charger's, the battery's); else any device of the same integration."""
    def good(did: Any) -> dict[str, Any] | None:
        d = devices.get(did or "") or {}
        return d if d.get("manufacturer") or d.get("model") else None
    for e in entity_ids:
        if d := good((reg.get(e) or {}).get("device_id")):
            return d
    for did in known or []:
        if d := good(did):
            return d
    if platform:
        for e in reg.values():
            if e.get("platform") == platform and (d := good(e.get("device_id"))):
                return d
    return {}


def _charger_profile(plat: str | None, ents: list[str]) -> str | None:
    """A charger's profile: its integration's own actions when Energy Pilot knows them, else the switch and current."""
    from . import adapters

    if plat and plat in getattr(adapters, "CHARGER_SERVICES", {}):
        return plat
    return "generic" if ents else None


def _bucket(v: Any, edges: list[float], unit: str) -> str | None:
    try:
        x = float(v)
    except (TypeError, ValueError):
        return None
    lo = 0.0
    for hi in edges:
        if x < hi:
            return f"{lo:g}-{hi:g} {unit}"
        lo = hi
    return f"{lo:g}+ {unit}"


def collect(ov: Any, full: bool) -> dict[str, Any]:
    c = getattr(ov, "controller", None)
    states = ov.ha.states
    reg = getattr(c, "_ent_reg", None) or {}
    devices = getattr(c, "_devices", None) or {}
    s = ov.settings
    words = [] if full else personal_words(ov, devices, getattr(c, "_areas", None) or [])
    out_devices: list[dict[str, Any]] = []
    if c:
        for part in c.parts():
            if part == "generator":
                continue
            ents = list(c.entities.get(part) or [])
            plat = (c.platforms.get(part) if hasattr(c, "platforms") else None)
            roles = BATTERY_ROLES if c.is_battery(part) else CAR_ROLES if part == "car" else ()
            role_ents = [(r, ov.role(r)) for r in roles if part in ("battery", "car") and ov.role(r)]
            # the part's own sensors decide its platform - a solar forecast or grid meter alone is no battery
            own = [e for r, e in role_ents if r in ("battery_power", "battery_soc") + CAR_ROLES]
            if not ents and not own and not plat:
                continue
            # what each control is used for: the intents whose calls use it
            uses: dict[str, set[str]] = {}
            try:
                want = (c.intents() or {}).get(part)
                if want:
                    for intent in ("normal", "hold", "charge", "export") if c.is_battery(part) else ("charge", "stop"):
                        for call in c.calls(part, {**want, "intent": intent}) or []:
                            e = (call.get("data") or {}).get("entity_id")
                            if isinstance(e, str):
                                uses.setdefault(e, set()).add(intent)
                            elif call.get("domain") and call.get("service"):
                                uses.setdefault(f"{call['domain']}.{call['service']}", set()).add(intent)
            except Exception:  # noqa: BLE001
                pass
            first = own[0] if own else (ents[0] if ents else None)
            known = [getattr(c, "battery_device", None)] if part == "battery" else [getattr(c, "car_device", None)] if part == "car" else []
            dev = brand_device([e for _r, e in role_ents] + ents, reg, devices, plat, known)
            rows = [entity(e, role, states, reg, devices, full, words) for role, e in role_ents]
            rows += [entity(e, "+".join(sorted(uses.get(e, []))) or "control", states, reg, devices, full, words) for e in ents if e not in dict(role_ents).values()][:30]
            rows += [{"name": k, "use": "+".join(sorted(v)), "platform": k.split(".")[0]} for k, v in uses.items() if k not in states and "." in k and not k.startswith(("number.", "select.", "switch.", "button."))]
            last = (c.last.get(part) or {}) if hasattr(c, "last") else {}
            res = str(last.get("result") or "")
            errs = list(getattr(c, "part_errors", {}).get(part, []))[-3:]
            out_devices.append({
                "kind": "battery" if c.is_battery(part) else "charger", "platform": plat or ((reg.get(first or "") or {}).get("platform")),
                "profile": c.profile_key(part) if c.is_battery(part) else _charger_profile(plat, ents),
                "manufacturer": str(dev.get("manufacturer") or "")[:60], "model": str(dev.get("model") or "")[:60],
                "ok": (res == "ok") if res and c.mode(part) == "control" else None, "errors": errs, "entities": rows,
                "extra": {"mode": c.mode(part), "changed_back_1h": len((getattr(c, "drift", {}) or {}).get(part, [])),
                          "blocked": bool(c.blocked(part))},
            })
    src = str(ov.source("price") or "") if hasattr(ov, "source") else ""
    if src:
        pe = ov.role("price")
        out_devices.append({"kind": "price", "platform": (reg.get(pe or "") or {}).get("platform") or (src.split(":", 1)[1] if src.startswith("integration:") else src),
                            "entities": [entity(pe, "price", states, reg, devices, full, words)] if pe else []})
    cu = s.get("curtail") or {}
    test = (s.get("curtail_test") or {}).get("result")
    if cu.get("entity"):
        out_devices.append({"kind": "export_limit", "platform": (reg.get(cu["entity"]) or {}).get("platform"), "ok": None if test in (None, "no_sun", "no_setting") else test == "ok",
                            "errors": [f"test: {test}"] if test in ("failed", "rejected") else [],
                            "entities": [entity(cu["entity"], f"stop selling = {cu.get('value')}", states, reg, devices, full, words)]
                            + [entity(e, f"stop selling = {v}", states, reg, devices, full, words) for e, v in cu.get("extra") or [] if e in states]})
    st_test = s.get("selftest") or {}
    return {
        "devices": out_devices,
        "features": {"sell_from_battery": bool(s.get("battery_export")), "stop_selling": bool(cu.get("on")), **({"stop_selling_test": test} if test else {}),
                     "grid_charge": bool(s.get("grid_charge")), "ev_follow_sun": bool(s.get("ev_follow_sun")), "runs_cheaply": bool(s.get("things")),
                     "power_tariff": bool(s.get("power_tariff_price")), "offgrid": bool(s.get("offgrid")), "battery_targets": bool(s.get("battery_targets")),
                     "tariff": str(s.get("price_source") or s.get("tariff") or "spot")[:20]},
        "sizes": {k: v for k, v in {"battery": _bucket(s.get("battery_kwh"), [5, 10, 15, 20, 30], "kWh"),
                                    "fuse": _bucket(s.get("import_limit_kw"), [10, 15, 20, 30], "kW"),
                                    "charger": _bucket(s.get("charger_kw"), [4, 8, 12], "kW")}.items() if v},
        "counts": {k: v for k, v in {"self_test_steps": len(st_test.get("results") or []),
                                     "fixes_by_itself": len(s.get("autofix_log") or [])}.items() if v is not None},
    }

energy_pilot/sources.py:
"""What the engine can find out by itself, so a home needs nothing but its inverter or battery in Home Assistant:

- holidays (Danish, computed - Easter and all that follows from it)
- weather and sunlight for the home's location (Open-Meteo, free, no key) - also the past weeks, to learn from
- spot prices (Energi Data Service, free) with tax, grid tariff and VAT on top - the user picks the area and can
  adjust the tariff
- its own solar forecast: sunlight from the weather service times what this system makes of it (learned per hour
  of the day from its own production, so the roof's direction and shade are in it)
- a learned forecast of the house's use (gradient boosting on hour, weekday, holiday and temperature; recent weeks
  weigh most) - falls back to a simple hourly profile when there's little history

A source the home already has (Strømligning, Solcast …) is used instead: it is usually better.
"""

from __future__ import annotations

from datetime import date, datetime, timedelta
import logging
import math
import time
from typing import Any
from zoneinfo import ZoneInfo

_LOGGER = logging.getLogger(__name__)
OPEN_METEO = "https://api.open-meteo.com/v1/forecast"
EDS = "https://api.energidataservice.dk/dataset/DayAheadPrices"


# ---------- holidays ----------

def easter(year: int) -> date:
    a, b, c = year % 19, year // 100, year % 100
    d, e = b // 4, b % 4
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i, k = c // 4, c % 4
    l = (32 + 2 * e + 2 * i - h - k) % 7  # noqa: E741
    m = (a + 11 * h + 22 * l) // 451
    month = (h + l - 7 * m + 114) // 31
    day = (h + l - 7 * m + 114) % 31 + 1
    return date(year, month, day)


def holidays_dk(year: int) -> set[date]:
    e = easter(year)
    return {date(year, 1, 1), e - timedelta(days=3), e - timedelta(days=2), e, e + timedelta(days=1),
            e + timedelta(days=39), e + timedelta(days=49), e + timedelta(days=50), date(year, 6, 5),
            date(year, 12, 24), date(year, 12, 25), date(year, 12, 26), date(year, 12, 31)}


COUNTRY = "DK"  # set from Home Assistant's country at start


def is_day_off(d: date) -> bool:
    if d.weekday() >= 5:
        return True
    if COUNTRY == "DK":
        return d in holidays_dk(d.year)
    try:
        import holidays

        return d in holidays.country_holidays(COUNTRY, years=d.year)
    except Exception:  # noqa: BLE001 - unknown country: weekends only
        return False


# ---------- weather ----------

class Weather:
    """Hourly temperature, cloud cover and sunlight (W/m²): the past weeks and the next two days."""

    def __init__(self, session: Any, lat: float, lon: float, tz: ZoneInfo) -> None:
        self.session, self.lat, self.lon, self.tz = session, lat, lon, tz
        self.hours: dict[datetime, dict[str, float]] = {}
        self._at = 0.0

    async def refresh(self, past_days: int = 60) -> None:
        if time.time() - self._at < 3600 and self.hours:
            return
        params = {"latitude": f"{self.lat:.3f}", "longitude": f"{self.lon:.3f}", "timezone": str(self.tz),
                  "hourly": "temperature_2m,cloud_cover,shortwave_radiation,wind_speed_100m,wind_gusts_10m,weather_code", "past_days": str(past_days), "forecast_days": "2"}
        async with self.session.get(OPEN_METEO, params=params, timeout=30) as resp:
            resp.raise_for_status()
            data = await resp.json()
        h = data.get("hourly") or {}
        out = {}
        for i, t in enumerate(h.get("time") or []):
            when = datetime.fromisoformat(t).replace(tzinfo=self.tz)
            out[when] = {"temp": h["temperature_2m"][i], "cloud": h["cloud_cover"][i], "sun": h["shortwave_radiation"][i],
                         "wind": (h.get("wind_speed_100m") or [None] * (i + 1))[i],  # much wind: cheap power
                         "gust": (h.get("wind_gusts_10m") or [None] * (i + 1))[i],  # km/h - a storm (storm.py)
                         "code": (h.get("weather_code") or [None] * (i + 1))[i]}  # 95-99: thunderstorm
        self.hours, self._at = out, time.time()

    def at(self, when: datetime) -> dict[str, float] | None:
        return self.hours.get(when.astimezone(self.tz).replace(minute=0, second=0, microsecond=0))


# ---------- prices ----------

# Typical Danish grid tariff (kr/kWh excl. VAT) by hour - low at night, peak 17-21. Adjustable in the settings.
DEFAULT_TARIFF = {"low": 0.115, "high": 0.346, "peak": 1.038}  # Radius 2026, roughly - the user can adjust
TARIFF_HOURS = {h: ("low" if h < 6 else "peak" if 17 <= h < 21 else "high") for h in range(24)}


# Bidding zones per country (day-ahead prices), and VAT on electricity.
ZONES = {
    "DK": ["DK1", "DK2"], "SE": ["SE1", "SE2", "SE3", "SE4"], "NO": ["NO1", "NO2", "NO3", "NO4", "NO5"], "FI": ["FI"],
    "DE": ["DE-LU"], "LU": ["DE-LU"], "NL": ["NL"], "BE": ["BE"], "AT": ["AT"], "FR": ["FR"], "PL": ["PL"], "CH": ["CH"],
    "CZ": ["CZ"], "SK": ["SK"], "SI": ["SI"], "HU": ["HU"], "HR": ["HR"], "RO": ["RO"], "BG": ["BG"], "GR": ["GR"],
    "ES": ["ES"], "PT": ["PT"], "EE": ["EE"], "LV": ["LV"], "LT": ["LT"],
    "IT": ["IT-North", "IT-Centre-North", "IT-Centre-South", "IT-South", "IT-Sicily", "IT-Sardinia"],
}
VAT = {"DK": 0.25, "SE": 0.25, "NO": 0.25, "FI": 0.255, "DE": 0.19, "LU": 0.08, "NL": 0.21, "BE": 0.06, "AT": 0.20,
       "FR": 0.20, "PL": 0.23, "CH": 0.081, "CZ": 0.21, "SK": 0.23, "SI": 0.22, "HU": 0.27, "HR": 0.13, "RO": 0.19,
       "BG": 0.20, "GR": 0.06, "ES": 0.21, "PT": 0.06, "EE": 0.24, "LV": 0.21, "LT": 0.21, "IT": 0.10}
ENERGY_CHARTS = "https://api.energy-charts.info/price"
FX = "https://api.frankfurter.dev/v1/latest"
_fx: dict[str, Any] = {"at": 0.0, "rates": {}}


def price_area(lat: float, lon: float, country: str | None = None) -> str:
    """The home's bidding zone - a guess the user can change."""
    country = (country or COUNTRY or "DK").upper()
    if country == "DK":
        return "DK2" if lon >= 11.0 else "DK1"
    if country == "SE":
        return "SE1" if lat >= 66 else "SE2" if lat >= 61.5 else "SE3" if lat >= 57.2 else "SE4"
    if country == "NO":
        return "NO4" if lat >= 65 else "NO3" if lat >= 62.5 else "NO5" if lon <= 7.5 and lat >= 59.8 else "NO2" if lon <= 9 else "NO1"
    return (ZONES.get(country) or ["DE-LU"])[0]


def consumer_price(spot_mwh: float, hour: int, s: dict[str, Any], country: str | None = None) -> float:
    """What a kWh costs at home: spot + grid tariff + taxes + markup, with VAT. Spot in the local currency per MWh.
    Denmark has its tariff model built in; elsewhere the user says what is added (default: VAT only)."""
    country = (country or COUNTRY or "DK").upper()
    vat = float(s.get("vat", VAT.get(country, 0.2)))
    if country == "DK":
        tariff = {**DEFAULT_TARIFF, **(s.get("tariff") or {})}
        extra = tariff[TARIFF_HOURS[hour]] + float(s.get("system_tariff", 0.072)) + float(s.get("elafgift", 0.008)) + float(s.get("markup", 0.012))
    else:
        tariff = {"low": 0.0, "high": 0.0, "peak": 0.0, **(s.get("tariff") or {})}
        extra = tariff[TARIFF_HOURS[hour]] + float(s.get("markup", 0.0))
    return round((spot_mwh / 1000 + extra) * (1 + vat), 4)


def country_of(area: str) -> str:
    """The country a bidding zone belongs to ("SE3" -> "SE", "DE-LU" -> "DE", "IT-North" -> "IT")."""
    return area[:2].upper()


async def _rate(session: Any, currency: str) -> float:
    """EUR -> the home's currency (ECB rates, once a day)."""
    if currency == "EUR":
        return 1.0
    if time.time() - _fx["at"] > 86400 or currency not in _fx["rates"]:
        async with session.get(FX, params={"base": "EUR"}, timeout=20) as resp:
            resp.raise_for_status()
            _fx["rates"], _fx["at"] = (await resp.json()).get("rates") or {}, time.time()
    return float(_fx["rates"][currency])


async def fetch_prices(session: Any, area: str, tz: ZoneInfo, s: dict[str, Any], currency: str = "DKK") -> list[dict[str, Any]]:
    """[{start, end, price}] for today and tomorrow (as far as known), like Strømligning's "prices".
    Danish zones from Energi Data Service (in DKK), all others from energy-charts.info (EUR, converted)."""
    if not area.startswith("DK"):
        rate = await _rate(session, currency)
        day0 = datetime.now(tz).date()  # without dates it gives today only - tomorrow (out ~13:00) must be asked for
        params = {"bzn": area, "start": day0.isoformat(), "end": (day0 + timedelta(days=1)).isoformat()}
        async with session.get(ENERGY_CHARTS, params=params, timeout=30) as resp:
            resp.raise_for_status()
            data = await resp.json()
        out = []
        times, prices = data.get("unix_seconds") or [], data.get("price") or []
        step = (times[1] - times[0]) if len(times) > 1 else 3600
        for ts, eur in zip(times, prices):
            if eur is None:
                continue
            t = datetime.fromtimestamp(ts, tz)
            out.append({"start": t.isoformat(), "end": (t + timedelta(seconds=step)).isoformat(),
                        "price": consumer_price(eur * rate, t.hour, s, country_of(area))})
        return out
    start = datetime.now(tz).replace(hour=0, minute=0, second=0, microsecond=0)
    params = {"start": start.strftime("%Y-%m-%dT%H:%M"), "end": (start + timedelta(days=2)).strftime("%Y-%m-%dT%H:%M"),
              "filter": f'{{"PriceArea":["{area}"]}}', "sort": "TimeDK asc", "limit": "400"}
    async with session.get(EDS, params=params, timeout=30) as resp:
        resp.raise_for_status()
        data = await resp.json()
    out = []
    for r in data.get("records") or []:
        t = datetime.fromisoformat(r["TimeDK"]).replace(tzinfo=ZoneInfo("Europe/Copenhagen")).astimezone(tz)
        spot = r.get("DayAheadPriceDKK")
        if spot is None:
            continue
        out.append({"start": t.isoformat(), "end": (t + timedelta(minutes=15)).isoformat(), "price": consumer_price(spot, t.hour, s, "DK")})
    return out


# ---------- own solar forecast ----------

def learn_solar(pv_kw_by_hour: dict[datetime, float], weather: Weather) -> dict[int, float]:
    """kWh per (kWh/m² of sunlight) for each hour of the day - the system's size, direction and shade in one."""
    num: dict[int, float] = {}
    den: dict[int, float] = {}
    for when, kw in pv_kw_by_hour.items():
        w = weather.at(when)
        if not w or w["sun"] is None or w["sun"] < 20 or kw is None:
            continue
        sun_kwh = w["sun"] / 1000
        num[when.hour] = num.get(when.hour, 0.0) + kw * sun_kwh
        den[when.hour] = den.get(when.hour, 0.0) + sun_kwh * sun_kwh
    return {h: num[h] / den[h] for h in num if den[h] > 0.01}


def solar_forecast(factors: dict[int, float], weather: Weather, hours: list[datetime]) -> dict[datetime, float]:
    out = {}
    overall = sorted(factors.values())[len(factors) // 2] if factors else None
    for h in hours:
        w = weather.at(h)
        if not w or w["sun"] is None:
            continue
        f = factors.get(h.hour, overall)
        if f is not None:
            out[h] = round(max(0.0, f * w["sun"] / 1000), 3)
    return out


# ---------- learned house forecast ----------

class HouseModel:
    """kWh per hour from hour, weekday, day off and temperature - recent weeks weigh most."""

    def __init__(self) -> None:
        self.model: Any = None
        self.samples = 0
        self.error: float | None = None  # mean absolute error on the last week, kWh

    @staticmethod
    def features(when: datetime, temp: float | None) -> list[float]:
        return [when.hour, math.sin(when.hour / 24 * 2 * math.pi), math.cos(when.hour / 24 * 2 * math.pi),
                when.weekday(), float(is_day_off(when.date())), temp if temp is not None else 10.0]

    def train(self, rows: list[tuple[datetime, float]], weather: Weather | None, now: datetime) -> bool:
        if len(rows) < 24 * 7:
            return False
        from . import mlcheck

        if not mlcheck.ok():
            return False
        from sklearn.ensemble import GradientBoostingRegressor
        X, y, w = [], [], []
        for when, kw in rows:
            if kw is None or kw < 0 or kw > 50:
                continue
            t = (weather.at(when) or {}).get("temp") if weather else None
            X.append(self.features(when, t))
            y.append(kw)
            w.append(0.5 ** (max(0.0, (now - when).total_seconds() / 86400) / 14))
        if len(X) < 24 * 7:
            return False
        cut = max(1, len(X) - 24 * 7)
        model = GradientBoostingRegressor(n_estimators=150, max_depth=3, learning_rate=0.08, subsample=0.9)
        model.fit(X[:cut], y[:cut], sample_weight=w[:cut])
        if cut < len(X):
            pred = model.predict(X[cut:])
            self.error = round(sum(abs(p - a) for p, a in zip(pred, y[cut:])) / len(pred), 3)
        model.fit(X, y, sample_weight=w)  # then on everything
        self.model, self.samples = model, len(X)
        return True

    def predict(self, hours: list[datetime], weather: Weather | None) -> list[float] | None:
        if self.model is None:
            return None
        X = [self.features(h, (weather.at(h) or {}).get("temp") if weather else None) for h in hours]
        return [round(max(0.0, float(v)), 3) for v in self.model.predict(X)]


# ---------- own tariff plan (time of use) ----------

# Examples to start from - the user checks them against the bill (prices change).
TOU_PRESETS = {
    "day_night": {"name": "Dag/nat", "default": 0.30, "periods": [{"name": "Nat", "price": 0.20, "from": "23:00", "to": "07:00", "days": "all"}]},
    "peak_17_21": {"name": "Spidslast 17-21", "default": 0.30, "periods": [{"name": "Spids", "price": 0.55, "from": "17:00", "to": "21:00", "days": "all"}]},
    "pge_etou_c": {"name": "PG&E E-TOU-C (US)", "default": 0.42, "currency": "USD",
                   "periods": [{"name": "Peak", "price": 0.52, "from": "16:00", "to": "21:00", "days": "all"}]},
    "sce_tou_d_4_9": {"name": "SCE TOU-D-4-9PM (US)", "default": 0.33, "currency": "USD",
                      "periods": [{"name": "On-peak", "price": 0.55, "from": "16:00", "to": "21:00", "days": "weekdays"},
                                  {"name": "Mid-peak", "price": 0.43, "from": "16:00", "to": "21:00", "days": "weekends"}]},
    "economy7": {"name": "Economy 7 (UK)", "default": 0.29, "currency": "GBP",
                 "periods": [{"name": "Night", "price": 0.14, "from": "00:30", "to": "07:30", "days": "all"}]},
}


def _minutes(text: str) -> int:
    h, m = (int(x) for x in str(text).split(":")[:2])
    return h * 60 + m


def tou_price(plan: dict[str, Any], when: datetime) -> float:
    """The price at a moment from a plan: the first period that covers it, else the default."""
    m = when.hour * 60 + when.minute
    weekend = is_day_off(when.date())
    for p in plan.get("periods") or []:
        days = p.get("days", "all")
        if (days == "weekdays" and weekend) or (days == "weekends" and not weekend):
            continue
        months = p.get("months")
        if months and when.month not in months:
            continue
        a, b = _minutes(p.get("from", "00:00")), _minutes(p.get("to", "00:00"))
        if (a <= m < b) if a < b else (m >= a or m < b):
            return float(p["price"])
    return float(plan.get("default", 0))


def tou_prices(plan: dict[str, Any], tz: ZoneInfo) -> list[dict[str, Any]]:
    """Today and tomorrow in 15-minute steps, like a price sensor's "prices"."""
    start = datetime.now(tz).replace(hour=0, minute=0, second=0, microsecond=0)
    out = []
    for i in range(2 * 96):
        t = start + timedelta(minutes=15 * i)
        out.append({"start": t.isoformat(), "end": (t + timedelta(minutes=15)).isoformat(), "price": round(tou_price(plan, t), 4)})
    return out

energy_pilot/storm.py:
"""Storm watch (off unless the user turns it on): a storm or a thunderstorm on its way, and the battery is filled up
before it - in the cheapest hours before the storm, like any other charging; only what the cheap hours can't reach is
bought dearer. While it lasts the battery is kept high, so the house has power if the grid goes down. Afterwards: the
normal plan again.

A storm: gusts of at least the chosen strength (25 m/s unless changed) or a thunderstorm in the weather forecast
(Open-Meteo) within the next 36 hours - or a weather warning in Home Assistant (Meteoalarm, DMI …) that is on.
"""

from __future__ import annotations

from datetime import datetime, timedelta
from typing import Any

GUST_MS = 25.0
FULL, HOLD = 100.0, 80.0
AHEAD_H = 36
# The weather services' own warnings in Home Assistant - by integration (the entity registry), else by the entity's name.
WARN_PLATFORMS = {"meteoalarm", "dwd_weather_warnings", "meteo_france", "environment_canada", "gdacs", "nws_alerts",
                  "bureau_of_meteorology", "metservice", "met_alerts", "metoffice_warnings", "uk_weather_warnings", "nhc",
                  "nhc_atlantic", "noaa_alerts"}
WARN_IDS = ("meteoalarm", "warning", "warnings", "alert", "alerts", "varsel", "farevarsel", "nws", "bom_", "gdacs", "nhc", "weather_alert")
STORM_WORDS = ("wind", "storm", "gale", "thunder", "hurricane", "cyclone", "typhoon", "tornado", "blizzard", "squall", "gust",
               "sturm", "orkan", "gewitter", "böe", "boe", "vent violent", "orage", "tempête", "tempete", "vind", "torden", "blæst",
               "uvær", "uvaer", "åska", "aska", "kuling")
SERIOUS = ("orange", "red", "rouge", "severe", "extreme", "major", "warning", "hurricane", "cyclone", "typhoon", "unwetter", "markant")
MILD_ONLY = ("advisory", "yellow", "jaune", "gelb", "gul", "minor", "moderate")


def _text(v) -> str:
    import json

    try:
        return json.dumps(v, ensure_ascii=False, default=str).lower()
    except (TypeError, ValueError):
        return str(v).lower()


def _serious(txt: str) -> bool:
    if not any(w in txt for w in STORM_WORDS):
        return False
    return any(w in txt for w in SERIOUS)


def _start(a: dict) -> str | None:
    for k in ("onset", "Onset", "start", "warning_1_start", "effective", "begin", "from"):
        if a.get(k):
            return str(a[k])
    for x in a.get("Alerts") or a.get("alerts") or a.get("warnings") or []:
        if isinstance(x, dict):
            for k in ("Onset", "onset", "start_time", "issue_time", "start"):
                if x.get(k):
                    return str(x[k])
    return None


def _warning(states: dict[str, Any], reg: dict[str, Any] | None = None) -> dict[str, Any] | None:
    """A serious warning about wind, storm, thunder or a cyclone from the weather service, through Home Assistant:
    Meteoalarm (most of Europe), DWD (DE), Météo-France, Environment Canada, GDACS (cyclones, the whole world), NWS
    Alerts (US), BOM (AU), MetService (NZ), MET Varsler (NO), Met Office warnings (UK), NHC (hurricanes)."""
    reg = reg or {}
    for e, st in (states or {}).items():
        dom = e.split(".")[0]
        if dom not in ("binary_sensor", "sensor", "geo_location"):
            continue
        plat = (reg.get(e) or {}).get("platform")
        if plat not in WARN_PLATFORMS and not any(w in e for w in WARN_IDS):
            continue
        a = st.get("attributes") or {}
        state = str(st.get("state") or "").lower()
        if state in ("off", "unknown", "unavailable", "", "0", "none", "vert", "green", "grün", "gruen"):
            continue
        found = None
        if plat == "gdacs" or dom == "geo_location":  # a cyclone near the home
            try:
                near = float(st.get("state")) < 600
            except (TypeError, ValueError):
                near = False
            if near and any(w in _text(a.get("event_type")) for w in ("cyclone", "storm")) and any(w in _text(a.get("alert_level")) for w in ("orange", "red")):
                found = a.get("event_type") or "cyclone"
        elif plat == "dwd_weather_warnings" or "warning_level" in e:  # DWD: 2 = markant, 3 = Unwetter, 4 = extrem
            try:
                lvl = int(float(st.get("state")))
            except (TypeError, ValueError):
                lvl = 0
            kinds = [a.get(f"warning_{i}_type") for i in range(1, 6)]
            names = _text([a.get(f"warning_{i}_name") for i in range(1, 6)])
            if lvl >= 2 and (0 in kinds or 1 in kinds or any(w in names for w in STORM_WORDS)):
                found = a.get("warning_1_name") or "DWD"
        elif plat == "meteo_france" or "weather_alert" in e:  # {"Vent violent": "Orange", "Orages": "Rouge"}
            for k, v in a.items():
                if any(w in str(k).lower() for w in ("vent", "orage", "vague")) and str(v).lower() in ("orange", "rouge"):
                    found = f"{k}: {v}"
        else:  # Meteoalarm, MET, NWS, BOM, MetService, Environment Canada, Met Office, NHC: by their words
            txt = _text(a)
            lvl = _text(a.get("awareness_level") or a.get("severity") or a.get("level") or "")
            if lvl and any(w in lvl for w in MILD_ONLY) and not any(w in lvl for w in ("orange", "red", "severe", "extreme")):
                continue
            if _serious(txt):
                found = a.get("event") or a.get("headline") or a.get("title") or a.get("friendly_name") or e
        if found:
            return {"source": plat or e.split(".")[0], "text": str(found)[:80], "start": _start(a)}
    return None


def find(weather: Any, now: datetime, s: dict[str, Any], states: dict[str, Any] | None = None, reg: dict[str, Any] | None = None) -> dict[str, Any] | None:
    """The coming storm: {"from", "to", "gust" (m/s), "kind"} - the first window within 36 hours, or None."""
    thr = float(s.get("storm_gust") or GUST_MS)
    hours = sorted((getattr(weather, "hours", None) or {}).items())
    hit = []
    for t, w in hours:
        if t + timedelta(hours=1) <= now or t > now + timedelta(hours=AHEAD_H):
            continue
        gust = (float(w["gust"]) / 3.6) if w.get("gust") is not None else 0.0
        thunder = w.get("code") is not None and int(w["code"]) >= 95
        if gust >= thr or thunder:
            hit.append((t, gust, thunder))
    warn = _warning(states or {}, reg)
    if not hit and not warn:
        return None
    if not hit:  # only the warning: from its start (else now), the next 12 hours
        t0 = now
        try:
            st0 = datetime.fromisoformat(str(warn.get("start")).replace("Z", "+00:00"))
            if now < st0 < now + timedelta(hours=AHEAD_H):
                t0 = st0.astimezone(now.tzinfo)
        except (TypeError, ValueError):
            pass
        return {"from": t0.isoformat(), "to": (t0 + timedelta(hours=12)).isoformat(), "gust": None, "kind": "warning",
                "source": warn["source"], "text": warn["text"]}
    first, end, top, thunder = hit[0][0], hit[0][0], 0.0, False
    for t, g, th in hit:
        if t - end > timedelta(hours=2):
            break  # the first storm only
        end, top, thunder = t, max(top, g), thunder or th
    return {"from": first.isoformat(), "to": (end + timedelta(hours=1)).isoformat(), "gust": round(top, 1) if top else None,
            "kind": "wind" if top >= thr else "thunder", "warning": bool(warn), "source": (warn or {}).get("source"), "text": (warn or {}).get("text")}


def targets(storm: dict[str, Any] | None, s: dict[str, Any]) -> tuple:
    """The battery's levels for the planner: full when the storm comes, and kept high every hour while it lasts."""
    if not storm:
        return ()
    full = float(s.get("storm_soc") or FULL)
    hold = min(full, float(s.get("storm_hold") or HOLD))
    t0, t1 = datetime.fromisoformat(storm["from"]), datetime.fromisoformat(storm["to"])
    out = [(t0, full)]
    t = t0 + timedelta(hours=1)
    while t <= t1:
        out.append((t, hold))
        t += timedelta(hours=1)
    return tuple(out)

energy_pilot/telemetry.py:
"""Learning together: small anonymous lines that make Energy Pilot better for everyone - on unless the user turns it
off (Settings). Never names, places, entity names or use hour by hour.

Sent:
- once a day: version, Home Assistant version, country, language, which profile/charger/price source, what the house
  has (battery, car, solar …), Shadow/Control per part, days in shadow before control, saved this month (rounded),
  battery size (rounded), how well yesterday's forecasts hit, which features are on.
- after a self-test: the result per step, and what it mended (the option names the inverter itself offers).
- when something was mended by itself: only which kind (fuse, kW, price …).
- when the app itself fails: the kind of error and where in the code - once a day per error.

Answers from the developer: every hour, for 60 days after a "Get help" report or an app error was sent, the
developer's comments on it are fetched with this installation's own id and shown in the app (Settings); a new one
also gives a notification in Home Assistant - once per comment.

Fetched once a day: fixes that 3 installations with the same profile found - used here too (see control._fixed),
and how many have tested each profile.
"""

from __future__ import annotations

import asyncio
from datetime import date
import hashlib
import logging
import os
import time
import traceback
from typing import Any
import uuid

_LOGGER = logging.getLogger(__name__)
DAY_S = 24 * 3600
REPLY_DAYS = 60
FRESH_S = 7 * DAY_S  # asked every 10 minutes the first week after a report or an error, then hourly
CLOSED_KEEP_S = 7 * DAY_S  # an answer on a closed issue goes away a week after it was closed
SEEN_KEEP_S = 14 * DAY_S  # ... or two weeks after it was seen - a new comment brings it back
NEW_ANSWER = {
    "da": "💬 Ny besked fra udvikleren. Åbn Energipilot → Indstillinger for at læse den.",
    "en": "💬 New message from the developer. Open Energy Pilot → Settings to read it.",
    "de": "💬 Neue Nachricht vom Entwickler. Öffne Energy Pilot → Einstellungen, um sie zu lesen.",
    "fr": "💬 Nouveau message du développeur. Ouvrez Energy Pilot → Réglages pour le lire.",
    "nl": "💬 Nieuw bericht van de ontwikkelaar. Open Energy Pilot → Instellingen om het te lezen.",
    "sv": "💬 Nytt meddelande från utvecklaren. Öppna Energy Pilot → Inställningar för att läsa det.",
    "nb": "💬 Ny melding fra utvikleren. Åpne Energy Pilot → Innstillinger for å lese den.",
}


def _r(v: Any, step: float = 1.0) -> float | None:
    try:
        return round(round(float(v) / step) * step, 1)
    except (TypeError, ValueError):
        return None


class Telemetry:
    def __init__(self, overview: Any, url: str) -> None:
        self.ov, self.url = overview, url.rstrip("/") if url else ""
        self._errors_sent: dict[str, str] = {}
        if not self.ov.settings.get("install_id"):
            self.ov.save({"install_id": uuid.uuid4().hex, "first_seen": date.today().isoformat()})

    @property
    def on(self) -> bool:
        return bool(self.url) and self.ov.settings.get("share_anonymous", True) is not False

    # ---------- sending ----------
    async def _post(self, kind: str, payload: dict[str, Any]) -> bool:
        if not self.on:
            return False
        import aiohttp

        body = {"kind": kind, "install": self.ov.settings.get("install_id"), **payload}
        try:
            async with aiohttp.ClientSession() as s:
                async with s.post(f"{self.url}/t", json=body, headers={"x-ep-client": "energy-pilot"},
                                  timeout=aiohttp.ClientTimeout(total=20)) as r:
                    return r.status == 200
        except Exception:  # noqa: BLE001 - never in the way
            return False

    def event(self, kind: str, payload: dict[str, Any]) -> None:
        """Send in the background - never waits, never fails anything."""
        if not self.on:
            return
        try:
            asyncio.get_running_loop().create_task(self._post(kind, payload))
        except RuntimeError:
            pass

    # ---------- what is sent ----------
    def daily(self) -> dict[str, Any]:
        from . import mlcheck

        o, s = self.ov, self.ov.settings
        c = getattr(o, "controller", None)
        eng = getattr(o, "engine", None)
        f = o.flow() if hasattr(o, "flow") else {}
        modes = {p: c.mode(p) for p in c.parts()} if c else {}
        if any(m == "control" for m in modes.values()) and not s.get("first_control"):
            o.save({"first_control": date.today().isoformat()})
        try:
            days = (date.fromisoformat(s["first_control"]) - date.fromisoformat(s["first_seen"])).days if s.get("first_control") and s.get("first_seen") else None
        except ValueError:
            days = None
        src = str(o.source("price") or "") if hasattr(o, "source") else ""
        price = src.split(":", 1)[1] if src.startswith("integration:") else ("own" if eng and getattr(eng, "own_prices", None) and not o.role("price") else src or None)
        ledger, y, cap = {}, {}, None
        if eng:
            try:
                from datetime import datetime
                from zoneinfo import ZoneInfo

                ledger = eng.ledger.summary(datetime.now(ZoneInfo(o.ha.config.get("time_zone") or "UTC")))
                y = (eng.learning.summary() or {}).get("yesterday") or {}
                cap = eng.settings().capacity_kwh
            except Exception:  # noqa: BLE001
                pass
        has = (f.get("has") or {}) if isinstance(f, dict) else {}
        # No battery profile: which integration the battery's level comes from (e.g. "sunsynk") - only that name,
        # so the developer can see which inverters are worth a profile.
        bat_int = None
        if c and not c.profile_key("battery") and (soc := o.role("battery_soc") if hasattr(o, "role") else None):
            bat_int = next((e.get("platform") for e in getattr(c, "registry", None) or [] if e.get("entity_id") == soc), None)
        out = {
            "version": os.environ.get("BUILD_VERSION", "dev"), "ha": str(o.ha.config.get("version") or "")[:12],
            "country": o.ha.config.get("country"), "currency": o.ha.config.get("currency"),
            "lang": s.get("language") or o.ha.config.get("language"),
            "profile": c.profile_key("battery") if c else None, "model": getattr(c, "model", None) if c else None,
            "charger": (c.platforms.get("car") if c else None), "price": price,
            "has": {"battery": bool(has.get("battery")), "car": bool(has.get("ev")), "pv": bool(has.get("pv")),
                    "things": bool(s.get("things")), "batteries": bool(s.get("batteries"))},
            "modes": modes, "days_to_control": days,
            "saved_month": _r(ledger.get("month"), 0.5), "battery_kwh": _r(cap, 0.5),
            "sun_err": _r(y.get("sun_err_ml") or y.get("sun_err_simple"), 0.01), "house_err": _r(y.get("house_err_ml") or y.get("house_error"), 0.01),
            "sun_source": getattr(o, "sun_source", None), "ml": mlcheck.why() or "ok",
            "features": {"export": bool(s.get("battery_export")), "targets": bool(s.get("battery_targets")), "things": bool(s.get("things")),
                         "power_tariff": bool(s.get("power_tariff_price")), "offgrid": bool(s.get("offgrid"))},
        }
        if bat_int:
            out["battery_integration"] = str(bat_int)[:40]
        return out

    def test_result(self, results: list[dict[str, Any]]) -> None:
        c = getattr(self.ov, "controller", None)
        keep = ("part", "step", "result", "why", "option_from", "option_to")
        self.event("test", {"profile": c.profile_key("battery") if c else None, "model": getattr(c, "model", None) if c else None,
                            "charger": c.platforms.get("car") if c else None,
                            "results": [{k: r.get(k) for k in keep if r.get(k) is not None} for r in results]})

    def mended(self, key: str, what: str) -> None:
        self.event("autofix", {"key": f"{what}:{key.split(':', 1)[-1]}" if ":" in key else what})

    def error(self, record: logging.LogRecord) -> None:
        """The kind of error and where in Energy Pilot's own code - no message (it may hold entity names)."""
        if not record.exc_info or not record.exc_info[1]:
            return
        exc = record.exc_info[1]
        if _network(exc):
            return
        frames = [fr for fr in traceback.extract_tb(record.exc_info[2]) if "energy_pilot" in fr.filename]
        where = f"{os.path.basename(frames[-1].filename)}:{frames[-1].lineno} {frames[-1].name}" if frames else "?"
        text = f"{type(exc).__name__} at {where} ({record.name})"
        h = hashlib.sha1(text.encode()).hexdigest()[:16]
        today = date.today().isoformat()
        if self._errors_sent.get(h) == today:
            return
        self._errors_sent[h] = today
        if self.on:
            self.ov.save({"last_error": time.time()})  # a note from the developer may come back (fetch_answers)
        self.event("error", {"hash": h, "text": text, "version": os.environ.get("BUILD_VERSION", "dev")})

    # ---------- answers to "Get help" ----------
    async def _ask(self, path: str, body: dict[str, Any]) -> dict[str, Any] | None:
        import aiohttp

        try:
            async with aiohttp.ClientSession() as s:
                async with s.post(f"{self.url}{path}", json={"install": self.ov.settings.get("install_id"), **body},
                                  headers={"x-ep-client": "energy-pilot"}, timeout=aiohttp.ClientTimeout(total=30)) as r:
                    d = await r.json(content_type=None)
                    return d if r.status == 200 else {"error": d.get("error") or f"http_{r.status}"}
        except Exception:  # noqa: BLE001
            return None

    def _last_sent(self) -> float:
        return max(float((self.ov.settings.get("last_report") or {}).get("t") or 0), float(self.ov.settings.get("last_error") or 0))

    def wants_answers(self) -> bool:
        return bool(self.url) and time.time() - self._last_sent() < REPLY_DAYS * DAY_S

    def answer_every(self) -> float | None:
        if self.wants_answers():
            return 600 if time.time() - self._last_sent() < FRESH_S else 3600
        return DAY_S if self.on else None  # an error sent by an older version

    @staticmethod
    def _key(r: dict[str, Any]) -> str:
        return str(r.get("id") or "e:" + hashlib.sha1(str(r.get("error")).encode()).hexdigest()[:12])

    @staticmethod
    def _newest(r: dict[str, Any]) -> str:
        return max((str(m.get("t") or "") for m in r.get("msgs") or [] if m.get("from") == "dev"), default="")

    def visible(self, mark_seen: bool = False) -> dict[str, Any]:
        """What the page shows: not the ones closed with "Close", a closed issue after a week, or one seen two weeks ago."""
        from datetime import datetime

        got = self.ov.settings.get("replies") or {}
        hidden = dict(self.ov.settings.get("replies_hidden") or {})
        shown = dict(self.ov.settings.get("replies_shown") or {})
        now, out, changed = time.time(), {"reports": [], "notes": [], "t": got.get("t")}, False
        for kind in ("reports", "notes"):
            for r in got.get(kind) or []:
                k, new = self._key(r), self._newest(r)
                if k in hidden and hidden[k] >= new:
                    continue
                closed = r.get("closed_at")
                try:
                    if closed and datetime.fromisoformat(str(closed).replace("Z", "+00:00")).timestamp() < now - CLOSED_KEEP_S and new <= closed:
                        continue
                except ValueError:
                    pass
                sh = shown.get(k)
                if new and sh and sh.get("t") == new and now - float(sh.get("at") or 0) > SEEN_KEEP_S:
                    continue
                if mark_seen and new and (not sh or sh.get("t") != new):
                    shown[k], changed = {"t": new, "at": now}, True
                out[kind].append({**r, "key": k})
        if changed:
            keep = {self._key(r) for kind in ("reports", "notes") for r in got.get(kind) or []}
            self.ov.save({"replies_shown": {k: v for k, v in shown.items() if k in keep}})
        return out

    def hide(self, key: str) -> None:
        got = self.ov.settings.get("replies") or {}
        r = next((x for kind in ("reports", "notes") for x in got.get(kind) or [] if self._key(x) == key), None)
        if r is not None:
            self.ov.save({"replies_hidden": {**(self.ov.settings.get("replies_hidden") or {}), key: self._newest(r)}})

    # ---------- updates (the same rules as in the other apps) ----------
    @staticmethod
    def _ver(v: Any) -> tuple[int, ...]:
        import re

        return tuple(int(x) for x in re.findall(r"\d+", str(v or ""))[:3]) or (0,)

    def _fixed(self) -> list[dict[str, str]]:
        """Errors this installation had that are fixed in a newer version than it runs ("Fixed in x.y.z")."""
        import re

        cur, out = self._ver(os.environ.get("BUILD_VERSION", "dev")), []
        for n in (self.ov.settings.get("replies") or {}).get("notes") or []:
            for m in n.get("msgs") or []:
                hit = re.search(r"fixed in v?(\d+\.\d+(?:\.\d+)?)", str(m.get("text") or ""), re.I)
                if hit and self._ver(hit.group(1)) > cur:
                    out.append({"error": str(n.get("error") or "")[:120], "version": hit.group(1), "key": str(n.get("hash") or n.get("error"))[:60]})
                    break
        return out

    def update(self) -> dict[str, Any] | None:
        """The update card: small fixes once 7 days behind, new features after 2 days, at once when an error it had is fixed."""
        from datetime import datetime

        lt, cur = self.ov.settings.get("latest") or {}, os.environ.get("BUILD_VERSION", "dev")
        lv, fixed = str(lt.get("version") or ""), self._fixed()
        if not lv or cur == "dev" or self._ver(lv) <= self._ver(cur):
            return None
        now, since = time.time(), dict(self.ov.settings.get("behind") or {})
        if lv not in since:
            try:
                since[lv] = datetime.fromisoformat(str(lt.get("date"))).timestamp() if lt.get("date") else now
            except ValueError:
                since[lv] = now
            self.ov.save({"behind": {lv: since[lv]}})
        big = self._ver(lv)[:2] > self._ver(cur)[:2]
        sn = self.ov.settings.get("update_snooze") or {}
        snoozed = now < float(sn.get("until") or 0) and not (big and self._ver(lv)[:2] > self._ver(sn.get("version"))[:2])
        due = bool(fixed) or (now - float(since[lv]) >= (2 if big else 7) * DAY_S and not snoozed)
        return {"version": lv, "current": cur, "note": str(lt.get("note") or ""), "important": bool(lt.get("important")),
                "repo": str(lt.get("repo") or ""), "big": big, "fixed": fixed, "due": due}

    async def _update_notices(self) -> None:
        """A notification in Home Assistant (never on the phone): an error it had is fixed, or 30 days behind something important."""
        u = self.update()
        if not u:
            return
        da = str(self.ov.settings.get("language") or self.ov.ha.config.get("language") or "en")[:2] == "da"
        told, msgs = dict(self.ov.settings.get("update_told") or {}), []
        for f in u["fixed"]:
            if told.get("fixed:" + f["key"]) != f["version"]:
                told["fixed:" + f["key"]] = f["version"]
                msgs.append(("energy_pilot_fixed", f"✅ Fejlen, du havde i Energipilot, er rettet i version {f['version']}. Opdater i add-on-butikken." if da
                             else f"✅ The error you had in Energy Pilot is fixed in version {f['version']}. Update in the add-on store."))
        if u["important"] and time.time() - float((self.ov.settings.get("behind") or {}).get(u["version"]) or time.time()) >= 30 * DAY_S and told.get("important") != u["version"]:
            told["important"] = u["version"]
            msgs.append(("energy_pilot_update", f"⬆️ Energipilot {u['version']} har en vigtig rettelse. Opdater i add-on-butikken." if da
                         else f"⬆️ Energy Pilot {u['version']} has an important fix. Update in the add-on store."))
        if msgs:
            self.ov.save({"update_told": told})
        for nid, text in msgs:
            try:
                await self.ov.ha.call_service("persistent_notification", "create", {"notification_id": nid, "title": "Energy Pilot", "message": text})
            except Exception:  # noqa: BLE001
                pass

    def snooze(self) -> None:
        u = self.update()
        self.ov.save({"update_snooze": {"until": time.time() + 7 * DAY_S, "version": (u or {}).get("version") or os.environ.get("BUILD_VERSION", "dev")}})

    async def fetch_answers(self, notify: bool = True) -> dict[str, Any]:
        body: dict[str, Any] = {"version": os.environ.get("BUILD_VERSION", "dev")}
        if self.on:  # how it is set up - names cleaned unless "Share my setup" is on (setupinfo.py)
            try:
                from . import setupinfo

                body["setup"] = {**setupinfo.collect(self.ov, bool(self.ov.settings.get("share_full"))), "full": bool(self.ov.settings.get("share_full"))}
            except Exception:  # noqa: BLE001
                body["setup"] = {"failed": True}
        d = await self._ask("/replies", body)
        if not d or "reports" not in d:
            return self.ov.settings.get("replies") or {}
        got = {"reports": d["reports"][:5], "notes": (d.get("notes") or [])[:5], "t": time.time()}
        self._keep_sent(got)
        if isinstance(d.get("latest"), dict) and d["latest"].get("version"):
            self.ov.save({"latest": d["latest"]})
        newest = max((str(m.get("t") or "") for r in got["reports"] + got["notes"] for m in r.get("msgs") or [] if m.get("from") == "dev"), default="")
        seen = self.ov.settings.get("replies_seen")
        seen = seen if isinstance(seen, str) else ""
        self.ov.save({"replies": got, "replies_seen": max(newest, seen)})
        if notify and newest > seen:  # once per new comment - closing the issue changes nothing
            lang = str(self.ov.settings.get("language") or self.ov.ha.config.get("language") or "en")[:2]
            try:
                await self.ov.ha.call_service("persistent_notification", "create", {
                    "notification_id": "energy_pilot_answer", "title": "Energy Pilot", "message": NEW_ANSWER.get(lang, NEW_ANSWER["en"])})
            except Exception:  # noqa: BLE001
                pass
        if notify:
            await self._update_notices()
        return got

    def _keep_sent(self, got: dict[str, Any]) -> None:
        """What the user just sent is shown at once: GitHub may list a new comment only minutes later. Kept until
        GitHub has it (or an hour has gone)."""
        sent = [x for x in getattr(self, "_sent", []) if time.time() - x["t"] < 3600]
        for x in list(sent):
            r = next((r for r in got.get("reports") or [] if str(r.get("id")) == x["id"]), None)
            if r is None:
                continue
            msgs = r.setdefault("msgs", [])
            if any(m.get("from") == "you" and str(m.get("text") or "").strip() == x["text"] for m in msgs):
                sent.remove(x)  # GitHub has it now
            else:
                msgs.append({"from": "you", "text": x["text"], "t": x["iso"]})
        self._sent = sent

    async def write_back(self, report_id: str, text: str) -> dict[str, Any]:
        d = await self._ask("/reply", {"id": str(report_id)[:40], "text": str(text)[:4000]})
        if d and d.get("ok"):
            from datetime import datetime, timezone

            self._sent = getattr(self, "_sent", []) + [{"id": str(report_id)[:40], "text": str(text)[:4000].strip(), "t": time.time(),
                                                         "iso": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")}]
            got = await self.fetch_answers(notify=False)
            if "reports" in got and got.get("t", 0) < time.time() - 5:  # the fetch failed: shown from what's stored
                self._keep_sent(got)
                self.ov.save({"replies": got})
            return {"ok": True}
        return {"ok": False, "error": (d or {}).get("error", "unreachable")}

    # ---------- the daily round ----------
    async def run(self) -> None:
        """Every 10 minutes: the daily line when a day has gone, and the shared fixes once a day."""
        while True:
            try:
                now = time.time()
                if self.on and now - float(self.ov.settings.get("telemetry_sent") or 0) >= DAY_S:
                    if await self._post("daily", {"data": self.daily()}):
                        self.ov.save({"telemetry_sent": now})
                if self.url and now - float((self.ov.settings.get("community") or {}).get("t") or 0) >= DAY_S:
                    await self.fetch_fixes()
                # every 10 minutes the first week after a report or an error, hourly until 60 days, then once a day
                every = self.answer_every()
                if every and now - float((self.ov.settings.get("replies") or {}).get("t") or 0) >= every:
                    await self.fetch_answers()
            except Exception:  # noqa: BLE001
                _LOGGER.debug("Telemetry round failed", exc_info=True)
            await asyncio.sleep(600)

    async def fetch_fixes(self) -> None:
        import aiohttp

        try:
            async with aiohttp.ClientSession() as s:
                async with s.get(f"{self.url}/fixes", timeout=aiohttp.ClientTimeout(total=20)) as r:
                    if r.status != 200:
                        return
                    d = await r.json(content_type=None)
        except Exception:  # noqa: BLE001
            return
        self.ov.save({"community": {"fixes": (d.get("fixes") or [])[:500], "tested": d.get("tested") or {}, "t": time.time()}})


class ErrorHandler(logging.Handler):
    """Hands Energy Pilot's own errors (with a traceback) to telemetry."""

    def __init__(self, telemetry: Telemetry) -> None:
        super().__init__(level=logging.WARNING)
        self.t = telemetry

    def emit(self, record: logging.LogRecord) -> None:
        try:
            self.t.error(record)
        except Exception:  # noqa: BLE001
            pass


def _network(exc: BaseException) -> bool:
    """Home Assistant restarting or the network gone (502, timeout, no connection) - not a fault in the app."""
    import asyncio

    if isinstance(exc, (asyncio.TimeoutError, TimeoutError, ConnectionError)):
        return True
    try:
        import aiohttp
    except ImportError:
        return False
    if isinstance(exc, aiohttp.ClientResponseError):
        return exc.status >= 500
    return isinstance(exc, aiohttp.ClientConnectionError)

energy_pilot/tempo.py:
"""EDF Tempo (France): prices from the day colours - blue, white, red - each with off-peak and peak hours.

A Tempo day runs from 06:00 to 06:00 the next morning; off-peak ("heures creuses") is 22:00-06:00, peak ("heures
pleines") 06:00-22:00. RTE announces tomorrow's colour around 11:00, so the plan can fill the battery the night
before a red day. Read from the integration's own entities (e.g. "Tarif EDF"): today's, tomorrow's and
yesterday's colour, and the six prices. An unknown colour is left out - the plan doesn't guess a red day.
"""

from __future__ import annotations

from datetime import datetime, timedelta
import re
from typing import Any
from zoneinfo import ZoneInfo

COLOURS = {"bleu": "blue", "blue": "blue", "blanc": "white", "white": "white", "rouge": "red", "red": "red"}


def _colour(states: dict[str, dict], when: str) -> dict[str, str]:
    """{"today"/"tomorrow"/"yesterday": entity_id} of the colour sensors."""
    words = {"today": r"aujourd|today", "tomorrow": r"demain|tomorrow", "yesterday": r"hier|yesterday"}
    for e in states:
        if "tempo" in e and re.search(r"couleur|colou?r", e) and re.search(words[when], e):
            return e
    return None


def found(states: dict[str, dict]) -> bool:
    return bool(_colour(states, "today") and prices_by_colour(states))


def prices_by_colour(states: dict[str, dict]) -> dict[tuple[str, str], float]:
    """{("blue", "off"): 0.13, ("red", "peak"): 0.75, …} from the six price sensors."""
    out = {}
    for e, s in states.items():
        o = e.split(".", 1)[-1]
        if "tempo" not in o:
            continue
        c = next((COLOURS[w] for w in COLOURS if re.search(rf"(^|_){w}(_|$)", o)), None)
        part = "off" if re.search(r"creuses|off_?peak|_hc(_|$)", o) else "peak" if re.search(r"pleines|_hp(_|$)|peak", o) else None
        if c and part:
            try:
                out[(c, part)] = float(s.get("state"))
            except (TypeError, ValueError):
                pass
    return out


def colour_of(states: dict[str, dict], when: str) -> str | None:
    e = _colour(states, when)
    v = str((states.get(e) or {}).get("state") or "").strip().lower() if e else ""
    return next((COLOURS[w] for w in COLOURS if w in v), None)


def prices(states: dict[str, dict], tz: ZoneInfo, now: datetime | None = None) -> dict[datetime, float]:
    """Hour by hour from yesterday's 06:00 to the end of the last known Tempo day."""
    now = now or datetime.now(tz)
    table = prices_by_colour(states)
    day0 = now.replace(hour=0, minute=0, second=0, microsecond=0)
    out: dict[datetime, float] = {}
    for offset, when in ((-1, "yesterday"), (0, "today"), (1, "tomorrow")):
        c = colour_of(states, when)
        if not c:
            continue
        start = day0 + timedelta(days=offset, hours=6)  # the Tempo day: 06:00 -> 06:00
        for h in range(24):
            t = start + timedelta(hours=h)
            part = "off" if t.hour >= 22 or t.hour < 6 else "peak"
            if (c, part) in table:
                out[t] = table[(c, part)]
    return out

energy_pilot/things.py:
"""Things that run cheaply: small batteries (a robot mower, an e-bike, tool batteries) and machines (washing machine,
dryer, dishwasher) - run on the sun or in the cheapest hours.

They come after what matters most: the house battery and the car are planned first, and a thing only gets the sun
that is left over (what the plan would sell) or cheap hours that keep within the main fuse with the cars charging.

A battery sits on a switch (a Shelly, a smart plug): Energy Pilot switches it on in its hours and off again; when the
charger stops drawing power the battery is full - done for the day. A machine is never switched off: once the user has
said it is ready, Energy Pilot only starts it (a remote start button or switch), or tells the user when to press start.
How much each thing takes and how long is learned from the runs seen (the median of the last ten, from three runs).
"""

from __future__ import annotations

import re
from datetime import datetime, timedelta
from statistics import median
from typing import Any

MODES = ("sun_cheap", "sun", "cheap")
RUN_W = 15  # a machine above this draws power: it runs
IDLE_W = 5  # below this it rests
MACHINE_END_S = 15 * 60  # a machine resting this long has finished (a dishwasher drying can rest a few minutes)
FULL_S = 10 * 60  # a battery charger resting this long while on: the battery is full


def _hhmm(text: str | None, now: datetime) -> datetime | None:
    """The next time it is HH:MM (today or tomorrow)."""
    if not text:
        return None
    try:
        hh, mm = (int(x) for x in str(text).split(":")[:2])
    except ValueError:
        return None
    t = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
    return t if t > now else t + timedelta(days=1)


def _num(state: dict[str, Any] | None) -> float | None:
    """A power sensor's value in W."""
    if not state:
        return None
    try:
        v = float(state.get("state"))
    except (TypeError, ValueError):
        return None
    return v * 1000 if str((state.get("attributes") or {}).get("unit_of_measurement") or "").lower() == "kw" else v


class Things:
    def __init__(self, state: dict[str, Any]) -> None:
        self.s = state.setdefault("things", {})
        self.plans: dict[str, dict[str, Any]] = {}
        self._sent: dict[str, datetime] = {}
        self.aw: dict[str, dict[str, Any]] = {}  # Appliance Watch: what a usual run takes, by the machine's power sensor

    def st(self, tid: str) -> dict[str, Any]:
        return self.s.setdefault(tid, {"runs": []})

    @staticmethod
    def items(settings: dict[str, Any]) -> list[dict[str, Any]]:
        return [t for t in (settings.get("things") or []) if isinstance(t, dict) and t.get("id")]

    # ---------- what a thing takes ----------

    @staticmethod
    def from_appliance_watch(states: dict[str, Any]) -> dict[str, dict[str, Any]]:
        """Appliance Watch knows each programme from clean cycles: the usual one's minutes and kWh, by power sensor."""
        out = {}
        for s in states.values():
            a = (s or {}).get("attributes") or {}
            typ, power = a.get("typical"), a.get("power_sensor")
            if power and isinstance(typ, dict) and typ.get("minutes") and typ.get("kwh"):
                out[power] = {"kwh": float(typ["kwh"]), "min": float(typ["minutes"]), "n": int(typ.get("n") or 0),
                              "program": typ.get("program"), "source": "appliance_watch"}
        return out

    def learned(self, tid: str) -> dict[str, Any] | None:
        runs = (self.st(tid).get("runs") or [])[-10:]
        if len(runs) < 3:
            return None
        return {"kwh": round(median(r["kwh"] for r in runs), 2), "min": round(median(r["min"] for r in runs)), "n": len(self.st(tid)["runs"])}

    def need(self, t: dict[str, Any]) -> tuple[float, float, float]:
        """(kWh, minutes, kW) one run takes: Appliance Watch's usual programme, else learned here, else the settings,
        else a fair guess."""
        lr = self.aw.get(t.get("power") or "") or self.learned(t["id"])
        battery = t.get("kind") != "machine"
        kwh = lr["kwh"] if lr else float(t.get("kwh") or (0.5 if battery else 1.0))
        if lr and lr["min"] > 0:
            minutes = float(lr["min"])
        elif t.get("kw"):
            minutes = kwh / float(t["kw"]) * 60
        else:
            minutes = 240.0 if battery else 120.0
        minutes = max(10.0, minutes)
        return kwh, minutes, max(0.02, kwh / (minutes / 60))

    # ---------- the plan ----------

    def plan(self, settings: dict[str, Any], hours: list[Any], now: datetime, left: dict[datetime, float],
             load: dict[datetime, float], limit: float | None) -> list[dict[str, Any]]:
        """Each thing's hours (a battery) or start (a machine). left: the sun left over per slot (kWh) after the house,
        the battery and the cars; load: what the cars draw per slot (kW), for the main fuse."""
        out = []
        self.plans = {}
        for t in self.items(settings):
            tid, s = t["id"], self.st(t["id"])
            kwh, minutes, kw = self.need(t)
            mode = t.get("mode") if t.get("mode") in MODES else "sun_cheap"
            until = _hhmm(t.get("ready"), now) or now + timedelta(hours=24)
            ok = [h for h in hours if h.start + timedelta(hours=h.length) > now and h.start < until
                  and (limit is None or h.house / h.length + load.get(h.start, 0.0) + kw <= limit + 1e-9)]

            def sunny(h: Any) -> bool:
                return left.get(h.start, 0.0) >= kw * h.length * 0.7

            def cost(h: Any) -> float:
                return h.sell if mode != "cheap" and sunny(h) else h.price

            p: dict[str, Any] = {"id": tid, "hours": [], "start": None, "sun": False}
            if t.get("kind") == "machine":
                if s.get("armed") and not s.get("running") and not s.get("start_sent"):
                    p.update(self._machine_start(ok, now, until, minutes, kw, mode, sunny, cost))
            elif not self.full_today(tid, now):
                rest = max(0.0, kwh - float(s.get("kwh_now") or 0))
                use = [h for h in ok if mode != "sun" or sunny(h)]
                chosen, got = [], 0.0
                for h in sorted(use, key=lambda h: (cost(h), h.start)):
                    if got >= rest:
                        break
                    chosen.append(h)
                    got += kw * h.length
                p["hours"] = sorted(h.start.isoformat() for h in chosen)
                p["sun"] = bool(chosen) and all(sunny(h) for h in chosen)
                p["slot_h"] = chosen[0].length if chosen else None
            self.plans[tid] = p
            out.append(p)
        return out

    @staticmethod
    def _machine_start(ok: list[Any], now: datetime, until: datetime, minutes: float, kw: float, mode: str,
                       sunny: Any, cost: Any) -> dict[str, Any]:
        """The start that costs least for the whole run, finished by the time it must be ready."""
        run = timedelta(minutes=minutes)
        starts = sorted({max(now, h.start) for h in ok if max(now, h.start) + run <= until + timedelta(minutes=1)})
        best = None
        for s0 in starts:
            end, total, sun_all = s0 + run, 0.0, True
            for h in ok:
                a, b = max(s0, h.start), min(end, h.start + timedelta(hours=h.length))
                if b > a:
                    total += kw * (b - a).total_seconds() / 3600 * cost(h)
                    sun_all = sun_all and sunny(h)
            covered = sum(max(0.0, (min(end, h.start + timedelta(hours=h.length)) - max(s0, h.start)).total_seconds()) for h in ok)
            if covered < run.total_seconds() * 0.95 or (mode == "sun" and not sun_all):
                continue
            if best is None or total < best[0] - 1e-6:
                best = (total, s0, sun_all)
        if best is None:
            return {}
        return {"start": best[1].isoformat(), "sun": best[2], "cost": round(best[0], 2)}

    def full_today(self, tid: str, now: datetime) -> bool:
        done = self.st(tid).get("done")
        return bool(done) and datetime.fromisoformat(done).date() == now.date()

    # ---------- running them ----------

    async def tick(self, ha: Any, settings: dict[str, Any], now: datetime, price: float | None, sell: float,
                   grid_w: float | None, dt_s: float = 30, act: bool = True) -> None:
        """Every half minute: switch the batteries, start the machines, measure what they use. act=False (shadow):
        only plan, measure and learn - nothing is switched or started."""
        for t in self.items(settings):
            try:
                if t.get("kind") == "machine":
                    await self._tick_machine(ha, t, now, price, sell, grid_w, dt_s, act)
                else:
                    await self._tick_battery(ha, t, now, price, sell, grid_w, dt_s, act)
            except Exception:  # noqa: BLE001 - one thing must never stop the others
                import logging

                logging.getLogger("energy_pilot.things").debug("Thing %s failed", t.get("id"), exc_info=True)

    @staticmethod
    def _price_now(price: float | None, sell: float, grid_w: float | None) -> float:
        return sell if grid_w is not None and grid_w < 0 else (price or 0.0)  # selling now: the sun pays for it

    def _measure(self, s: dict[str, Any], w: float, now: datetime, price: float, dt_s: float) -> None:
        kwh = w / 1000 * dt_s / 3600
        s["kwh_now"] = round(float(s.get("kwh_now") or 0) + kwh, 5)
        s["cost_now"] = round(float(s.get("cost_now") or 0) + kwh * price, 5)
        s["min_now"] = round(float(s.get("min_now") or 0) + dt_s / 60, 2)

    def _finish(self, s: dict[str, Any], now: datetime) -> None:
        if float(s.get("kwh_now") or 0) >= 0.01 and float(s.get("min_now") or 0) >= 5:
            s["runs"] = (s.get("runs") or [])[-19:] + [{"kwh": round(s["kwh_now"], 3), "min": round(s["min_now"])}]
        s["last"] = {"end": now.isoformat(), "kwh": round(float(s.get("kwh_now") or 0), 2), "cost": round(float(s.get("cost_now") or 0), 2)}
        s["kwh_now"], s["cost_now"], s["min_now"], s["quiet_since"] = 0.0, 0.0, 0.0, None

    def _in_hours(self, tid: str, now: datetime) -> bool:
        p = self.plans.get(tid) or {}
        length = timedelta(hours=p.get("slot_h") or 1)
        return any(datetime.fromisoformat(x) <= now < datetime.fromisoformat(x) + length for x in p.get("hours") or [])

    async def _switch(self, ha: Any, entity: str, on: bool, now: datetime) -> bool:
        state = (ha.states.get(entity) or {}).get("state")
        if state == ("on" if on else "off"):
            return False
        last = self._sent.get(entity)
        if last and (now - last).total_seconds() < 120:
            return False  # it was just told: give it time
        self._sent[entity] = now
        await ha.call_service("homeassistant", "turn_on" if on else "turn_off", {"entity_id": entity})
        return True

    async def _tick_battery(self, ha: Any, t: dict[str, Any], now: datetime, price: float | None, sell: float,
                            grid_w: float | None, dt_s: float, act: bool = True) -> None:
        tid, s, sw = t["id"], self.st(t["id"]), t.get("switch")
        if not sw:
            return
        if s.get("done") and not self.full_today(tid, now):
            s["done"] = None  # a new day: charge again
        on = (ha.states.get(sw) or {}).get("state") == "on"
        if not on:
            s["on_by_us"] = False
        # Turned on by the user (not by Energy Pilot): left on until the battery is full - never cut off mid-charge.
        by_hand = on and not s.get("on_by_us")
        w = _num(ha.states.get(t["power"])) if t.get("power") else None
        _, minutes, kw = self.need(t)
        if on:
            self._measure(s, w if w is not None else kw * 1000, now, self._price_now(price, sell, grid_w), dt_s)
        want = (self._in_hours(tid, now) or by_hand) and not self.full_today(tid, now)
        if on and w is not None and float(s.get("min_now") or 0) >= 5:
            if w < IDLE_W:  # on, but the charger takes nothing: full (or the battery is not on it)
                s["quiet_since"] = s.get("quiet_since") or now.isoformat()
                if (now - datetime.fromisoformat(s["quiet_since"])).total_seconds() >= FULL_S:
                    s["done"] = now.isoformat()
                    self._finish(s, now)
                    want = False
            else:
                s["quiet_since"] = None
        elif on and w is None and float(s.get("min_now") or 0) >= minutes:
            s["done"] = now.isoformat()  # no power sensor: charged for as long as it takes
            self._finish(s, now)
            want = False
        if not act:
            return  # shadow: the plan is shown, nothing is switched
        if await self._switch(ha, sw, want, now) and want:
            s["on_by_us"] = True

    async def _tick_machine(self, ha: Any, t: dict[str, Any], now: datetime, price: float | None, sell: float,
                            grid_w: float | None, dt_s: float, act: bool = True) -> None:
        """A machine is never switched off: only started when it is ready and the time has come."""
        tid, s = t["id"], self.st(t["id"])
        w = _num(ha.states.get(t["power"])) if t.get("power") else None
        p = self.plans.get(tid) or {}
        if s.get("armed") and not s.get("running") and not s.get("start_sent") and p.get("start") \
                and datetime.fromisoformat(p["start"]) <= now:
            s["start_sent"] = now.isoformat()
            if (st := t.get("start")) and act:  # in shadow the user is only told
                domain = st.split(".")[0]
                if domain == "button":
                    await ha.call_service("button", "press", {"entity_id": st})
                elif domain in ("switch", "input_boolean"):
                    await ha.call_service(domain, "turn_on", {"entity_id": st})
            else:
                await ha.call_service("persistent_notification", "create", {
                    "notification_id": f"energy_pilot_{tid}", "title": "Energy Pilot",
                    "message": f"▶ {t.get('name') or 'Machine'}: start it now."})
        _, minutes, kw = self.need(t)
        running_now = (w is not None and w > RUN_W) or (w is None and s.get("start_sent") is not None)
        if running_now and not s.get("running"):
            s["running"], s["started"] = True, now.isoformat()
        if s.get("running"):
            self._measure(s, w if w is not None else kw * 1000, now, self._price_now(price, sell, grid_w), dt_s)
            ended = False
            if w is not None:
                if w < IDLE_W:
                    s["quiet_since"] = s.get("quiet_since") or now.isoformat()
                    ended = (now - datetime.fromisoformat(s["quiet_since"])).total_seconds() >= MACHINE_END_S
                else:
                    s["quiet_since"] = None
            else:
                ended = float(s.get("min_now") or 0) >= minutes
            if ended:
                if w is not None:  # the resting minutes at the end are not part of the run
                    s["min_now"] = max(0.0, float(s.get("min_now") or 0) - MACHINE_END_S / 60)
                self._finish(s, now)
                s["running"], s["armed"], s["start_sent"], s["started"] = False, False, None, None
        elif s.get("start_sent") and w is not None:
            sent = datetime.fromisoformat(s["start_sent"])
            if (now - sent).total_seconds() > 30 * 60 and not t.get("start"):
                pass  # told the user; still waiting for them to press start - keep waiting
            elif (now - sent).total_seconds() > 10 * 60 and t.get("start"):
                s["start_sent"] = None  # the start didn't take (door open, remote start off): try again next round

    def arm(self, tid: str, armed: bool) -> None:
        s = self.st(tid)
        s["armed"] = bool(armed)
        if not armed:
            s["start_sent"] = None

    # ---------- for the page ----------

    def view(self, settings: dict[str, Any], now: datetime) -> list[dict[str, Any]]:
        out = []
        for t in self.items(settings):
            tid, s = t["id"], self.st(t["id"])
            p = self.plans.get(tid) or {}
            kwh, minutes, _ = self.need(t)
            if t.get("kind") == "machine":
                status = "running" if s.get("running") else "waiting_start" if s.get("start_sent") else \
                    "planned" if s.get("armed") and p.get("start") else "armed" if s.get("armed") else \
                    "done" if s.get("last") and datetime.fromisoformat(s["last"]["end"]).date() == now.date() else "idle"
            else:
                on = bool(self._in_hours(tid, now))
                status = "full" if self.full_today(tid, now) else "charging" if on else "planned" if p.get("hours") else "idle"
            out.append({"id": tid, "name": t.get("name") or "", "icon": t.get("icon") or "", "kind": t.get("kind") or "battery",
                        "status": status, "hours": p.get("hours") or [], "start": p.get("start"), "sun": p.get("sun", False),
                        "slot_h": p.get("slot_h"), "kwh_now": round(float(s.get("kwh_now") or 0), 2), "need_kwh": round(kwh, 2),
                        "minutes": round(minutes), "learned": self.learned(tid), "last": s.get("last"),
                        "done_at": s.get("done"), "armed": bool(s.get("armed"))})
        return out


# ---------- finding them ----------

MACHINE_WORDS = re.compile(r"wash|vaske|vask_|dish|opvask|geschirr|spuel|spül|dryer|tørre|toerre|tumble|trockner|lave.?linge|"
                           r"lave.?vaisselle|seche|sèche|vaatwas|wasmachine|droger|tvatt|tvätt|disk|tork|oppvask", re.I)
BATTERY_WORDS = re.compile(r"mower|plæne|plaene|automower|rasenm|tondeuse|maaier|grasklipp|gräsklipp|gressklipp|e.?bike|"
                           r"elcykel|cykel|bike|fahrrad|velo|vélo|fiets|sykkel|tool|værktøj|vaerktoej|werkzeug|outil|gereedschap|verktyg", re.I)
NOT_THING = re.compile(r"phone|iphone|pixel|galaxy|ipad|tablet|laptop|macbook|watch|_tv|tv_|television|heat.?pump|varmepumpe|"
                       r"light|lys|lamp|inverter|growatt|battery_soc|ev_|charger|wallbox|keba|easee|zappi|car_", re.I)


ROOM_WORDS = re.compile(r"vaskerum|bryggers|laundry|utility|waschk|buanderie|wasruimte|tvättstuga|vaskerom|_room|rum_|fp300|presence|motion|sensor", re.I)
SMART_DOMAINS = ("lawn_mower", "vacuum")
START = re.compile(r"(?<!re)(?<!re_)start(?!_time)", re.I)


def icon_for(text: str) -> str:
    t = text.lower()
    for key, words in (("dish", r"dish|opvask|geschirr|vaisselle|vaatwas|disk|oppvask|spül|spuel"),
                       ("dryer", r"dryer|tørre|toerre|tumble|trockner|seche|sèche|droger|tork"),
                       ("wash", r"wash|vask|linge|wasmachine|tvatt|tvätt"),
                       ("mower", r"mower|plæne|plaene|rasenm|tondeuse|maaier|klipp"),
                       ("bike", r"bike|cykel|fahrrad|velo|vélo|fiets|sykkel"),
                       ("tool", r"tool|værktøj|vaerktoej|werkzeug|outil|gereedschap|verktyg")):
        if re.search(words, t):
            return key
    return "plug"


def find(registry: list[dict[str, Any]], devices: dict[str, dict[str, Any]], states: dict[str, Any],
         taken: set[str], dismissed: list[str]) -> list[dict[str, Any]]:
    """Machines and small batteries in Home Assistant worth offering - only what clearly is one: a machine that can be
    started or measured, a mower or bike battery on a switch. Never phones, lights, the car or the house battery."""
    by_dev: dict[str, list[dict[str, Any]]] = {}
    for e in registry:
        if e.get("disabled_by") or e.get("platform") == "mobile_app" or e["entity_id"] not in states or not e.get("device_id"):
            continue
        by_dev.setdefault(e["device_id"], []).append(e)
    out = []
    for dev, ents in by_dev.items():
        if dev in dismissed:
            continue
        d = devices.get(dev) or {}
        dname = str(d.get("name_by_user") or d.get("name") or "")
        text = " ".join([dname, str(d.get("model") or ""), str(d.get("manufacturer") or "")]
                        + [e["entity_id"] for e in ents]).lower().replace(" ", "_")
        dn = dname.lower().replace(" ", "_")
        if NOT_THING.search(dn) or ROOM_WORDS.search(dn):
            continue  # a sensor in the laundry room is not the washing machine
        ids = [e["entity_id"] for e in ents]
        if any(i in taken for i in ids) or any(i.split(".")[0] in SMART_DOMAINS for i in ids):
            continue  # a robot mower or vacuum runs its own dock: nothing to switch
        power = next((i for i in ids if i.startswith("sensor.") and (states[i].get("attributes") or {}).get("device_class") == "power"), None)
        switch = next((i for i in ids if i.startswith("switch.") and not re.search(r"child|lock|led|light|lys|sound|beep|mode|indicator", i)), None)
        if switch and not power and not re.search(r"plug|outlet|socket|stik|stikkontakt|relay|relæ|power|strom|steckdose|prise|shelly|tasmota|sonoff|grillplats|tradfri", switch + " " + text):
            switch = None  # only a switch that powers something: a smart plug or a relay
        start = next((i for i in ids if i.startswith("button.") and START.search(i)), None) or \
            next((i for i in ids if i.startswith("switch.") and re.search(r"remote_start", i)), None)
        if MACHINE_WORDS.search(dn + " " + str(d.get("model") or "").lower()) and (start or power):
            out.append({"device": dev, "kind": "machine", "name": dname or ids[0], "icon": icon_for(text), "start": start, "power": power,
                        "remote": bool(start)})
        elif BATTERY_WORDS.search(text) and switch:
            out.append({"device": dev, "kind": "battery", "name": dname or ids[0], "icon": icon_for(text), "switch": switch, "power": power})
    return sorted(out, key=lambda c: (c["kind"] != "machine", c["name"].lower()))


# ---------- what to pick from (Settings) ----------

PLUG_WORDS = re.compile(r"plug|outlet|socket|stik|stikkontakt|relay|relæ|power|strom|steckdose|prise|shelly|tasmota|sonoff|grillplats|tradfri", re.I)
NOT_SWITCH = re.compile(r"growatt|inverter|varmepumpe|heat.?pump|child|lock|led|light|lys|lamp|sound|beep|mode|indicator|display|buzzer|alarm|update|auto|ai_|schedule|night|eco|"
                        r"boost|vacation|frost|mop|wash_|dock|camera|motion|privacy", re.I)
MAIN_POWER = re.compile(r"(^|[._])(pv|ev|l1|l2|l3|net|grid|sol|solar|house|load)([._]|$)|inverter|growatt|battery|batteri|husets|phase|charger|"
                        r"lader|keba|easee|zappi|wallbox|kamst|meter|måler|maaler|gateway|elmåler", re.I)


def options(registry: list[dict[str, Any]], devices: dict[str, dict[str, Any]], states: dict[str, Any], used: set[str]) -> dict[str, Any]:
    """The switches, start buttons and power sensors that make sense for a thing - and all of them, for 'show all'."""
    by_id = {e["entity_id"]: e for e in registry}
    phones = {e["entity_id"] for e in registry if e.get("platform") == "mobile_app"}
    power_devs = {e.get("device_id") for e in registry if e["entity_id"].startswith("sensor.") and e.get("device_id")
                  and (states.get(e["entity_id"], {}).get("attributes") or {}).get("device_class") == "power"}
    smart = {e.get("device_id") for e in registry if e["entity_id"].split(".")[0] in ("lawn_mower", "vacuum", "light", "climate", "media_player")}

    def row(e: str) -> dict[str, Any]:
        return {"entity_id": e, "name": str((states[e].get("attributes") or {}).get("friendly_name") or e),
                "device": (by_id.get(e) or {}).get("device_id") or ""}

    sw_all, pw_all, switches, starts, power = [], [], [], [], []
    for e, s in states.items():
        if e in phones or e in used:
            continue
        domain = e.split(".")[0]
        dev = (by_id.get(e) or {}).get("device_id")
        if domain in ("switch", "button", "input_boolean"):
            sw_all.append(row(e))
            text = e + " " + str((s.get("attributes") or {}).get("friendly_name") or "").lower().replace(" ", "_")
            if (domain == "button" and START.search(e) or re.search(r"remote_start", e)) and not re.search(r"stream|p2p|camera|record|doorbell|ringeklokke", text):
                starts.append(row(e))
            elif domain == "switch" and not NOT_SWITCH.search(text) and dev not in smart and (dev in power_devs or PLUG_WORDS.search(text)):
                switches.append(row(e))
        elif domain == "sensor" and (s.get("attributes") or {}).get("device_class") == "power":
            pw_all.append(row(e))
            name = e + " " + str((s.get("attributes") or {}).get("friendly_name") or "").lower().replace(" ", "_")
            if not MAIN_POWER.search(name) and dev and dev not in smart:
                power.append(row(e))
    key = lambda x: x["name"].lower()  # noqa: E731
    return {"switches": sorted(switches, key=key), "starts": sorted(starts, key=key), "power": sorted(power, key=key),
            "all_switches": sorted(sw_all, key=key), "all_power": sorted(pw_all, key=key)}

standalone/devices/base.py:
"""What every device driver in the app has in common.

A driver makes the entities the Home Assistant integration for that device would make, with the same names and
units, and carries out the services Energy Pilot calls (select.select_option, number.set_value, switch.turn_on,
keba.set_current …) by talking to the device itself (Modbus TCP, UDP, the maker's cloud …).
"""

from __future__ import annotations

from typing import Any


class Device:
    platform = "unknown"  # the HA integration this driver stands in for (growatt_local, keba …)
    manufacturer = ""
    model = ""
    sw_version = "app"

    def __init__(self, device_id: str, name: str) -> None:
        self.device_id = device_id
        self.name = name
        self.entities: dict[str, dict[str, Any]] = {}  # entity_id -> attributes
        self.ha: Any = None
        self.online = True

    # ---- set up ----

    def entity(self, entity_id: str, name: str, unit: str | None = None, device_class: str | None = None,
               state_class: str | None = "measurement", **extra: Any) -> str:
        attrs: dict[str, Any] = {"friendly_name": f"{self.name} {name}"}
        if unit:
            attrs["unit_of_measurement"] = unit
        if device_class:
            attrs["device_class"] = device_class
        if state_class and entity_id.startswith("sensor.") and unit:
            attrs["state_class"] = state_class
        attrs.update(extra)
        self.entities[entity_id] = attrs
        return entity_id

    def attach(self, ha: Any) -> None:
        self.ha = ha

    def set(self, entity_id: str, state: Any, **attrs: Any) -> None:
        a = dict(self.entities.get(entity_id) or {})
        a.update(attrs)
        self.entities[entity_id] = a
        if not self.online:
            state = "unavailable"
        self.ha.publish(entity_id, state, a)

    def get(self, entity_id: str) -> Any:
        return ((self.ha.states.get(entity_id) or {}) if self.ha else {}).get("state")

    def get_float(self, entity_id: str, default: float = 0.0) -> float:
        try:
            return float(self.get(entity_id))
        except (TypeError, ValueError):
            return default

    # ---- what a driver does ----

    async def refresh(self, dt: float) -> None:
        """Read the device (dt: seconds since last time) and publish its entities."""

    async def handle_service(self, domain: str, service: str, data: dict[str, Any], ids: list[str]) -> bool:
        """Carry out a service if it is for this device. Returns True when handled."""
        mine = [e for e in ids if e in self.entities]
        if not mine:
            return False
        for e in mine:
            if domain == "select" and service == "select_option":
                await self.write(e, data.get("option"))
            elif domain == "number" and service == "set_value":
                await self.write(e, data.get("value"))
            elif domain in ("switch", "input_boolean", "homeassistant") and service in ("turn_on", "turn_off"):
                await self.write(e, "on" if service == "turn_on" else "off")
            elif domain == "button" and service == "press":
                await self.write(e, "press")
            elif domain == "time" and service == "set_value":
                await self.write(e, data.get("time"))
            else:
                return False
        return True

    async def write(self, entity_id: str, value: Any) -> None:
        """Send one setting to the device (override). The default just keeps it."""
        self.set(entity_id, value)

    def services(self) -> dict[str, list[str]]:
        """The device's own services, e.g. {"keba": ["set_current", "enable", "disable"]}."""
        return {}

    def energy_prefs(self) -> list[dict[str, Any]]:
        """Entries for HA's Energy dashboard (helps auto-discovery)."""
        return []

standalone/virtual_ha.py:
"""A small Home Assistant inside the app.

Energy Pilot's core was written for Home Assistant: it reads entities, calls services and asks the recorder for
history. This class has the same interface as energy_pilot.ha.HomeAssistant, but the entities come from the app's
own device drivers (standalone/devices). A driver makes the same entities as the Home Assistant integration for
that device would (Growatt: select.…_work_mode_priority, KEBA: keba.set_current …), so auto-discovery, the brand
profiles in adapters.py and everything else work unchanged.

Also here: a recorder (hourly means per sensor and a short state history), so learning works as it does in HA.
"""

from __future__ import annotations

import asyncio
import json
import logging
import time
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any, Callable

_LOGGER = logging.getLogger("energy_pilot.virtual_ha")

VERSION = "app"


def _iso(ts: float | None = None) -> str:
    return datetime.fromtimestamp(ts if ts is not None else time.time(), timezone.utc).isoformat()


class Recorder:
    """Hourly mean per numeric sensor (like HA's long-term statistics) and the last days' state changes."""

    KEEP_DAYS = 60
    HISTORY_DAYS = 3

    def __init__(self, data_dir: Path) -> None:
        self.file = data_dir / "app_recorder.json"
        self.hours: dict[str, dict[str, list[float]]] = {}  # entity -> {hour start (epoch s, str): [sum, n]}
        self.changes: dict[str, list[tuple[float, str]]] = {}
        self._dirty = False
        try:
            raw = json.loads(self.file.read_text())
            self.hours = raw.get("hours") or {}
            self.changes = {k: [tuple(x) for x in v] for k, v in (raw.get("changes") or {}).items()}
        except (OSError, ValueError):
            pass

    def see(self, entity_id: str, state: Any, now: float) -> None:
        try:
            v = float(state)
        except (TypeError, ValueError):
            v = None
        if v is not None and entity_id.startswith("sensor."):
            h = str(int(now // 3600 * 3600))
            row = self.hours.setdefault(entity_id, {}).setdefault(h, [0.0, 0])
            row[0] += v
            row[1] += 1
            self._dirty = True
        ch = self.changes.setdefault(entity_id, [])
        s = str(state)
        if not ch or ch[-1][1] != s:
            ch.append((now, s))
            self._dirty = True

    def seed_hour(self, entity_id: str, hour_start: float, mean: float) -> None:
        self.hours.setdefault(entity_id, {})[str(int(hour_start))] = [mean, 1]
        self._dirty = True

    def statistics(self, entity_id: str, start: float, end: float) -> list[dict[str, Any]]:
        out = []
        for h, (s, n) in sorted(self.hours.get(entity_id, {}).items(), key=lambda kv: int(kv[0])):
            t = int(h)
            if start <= t < end and n:
                out.append({"start": t * 1000, "end": (t + 3600) * 1000, "mean": s / n})
        return out

    def history(self, entity_id: str, start: float, end: float | None, include_start: bool = False) -> list[dict[str, Any]]:
        rows = self.changes.get(entity_id, [])
        end = end or time.time()
        out = [{"s": s, "lu": t, "lc": t} for t, s in rows if start <= t <= end]
        if include_start:
            before = [r for r in rows if r[0] < start]
            if before:
                out.insert(0, {"s": before[-1][1], "lu": start, "lc": start})
        return out

    def prune(self) -> None:
        cut_h = time.time() - self.KEEP_DAYS * 86400
        for e in list(self.hours):
            self.hours[e] = {h: v for h, v in self.hours[e].items() if int(h) >= cut_h}
        cut_c = time.time() - self.HISTORY_DAYS * 86400
        for e in list(self.changes):
            rows = self.changes[e]
            keep = [r for r in rows if r[0] >= cut_c]
            self.changes[e] = ([rows[len(rows) - len(keep) - 1]] if len(keep) < len(rows) else []) + keep

    def save(self) -> None:
        if not self._dirty:
            return
        self.prune()
        try:
            self.file.write_text(json.dumps({"hours": self.hours, "changes": self.changes}))
            self._dirty = False
        except OSError:
            _LOGGER.debug("Could not save the recorder", exc_info=True)


class VirtualHA:
    """Same interface as energy_pilot.ha.HomeAssistant."""

    def __init__(self, devices: list[Any] | None = None, config: dict[str, Any] | None = None,
                 data_dir: Path | None = None) -> None:
        import os

        from aiohttp import ClientSession

        self.data_dir = data_dir or Path(os.environ.get("DATA_DIR", "/data"))
        self.data_dir.mkdir(parents=True, exist_ok=True)
        self.states: dict[str, dict[str, Any]] = {}
        self.session = ClientSession()
        self.on_state: list[Callable[[str, dict | None, dict | None], None]] = []
        self._event_handlers: dict[str, list[Callable[[dict[str, Any]], None]]] = {}
        self.connected = asyncio.Event()
        self.config: dict[str, Any] = {
            "version": VERSION, "time_zone": "Europe/Copenhagen", "country": "DK", "currency": "DKK", "language": "da",
            "latitude": 55.68, "longitude": 12.57, "location_name": "Hjem", "unit_system": {"length": "km"},
        }
        self.config.update(config or {})
        self.devices: list[Any] = list(devices or [])
        self.recorder = Recorder(self.data_dir)
        self.notifications: dict[str, dict[str, Any]] = {}
        self.service_log: list[dict[str, Any]] = []  # what Energy Pilot told the devices (shown in the app)
        self._inputs: dict[str, dict[str, Any]] = {}

    # ---- the entities ----

    def _entity_owner(self, entity_id: str) -> Any | None:
        for d in self.devices:
            if entity_id in d.entities:
                return d
        return None

    def publish(self, entity_id: str, state: Any, attributes: dict[str, Any] | None = None) -> None:
        """A driver (or the app) sets an entity's state - like a state_changed event in HA."""
        now = time.time()
        old = self.states.get(entity_id)
        attrs = dict(attributes if attributes is not None else (old or {}).get("attributes") or {})
        s = "unknown" if state is None else (str(round(state, 3)) if isinstance(state, float) else str(state))
        changed = old is None or old.get("state") != s
        new = {"entity_id": entity_id, "state": s, "attributes": attrs,
               "last_changed": _iso(now) if changed else old.get("last_changed", _iso(now)),
               "last_updated": _iso(now), "context": {"id": ""}}
        self.states[entity_id] = new
        self.recorder.see(entity_id, s, now)
        if changed or old.get("attributes") != attrs:
            for cb in self.on_state:
                try:
                    cb(entity_id, old, new)
                except Exception:  # noqa: BLE001
                    _LOGGER.debug("state callback failed", exc_info=True)

    async def run(self) -> None:
        """Keep the devices' entities up to date (instead of the websocket to HA)."""
        last = time.time()
        for d in self.devices:
            d.attach(self)
        for d in self.devices:
            try:
                await d.refresh(0.0)
            except Exception:  # noqa: BLE001 - a device that can't be reached must not stop the app
                _LOGGER.warning("Device %s could not be read", d.name, exc_info=True)
        self.connected.set()
        _LOGGER.info("Virtual Home Assistant ready (%s entities, %s devices)", len(self.states), len(self.devices))
        saved = time.time()
        while True:
            await asyncio.sleep(5)
            now = time.time()
            dt = now - last
            last = now
            for d in self.devices:
                try:
                    await d.refresh(dt)
                except Exception:  # noqa: BLE001 - one device offline must not stop the others
                    _LOGGER.warning("Device %s could not be read", d.name, exc_info=True)
            if now - saved > 120:
                self.recorder.save()
                saved = now

    # ---- services ----

    async def call_service(self, domain: str, service: str, data: dict[str, Any], response: bool = False) -> Any:
        data = dict(data or {})
        if domain == "recorder" and service == "get_statistics":
            return {"response": self._statistics(data)}
        ids = data.get("entity_id")
        ids = [ids] if isinstance(ids, str) else list(ids or [])
        self.service_log.append({"t": _iso(), "domain": domain, "service": service,
                                 "data": {k: v for k, v in data.items() if k != "entity_id"}, "entity_id": ids})
        del self.service_log[:-200]
        if domain == "persistent_notification":
            nid = data.get("notification_id") or str(len(self.notifications))
            if service == "create":
                self.notifications[nid] = {"title": data.get("title"), "message": data.get("message"), "t": _iso()}
            elif service == "dismiss":
                self.notifications.pop(nid, None)
            return None
        # A driver's own services (keba.set_current …) or its entities' (select.select_option on its select)
        handled = False
        for d in self.devices:
            if await d.handle_service(domain, service, data, ids):
                handled = True
        if handled:
            return {"response": {}} if response else None
        # Helpers Energy Pilot may use (input_boolean / input_number / input_datetime …)
        if domain.startswith("input_") or domain == "homeassistant":
            for e in ids:
                st = self.states.get(e)
                if not st:
                    continue
                if service in ("turn_on", "turn_off"):
                    self.publish(e, "on" if service == "turn_on" else "off")
                elif service == "set_value":
                    self.publish(e, data.get("value"))
                elif service == "set_datetime":
                    self.publish(e, data.get("time") or data.get("datetime"))
            return None
        _LOGGER.info("No device handles %s.%s %s", domain, service, ids)
        raise RuntimeError(f"Service {domain}.{service} not found")

    def _statistics(self, data: dict[str, Any]) -> dict[str, Any]:
        def ts(v: Any) -> float:
            return datetime.fromisoformat(str(v)).timestamp()

        start = ts(data["start_time"]) if data.get("start_time") else time.time() - 30 * 86400
        end = ts(data["end_time"]) if data.get("end_time") else time.time()
        return {"statistics": {e: self.recorder.statistics(e, start, end) for e in data.get("statistic_ids") or []}}

    async def set_state(self, entity_id: str, state: Any, attributes: dict[str, Any] | None) -> None:
        self.publish(entity_id, state, attributes or {})

    async def history(self, entity_id: str, start: datetime, end: datetime | None) -> list[list[dict[str, Any]]]:
        rows = self.recorder.history(entity_id, start.timestamp(), end.timestamp() if end else None, include_start=True)
        attrs = (self.states.get(entity_id) or {}).get("attributes") or {}
        return [[{"entity_id": entity_id, "state": r["s"], "attributes": attrs,
                  "last_changed": _iso(r["lc"]), "last_updated": _iso(r["lu"])} for r in rows]]

    async def listen_event(self, event: str, cb: Callable[[dict[str, Any]], None]) -> None:
        self._event_handlers.setdefault(event, []).append(cb)

    # ---- the websocket commands Energy Pilot uses ----

    def _registry(self) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        entities, devices = [], []
        for d in self.devices:
            devices.append({"id": d.device_id, "name": d.name, "name_by_user": None, "manufacturer": d.manufacturer,
                            "model": d.model, "sw_version": d.sw_version, "area_id": None, "identifiers": [[d.platform, d.device_id]],
                            "config_entries": [d.device_id], "disabled_by": None})
            for e in d.entities:
                entities.append({"entity_id": e, "platform": d.platform, "device_id": d.device_id, "disabled_by": None,
                                 "hidden_by": None, "config_entry_id": d.device_id, "unique_id": f"{d.device_id}_{e}",
                                 "name": None, "original_name": (self.states.get(e) or {}).get("attributes", {}).get("friendly_name"),
                                 "entity_category": None, "options": {}})
        return entities, devices

    async def command(self, msg: dict[str, Any], timeout: float = 60) -> Any:
        kind = msg.get("type")
        if kind == "get_config":
            return dict(self.config)
        if kind == "get_states":
            return list(self.states.values())
        if kind == "config/entity_registry/list":
            return self._registry()[0]
        if kind == "config/entity_registry/list_for_display":
            return {"entities": [{"ei": e["entity_id"], "pl": e["platform"], "di": e["device_id"]} for e in self._registry()[0]],
                    "entity_categories": {}}
        if kind == "config/entity_registry/get":
            for e in self._registry()[0]:
                if e["entity_id"] == msg.get("entity_id"):
                    return e
            raise RuntimeError("not found")
        if kind == "config/device_registry/list":
            return self._registry()[1]
        if kind == "config/area_registry/list":
            return []
        if kind == "get_services":
            out: dict[str, dict[str, Any]] = {}
            for d in self.devices:
                for dom, svcs in d.services().items():
                    out.setdefault(dom, {}).update({s: {"fields": {}} for s in svcs})
            for dom in ("select", "number", "switch", "button", "input_boolean", "input_number", "input_datetime", "homeassistant"):
                out.setdefault(dom, {})
            return out
        if kind == "energy/get_prefs":
            src: list[dict[str, Any]] = []
            for d in self.devices:
                src.extend(d.energy_prefs())
            return {"energy_sources": src, "device_consumption": []}
        if kind == "energy/solar_forecast":
            return {}
        if kind == "history/history_during_period":
            start = datetime.fromisoformat(str(msg["start_time"])).timestamp()
            end = datetime.fromisoformat(str(msg["end_time"])).timestamp() if msg.get("end_time") else None
            return {e: self.recorder.history(e, start, end, bool(msg.get("include_start_time_state"))) for e in msg.get("entity_ids") or []}
        if kind in ("lovelace/resources",):
            return []
        if kind and (kind.startswith("lovelace/") or kind in ("fire_event", "subscribe_events")):
            return None
        raise RuntimeError(f"Unknown command {kind}")
